/*
 * The %join instruction causes the thread to wait for one child
 * to die.  If a child is already dead (and a zombie) then I reap
 * it and go on. Otherwise, I mark myself as waiting in a join so that
 * children know to wake me when they finish.
 */

static void do_join(vthread_t thr, vthread_t child)
{
      assert(child->parent == thr);
      mirror_automatic_call_outputs_if_needed_(thr, child);
      mirror_dynamic_dispatch_outputs_if_needed_(thr, child);
      mirror_object_return_if_needed_(thr, child);
      trace_context_event_("join-enter", thr, child ? child->parent_scope : 0,
                           child ? child->wt_context : 0);
      int child_type = child && child->parent_scope
                     ? child->parent_scope->get_type_code() : 0;
      __vpiScope*thr_ctx_scope = resolve_context_scope(thr ? thr->parent_scope : 0);
      __vpiScope*child_ctx_scope = resolve_context_scope(child ? child->parent_scope : 0);

	/* (A "transferred_context" hand-off branch lived here for the
	   per-block-frame model; the field had no remaining setter and the
	   2026-07 engagement census never saw it fire, so it was retired
	   with the rest of the dead recovery paths.) */
      if (child->wt_context
                 && (child_type == vpiTask || child_type == vpiFunction)
                 && thr->wt_context != thr->rd_context) {
            vvp_context_t child_context = 0;
              /* For a dynamically dispatched virtual call, the override ran in
                 a separate dispatch context that is NOT on this thread's write
                 stack; the frame that IS stacked here is the %alloc'd
                 call-site (base-scope) frame. Pop THAT frame — looking for the
                 override scope's frame finds nothing, leaving the base-scope
                 frame stuck at the write head, so the enclosing task's own
                 output store lands in the base-scope frame instead of its own.
                 That silently drops the returned value of a virtual task with
                 an `output' argument whose caller is itself an output-argument
                 task/method (the RAL get_next_item / port copy-back shape). */
            __vpiScope*pop_ctx_scope = child_ctx_scope;
            if (child->dynamic_dispatch_base_scope) {
                  __vpiScope*base_ctx_scope =
                        resolve_context_scope(child->dynamic_dispatch_base_scope);
                  if (base_ctx_scope)
                        pop_ctx_scope = base_ctx_scope;
            }
            if (pop_ctx_scope && pop_ctx_scope->has_automatic_context())
                  child_context = first_live_context_for_scope(thr->wt_context,
                                                               pop_ctx_scope);

              /* Same-scope recursive calls take the generic pop-push
                 below as well: with nested begin blocks collapsed into
                 the task frame, caller and callee frames share one owner
                 scope, so the callee frame must come OFF the write stack
                 at join — otherwise the post-join output copy-back, which
                 stores through the write chain by owner scope, hits the
                 callee frame instead of the caller's. The subsequent
                 %free finds the callee frame at the head of the read
                 chain. (The retired "join-rd-share" variant, which kept
                 the callee frame on both stacks, was only viable when a
                 per-block frame disambiguated the store target.) */
	            if (child_context) {
	                    /* Pop the child context from the write stack, then move that
	                       same context to the top of the read stack without leaving a
	                       duplicate stacked link behind. */
	                  vvp_context_t caller_rd = 0;
	                  if (child_context != thr->wt_context)
	                        ctx_stats_bump("join.pop-not-head");
	                  thr->wt_context = vvp_get_stacked_context(child_context);
	                  caller_rd = remove_context_from_stacked_chain_(thr->rd_context,
	                                                                 child_context);
	                  thr->rd_context = caller_rd;
	                  vvp_set_stacked_context(child_context, thr->rd_context);
	                  thr->rd_context = child_context;
	                  if (!thr->wt_context && thr_ctx_scope && thr_ctx_scope->has_automatic_context()
	                      && caller_rd
	                      && context_live_matches_scope_(caller_rd, thr_ctx_scope)) {
	                        thr->wt_context = caller_rd;
	                        ctx_stats_bump("join.wt-caller-restore");
	                        trace_context_event_("join-wt-caller-restore", thr,
	                                             child ? child->parent_scope : 0,
	                                             caller_rd);
	                  }
	                  trace_context_event_("join-pop-push", thr,
	                                       child ? child->parent_scope : 0,
	                                       child_context);
	            }
	      }

	      if (thr->i_am_in_function
	          && child->pending_nonlocal_jmp && child->nonlocal_target) {
	            if (!child->is_callf_child
	                && child_nonlocal_jump_matches_parent_(thr, child)) {
	                  if (flow_trace_enabled_()) {
	                        fprintf(stderr,
                                "trace flow: applying non-local join jump parent=%s child=%s origin=%s target=%p\n",
                                scope_name_or_unknown_(thr->parent_scope),
                                scope_name_or_unknown_(child->parent_scope),
                                scope_name_or_unknown_(child->nonlocal_origin_scope),
                                (void*)child->nonlocal_target);
                  }
	                  thr->pending_nonlocal_jmp = 1;
	                  thr->nonlocal_target = child->nonlocal_target;
	                  thr->nonlocal_origin_scope = child->nonlocal_origin_scope;
	                  thr->pc = child->nonlocal_target;
	            } else if (child->is_callf_child) {
	                  if (flow_trace_enabled_()) {
	                        fprintf(stderr,
	                                "trace flow: suppressing non-local join jump across callf boundary"
	                                " parent=%s child=%s origin=%s target=%p\n",
	                                scope_name_or_unknown_(thr->parent_scope),
	                                scope_name_or_unknown_(child->parent_scope),
	                                scope_name_or_unknown_(child->nonlocal_origin_scope),
	                                (void*)child->nonlocal_target);
	                  }
	            } else if (flow_trace_enabled_()) {
	                  fprintf(stderr,
	                          "trace flow: suppressing non-local join jump due to scope mismatch"
	                          " parent=%s child=%s origin=%s target=%p\n",
	                          scope_name_or_unknown_(thr->parent_scope),
	                          scope_name_or_unknown_(child->parent_scope),
	                          scope_name_or_unknown_(child->nonlocal_origin_scope),
	                          (void*)child->nonlocal_target);
            }
      }

      vthread_reap(child);
}

/*
 * DPI export runtime dispatcher (IEEE 1800-2017 35.5).
 *
 * The generated C stub for an exported SV subroutine calls one of
 * __ivl_dpi_export_call_{i,r,v} with the exported C name and a packed
 * argument buffer. These entry points are called from C that is itself
 * executing inside a %dpi/call opcode of an imported (context) DPI
 * function, so `running_thread' is the SV thread that invoked C. We run
 * the exported subroutine synchronously to completion in zero time —
 * reusing the same inline child-thread execution the M6-CALLF path uses
 * for SV->SV calls — then marshal the result back to C.
 *
 * Supported here: functions/tasks with integer atoms, scalar bit/logic,
 * shortreal/real, chandle, string, and packed-vector formals. A
 * time-consuming void export reached through an imported DPI task uses the
 * coroutine bridge; a suspending export with no such bridge is a loud sorry,
 * never a silent wrong answer.
 */
typedef union ivl_dpi_arg_u {
      int64_t i;
      double  r;
      const char*s;
      void*p;
      uint32_t*v;
} ivl_dpi_arg_t;

/* Copy exported output/inout formals from the completed SV activation into
 * the C-facing argument buffer while the activation context is still alive.
 * Both the synchronous function path and the imported-task coroutine path
 * must use this exact operation: the latter resumes on the C stack before the
 * scheduler reaps its completed child. */
static void dpi_export_copy_out_(const struct dpi_export_info_s&info,
				 int nargs, ivl_dpi_arg_t*args,
				 vector<string>&string_arg_hold,
				 vthread_t child, vthread_t caller)
{
      /* A nested C->SV->C->SV call may have populated this same hold area
	 while the child ran. Replace it only after the child completes, and size
	 it before taking any c_str pointers so later elements cannot reallocate
	 the vector. */
      string_arg_hold.clear();
      string_arg_hold.resize(info.nargs);
      running_thread = child;
      for (unsigned idx = 0 ; idx < info.nargs && (int)idx < nargs ; idx += 1) {
	    char letter = info.arg_sig[2*idx];
	    char direction = info.arg_sig[2*idx+1];
	    if (direction == 'i' || info.arg_nets[idx] == 0) continue;
	    vvp_net_t*net = info.arg_nets[idx];
	    vvp_signal_value*sv = dynamic_cast<vvp_signal_value*>(net->fil);
	    if (letter == 'f' || letter == 'r') {
		  if (sv) args[idx].r = sv->real_value();
	    } else if (letter == 's') {
		  vvp_fun_signal_string*ss =
			dynamic_cast<vvp_fun_signal_string*>(net->fil);
		  if (ss) {
			string_arg_hold[idx] = ss->get_string();
			args[idx].s = string_arg_hold[idx].c_str();
		  }
	    } else if (sv) {
		  vvp_vector4_t val;
		  sv->vec4_value(val);
		  if ((letter == 'V' || letter == 'W') && args[idx].v) {
			unsigned words = (val.size() + 31) / 32;
			for (unsigned w = 0 ; w < words ; w += 1) {
			      if (letter == 'V') args[idx].v[w] = 0;
			      else {
				    args[idx].v[2*w] = 0;
				    args[idx].v[2*w+1] = 0;
			      }
			}
			for (unsigned b = 0 ; b < val.size() ; b += 1) {
			      unsigned word = b / 32;
			      uint32_t mask = uint32_t(1) << (b % 32);
			      vvp_bit4_t bit = val.value(b);
			      if (letter == 'V') {
				    if (bit == BIT4_1) args[idx].v[word] |= mask;
			      } else {
				    if (bit == BIT4_1 || bit == BIT4_X)
					  args[idx].v[2*word] |= mask;
				    if (bit == BIT4_X || bit == BIT4_Z)
					  args[idx].v[2*word+1] |= mask;
			      }
			}
		  } else if (letter == 'g' && val.size() > 0) {
			switch (val.value(0)) {
			    case BIT4_0: args[idx].i = 0; break;
			    case BIT4_1: args[idx].i = 1; break;
			    case BIT4_Z: args[idx].i = 2; break;
			    default:     args[idx].i = 3; break;
			}
		  } else {
			uint64_t u = 0;
			for (unsigned b = 0 ; b < val.size() && b < 64 ; b += 1)
			      if (val.value(b) == BIT4_1) u |= uint64_t(1) << b;
			if (letter == 'p')
			      args[idx].p = (void*)(uintptr_t)u;
			else
			      args[idx].i = (int64_t)u;
		  }
	    }
      }
      running_thread = caller;
}

// Multi-instance export selection (H.9 / 35.5.2). Among the N records
// registered for a C name (one per instance of a multiply-instantiated
// module), pick the one whose enclosing instance matches the active
// svScope. The active scope is either an explicit svSetScope target (the
// instance scope itself) or — when a `context' import calls the export
// with no svSetScope — the import's own function scope, whose parent is
// the instance ("context-relative" default, 35.5.2). We therefore match
// the export's parent-instance scope (fs->scope) against the active scope
// AND against the active scope's parent, so both forms resolve. With no
// active scope or no match, fall back to instance 0 (warning once); a
// single-instance export always uses index 0 with no svScope needed.
static unsigned dpi_export_pick_instance_(const char*cname, unsigned n)
{
      __vpiScope*active = dpi_active_scope_;
      if (active == 0 && running_thread)
	    active = running_thread->parent_scope;

      if (active) {
	    __vpiScope*active_inst = active->scope; // enclosing instance of a
						    // context import's fn scope
	    for (unsigned i = 0 ; i < n ; i += 1) {
		  struct dpi_export_info_s info;
		  if (! dpi_export_lookup(cname, i, &info))
			continue;
		  vvp_code_t c = 0;
		  __vpiScope*fs = 0;
		  if (! compile_lookup_code_scope(info.td_label, &c, &fs)
		      || fs == 0)
			continue;
		    // fs        = the exported function's scope (inst.sub.f)
		    // fs->scope = its enclosing instance (inst.sub)
		  if (fs == active || fs->scope == active
		      || (active_inst && fs->scope == active_inst))
			return i;
	    }
      }

      static bool warned = false;
      if (!warned) {
	    fprintf(stderr, "vvp: warning: exported DPI subroutine '%s' has %u "
		    "instances but no svScope selects one; using the first. "
		    "Call svSetScope(svGetScopeFromName(\"<instance>\")) before "
		    "the call to choose (further similar warnings suppressed).\n",
		    cname, n);
	    warned = true;
      }
      return 0;
}

static bool dpi_export_run_(const char*cname, int nargs, ivl_dpi_arg_t*args,
			    int64_t*ret_i, double*ret_r, std::string*ret_s)
{
	/* IEEE 1800-2017/2023 35.9(d): once an enclosing import has been
	   disabled, C may only unwind and acknowledge it. Calling back into SV
	   again is a protocol violation. */
      if (dpi_import_call_current_ && dpi_import_call_current_->disabled) {
	    dpi_protocol_fatal_(
		  "DPI export '%s' called after imported DPI subroutine '%s' entered disabled state",
		  cname, dpi_import_call_current_->c_name);
	    return false;
      }

	/* Exported output/inout strings are simulator-owned. Keep copies outside
	   an automatic invocation context so their C pointers remain valid after
	   the child is joined and reaped, through the next DPI export call. */
      static vector<string> string_arg_hold;
      string_arg_hold.clear();

      unsigned ninst = dpi_export_count(cname);
      if (ninst == 0) {
	    fprintf(stderr, "vvp: internal error: DPI export '%s' is not "
		    "registered.\n", cname);
	    return false;
      }
      unsigned pick = (ninst > 1) ? dpi_export_pick_instance_(cname, ninst) : 0;

      struct dpi_export_info_s info;
      if (! dpi_export_lookup(cname, pick, &info)) {
	    fprintf(stderr, "vvp: internal error: DPI export '%s' instance %u "
		    "not found.\n", cname, pick);
	    return false;
      }

      vvp_code_t code = 0;
      __vpiScope*scope = 0;
      if (! compile_lookup_code_scope(info.td_label, &code, &scope)
	  || code == 0) {
	    fprintf(stderr, "vvp: error: DPI export '%s': thread definition "
		    "'%s' not found.\n", cname, info.td_label);
	    return false;
      }
      const bool is_export_task = scope->get_type_code() == vpiTask;

	// The SV caller is the thread that issued the enclosing %dpi/call.
	// On a coroutine it is coro->sv_caller — NOT running_thread, which
	// on a resume is the just-ended child thread (we are inside its
	// of_END). Using running_thread there would misparent the next
	// exported task's child to the ending thread.
      vthread_t thr = dpi_coro_current ? dpi_coro_current->sv_caller
				       : running_thread;
      if (thr == 0) {
	    fprintf(stderr, "vvp: error: exported DPI subroutine '%s' called "
		    "with no active simulation thread.\n", cname);
	    return false;
      }

      vthread_t child = vthread_new(code, scope);
      child->parent = thr;
      child->is_callf_child = 1;
      child->i_am_in_function = 1;
      thr->children.insert(child);

	/* M10-4: an automatic-lifetime export needs an argument frame of its
	   own. info.arg_nets names the STATIC prototype nets, which an
	   automatic body never reads -- it reads its per-invocation context --
	   so marshaling into them with a null context silently delivered x for
	   every argument, even on a single call. Allocate a context here, the
	   same shape %alloc gives an ordinary SV call to an automatic
	   subroutine, and hand it to the child; the child owns it and
	   release_owned_context_ frees it when the thread is reaped, so the
	   inline, coroutine and orphaned-detach paths all clean up.

	   A static-lifetime export keeps a null context and so keeps sharing
	   the one static frame. That is not a defect: IEEE 1800-2017 13.3.1
	   gives a static subroutine one copy of its arguments, so concurrent
	   invocations alias -- exactly what a plain SV static task does. */
      vvp_context_t exp_context = 0;
      if (scope->has_automatic_context()) {
	    exp_context = vthread_alloc_context(scope);
	    child->wt_context = exp_context;
	    child->rd_context = exp_context;
	    child->owns_automatic_context = 1;
	    child->owned_context = exp_context;
      }

	/* Marshal the C arguments into the subroutine's argument nets. */
      for (unsigned idx = 0 ; idx < info.nargs && (int)idx < nargs ; idx += 1) {
	    vvp_net_t*net = info.arg_nets[idx];
	    if (net == 0)
		  continue;
	    char letter = info.arg_sig[2*idx];
	    char direction = info.arg_sig[2*idx+1];
	    if (letter == 'f' || letter == 'r') {
		  vvp_send_real(vvp_net_ptr_t(net, 0),
				direction == 'o' ? 0.0 : args[idx].r,
				exp_context);
	    } else if (letter == 's') {
		  vvp_send_string(vvp_net_ptr_t(net, 0),
				  direction == 'o' ? std::string()
				  : std::string(args[idx].s ? args[idx].s : ""),
				  exp_context);
	    } else {
		  vvp_signal_value*sv = dynamic_cast<vvp_signal_value*>(net->fil);
		  unsigned wid = sv ? sv->value_size() : 64;
		  vvp_vector4_t val (
			wid, (direction == 'o'
			      && (letter == 'W' || letter == 'g'))
			     ? BIT4_X : BIT4_0);
		  if ((letter == 'V' || letter == 'W') && direction != 'o'
		      && args[idx].v) {
			for (unsigned b = 0 ; b < wid ; b += 1) {
			      unsigned word = b / 32;
			      unsigned shift = b % 32;
			      bool aval = (args[idx].v[(letter == 'W') ? 2*word
								     : word] >> shift) & 1;
			      if (letter == 'V') {
				    val.set_bit(b, aval ? BIT4_1 : BIT4_0);
			      } else {
				    bool bval = (args[idx].v[2*word+1] >> shift) & 1;
				    val.set_bit(b, !bval ? (aval ? BIT4_1 : BIT4_0)
							 : (aval ? BIT4_X : BIT4_Z));
			      }
			}
		  } else if (letter == 'g' && direction != 'o' && wid == 1) {
			switch ((unsigned)args[idx].i & 3u) {
			    case 0: val.set_bit(0, BIT4_0); break;
			    case 1: val.set_bit(0, BIT4_1); break;
			    case 2: val.set_bit(0, BIT4_Z); break;
			    default: val.set_bit(0, BIT4_X); break;
			}
		  } else if (letter != 'V' && letter != 'W'
			     && direction != 'o') {
			uint64_t u = letter == 'p'
			      ? (uint64_t)(uintptr_t)args[idx].p
			      : (uint64_t)args[idx].i;
			for (unsigned b = 0 ; b < wid ; b += 1)
			      val.set_bit(b, ((u >> (b < 64 ? b : 63)) & 1)
					  ? BIT4_1 : BIT4_0);
		  }
		  vvp_send_vec4(vvp_net_ptr_t(net, 0), val, exp_context);
	    }
      }

#ifdef IVL_HAVE_DPI_CORO
	/* Coroutine export path: a void task or function reached from an imported
	   DPI task. Let the scheduler run
	   the child across simulation time and park the coroutine until it
	   ends. The child is a normal join-child of thr (the SV thread that
	   issued the %dpi/call); resume_joining_parent_ resumes this coroutine
	   when the child ends. A void export that finishes in zero time also
	   works here (it completes in the same time step). */
      if (info.ret_sig == 'v' && dpi_coro_current) {
	    dpi_coro_s*coro = dpi_coro_current;
	    child->is_callf_child = 0;
	    child->i_am_in_function = 0;
	    child->dpi_coro = coro;
	    thr->i_am_joining = 1;
	    schedule_vthread(child, 0);   // marks the child scheduled
	    dpi_coro_yield_(coro);   // park; resumed after the child ends
	      /* resume_joining_parent_ switched us back in before it reaps the
		 completed child. Copy outputs now, while an automatic activation's
		 context and string storage are still live. This also covers a
		 zero-time exported void function reached from an imported task;
		 ret_sig alone intentionally does not distinguish that function from
		 a task. */
	    bool caller_disabled = thr->i_was_disabled;
	    if (caller_disabled)
		  dpi_import_mark_disabled_();
	    if (is_export_task && ret_i)
		  *ret_i = caller_disabled ? 1 : 0;

	    bool ok = child->i_have_ended && child->parent == thr
		  && ! vthread_is_blocked_on_wait_(child);
	      /* Values written by any disabled subroutine chain are undefined.
		 Do not expose partially written output arguments to C. */
	    if (ok && !caller_disabled)
		  dpi_export_copy_out_(info, nargs, args, string_arg_hold,
				       child, thr);
	    else
		  running_thread = thr;
	    return ok;
      }
#endif

	/* The exported subroutine is ordinary SystemVerilog that may make
	   VPI system-task calls ($display etc.), which require
	   VPI_MODE_NONE. The enclosing %dpi/call raised the mode to
	   VPI_MODE_RWSYNC (so C could call svGetScopeFromName); drop it back
	   to NONE while the SV body runs, and restore it before returning to
	   the C caller. */
      vpi_mode_t saved_vpi_mode = vpi_mode_flag;
      vpi_mode_flag = VPI_MODE_NONE;

	/* A function returns through the caller's value stack: push a
	   placeholder onto this (parent) thread and register the return slot
	   on the child, exactly as %callf/<type> does. The subroutine's
	   %ret/<type> pokes the result into that slot; we read it back off
	   our stack after the child ends. */
      unsigned ret_wid = 0;
      if (info.ret_sig == 'f' || info.ret_sig == 'r') {
	    thr->push_real(0.0);
	    child->args_real.push_back(0);
      } else if (info.ret_sig == 's') {
	    thr->push_str(std::string());
	    child->args_str.push_back(0);
      } else if (info.ret_sig != 'v') {
	    vpiScopeFunction*sfun = dynamic_cast<vpiScopeFunction*>(scope);
	    ret_wid = sfun ? sfun->get_func_width() : 32;
	    vvp_bit4_t init = sfun ? sfun->get_func_init_val() : BIT4_X;
	    thr->push_vec4(vvp_vector4_t(ret_wid, init));
	    child->args_vec4.push_back(0);
      }

	/* Run the subroutine synchronously (M6-CALLF inline model). */
        /* A synchronous export may disable its enclosing imported function.
           do_disable() then reaps this very child while vthread_run() is
           still unwinding. Hold one external pin until every status/result
           inspection below is complete. */
      vthread_run_pin_(child);
      child->is_scheduled = 1;
      vthread_run(child);
      running_thread = thr;
      unsigned guard = 0;
      while (! child->i_have_ended
	     && child->parent == thr
	     && child->is_callf_child
	     && child->is_scheduled
	     && ! vthread_is_blocked_on_wait_(child)
	       /* M10-2: a child that hit a delay is scheduled for a FUTURE
		  time. Spinning it here would run past the delay AND leave
		  the scheduler holding an event for a thread we then join
		  and free -- which later tripped assert(is_scheduled) in
		  vthread_run. Stop and report instead. */
	     && ! child->i_am_delaying) {
	    if (++guard > 1000000u)
		  break;
	    vthread_run(child);
	    running_thread = thr;
      }

      bool caller_disabled = thr->i_was_disabled;
      if (caller_disabled)
	    dpi_import_mark_disabled_();
      if (is_export_task && ret_i)
	    *ret_i = caller_disabled ? 1 : 0;

      bool body_completed = child->i_have_ended && child->parent == thr
		&& ! vthread_is_blocked_on_wait_(child);
        /* A caller disable is a successful 35.9 protocol transfer even
           though do_disable() has already severed/reaped the child link. */
      bool ok = body_completed || caller_disabled;
      bool values_defined = body_completed && !caller_disabled;

      /* DPI output and inout arguments are copy-out parameters (35.5.6).
	   Read them before joining/reaping the child, while an automatic
	   function's invocation context is still alive. */
      if (values_defined)
	    dpi_export_copy_out_(info, nargs, args, string_arg_hold, child, thr);

	/* Read the return value off this thread's stack (the slot the child
	   poked) and pop the placeholder. */
      if (info.ret_sig == 'f' || info.ret_sig == 'r') {
	    double rv = thr->peek_real(0);
	    if (values_defined && ret_r) *ret_r = rv;
	    thr->pop_real(1);
      } else if (info.ret_sig == 's') {
	    string rv = thr->peek_str(0);
	    if (values_defined && ret_s) *ret_s = rv;
	    thr->pop_str(1);
      } else if (info.ret_sig != 'v') {
	    vvp_vector4_t out = thr->peek_vec4();
	    unsigned wid = out.size();
	    uint64_t u = 0;
	    for (unsigned b = 0 ; b < wid && b < 64 ; b += 1)
		  if (out.value(b) == BIT4_1)
			u |= (uint64_t)1 << b;
	    if (info.ret_sig == 'g' && wid > 0) {
		  switch (out.value(0)) {
		      case BIT4_0: u = 0; break;
		      case BIT4_1: u = 1; break;
		      case BIT4_Z: u = 2; break;
		      default:     u = 3; break;
		  }
	    }
	    int64_t s = (int64_t) u;
	    if (info.ret_sig == 'I' && wid > 0 && wid < 64
		&& ((u >> (wid - 1)) & 1))
		  s |= ~(((int64_t)1 << wid) - 1);
	    if (values_defined && ret_i) *ret_i = s;
	    thr->pop_vec4(1);
      }

      if (body_completed) {
	    do_join(thr, child);
      } else if (caller_disabled) {
	      /* do_disable() already performed the owning reap. The external
		 run pin keeps storage alive until the unpin below. */
      } else {
	      /* Reached only when a suspending export could not be run
		 time-consuming: a value-returning function that blocked
		 (illegal — functions are zero-time), or a void export reached
		 from something other than an imported DPI task. A
		 time-consuming task reached from an imported DPI task takes
		 the coroutine path above (available on all platforms). */
	    fprintf(stderr, "vvp: sorry: exported DPI subroutine '%s' did not "
		    "complete in zero time; a time-consuming export is "
		    "supported only for a task reached from an imported DPI "
		    "task.\n",
		    cname);
	      /* M10-2: DETACH the still-running child. We are about to
		 return to the C caller, so nothing will ever join it; if it
		 kept pointing at this parent it would try to resume a frame
		 that no longer exists when it finally ends. Orphaned, it
		 simply runs to completion under the scheduler. */
	    if (! child->i_have_ended) {
		  child->is_callf_child = 0;
		  child->i_am_in_function = 0;
		  thr->children.erase(child);
		  child->parent = 0;
		  thr->i_am_joining = 0;
	    }
      }

	/* Restore the VPI mode the enclosing %dpi/call established. */
      vpi_mode_flag = saved_vpi_mode;
      vthread_run_unpin_(child);
      return ok;
}

extern "C" int64_t __ivl_dpi_export_call_i(const char*cname, int nargs,
					   ivl_dpi_arg_t*args)
{
      int64_t rv = 0;
      dpi_export_run_(cname, nargs, args, &rv, 0, 0);
      return rv;
}

extern "C" double __ivl_dpi_export_call_r(const char*cname, int nargs,
					  ivl_dpi_arg_t*args)
{
      double rv = 0.0;
      dpi_export_run_(cname, nargs, args, 0, &rv, 0);
      return rv;
}

extern "C" const char* __ivl_dpi_export_call_s(const char*cname, int nargs,
					       ivl_dpi_arg_t*args)
{
	// The returned pointer must outlive this call for the C caller to
	// read it (DPI string-return convention: valid until the next DPI
	// call). Hold it in a static buffer.
      static std::string ret_hold;
      ret_hold.clear();
      dpi_export_run_(cname, nargs, args, 0, 0, &ret_hold);
      return ret_hold.c_str();
}

extern "C" void __ivl_dpi_export_call_v(const char*cname, int nargs,
					ivl_dpi_arg_t*args)
{
      dpi_export_run_(cname, nargs, args, 0, 0, 0);
}

/* DPI disable-state protocol (IEEE 1800-2017/2023 H.8.2). */
extern "C" int svIsDisabledState(void)
{
      return dpi_import_call_current_ && dpi_import_call_current_->disabled
	    ? 1 : 0;
}

extern "C" void svAckDisabledState(void)
{
      if (!dpi_import_call_current_
	  || dpi_import_call_current_->kind != DPI_IMPORT_FUNCTION
	  || !dpi_import_call_current_->disabled) {
	    dpi_protocol_fatal_(
		  "svAckDisabledState() called without an active disabled imported DPI function");
	    return;
      }
      dpi_import_call_current_->acked = true;
}

/*
 * svScope API (IEEE 1800-2017 H.9). A svScope is a vpiHandle to an
 * instance/package scope. svGetScope returns the scope currently active
 * for DPI — the caller of the DPI import on the C stack, or the last
 * value set with svSetScope.
 */
extern "C" void*svGetScope(void)
{
      if (dpi_active_scope_)
	    return dpi_active_scope_;
      return running_thread ? running_thread->parent_scope : 0;
}

extern "C" void*svSetScope(void*scope)
{
      void*prev = svGetScope();
      dpi_active_scope_ = reinterpret_cast<__vpiScope*>(scope);
      return prev;
}

extern "C" void*svGetScopeFromName(const char*scopeName)
{
      if (scopeName == 0)
	    return 0;
      return vpi_handle_by_name(scopeName, 0);
}

extern "C" const char*svGetNameFromScope(void*scope)
{
      if (scope == 0)
	    return 0;
      return vpi_get_str(vpiName, reinterpret_cast<vpiHandle>(scope));
}

extern "C" const char*svGetFullNameFromScope(void*scope)
{
      if (scope == 0)
	    return 0;
      return vpi_get_str(vpiFullName, reinterpret_cast<vpiHandle>(scope));
}

static bool do_join_opcode(vthread_t thr)
{
      assert( !thr->i_am_joining );
      assert( !thr->children.empty());

	// Are there any children that have already ended? If so, then
	// join with that one.
      for (set<vthread_t>::iterator cur = thr->children.begin()
		 ; cur != thr->children.end() ; ++cur) {
	    vthread_t curp = *cur;
	    if (! curp->i_have_ended)
		  continue;

	      // found something!
	    do_join(thr, curp);
	    return true;
      }

	// Otherwise, tell my children to awaken me when they end,
	// then pause.
      thr->i_am_joining = 1;
      return false;
}

bool of_JOIN(vthread_t thr, vvp_code_t)
{
      return do_join_opcode(thr);
}

/*
 * This %join/detach <n> instruction causes the thread to detach
 * threads that were created by an earlier %fork.
 */
bool of_JOIN_DETACH(vthread_t thr, vvp_code_t cp)
{
      unsigned long count = cp->number;

      assert(count == thr->children.size());
      trace_context_event_("join-detach-enter", thr, 0, 0);

	      while (! thr->children.empty()) {
		    vthread_t child = *thr->children.begin();
		    assert(child->parent == thr);

		      // We cannot detach automatic tasks/functions within an
		      // automatic scope. If we try to do that, we might make
		      // a mess of the allocation of the context. Note that it
		      // is OK if the child context is distinct (See %exec_ufunc.)
		    if (child->wt_context && thr->wt_context == child->wt_context) {
			  vvp_context_t child_context = child->wt_context;
			  unordered_map<vvp_context_t, __vpiScope*>::const_iterator owner_it =
				automatic_context_owner.find(child_context);
			  __vpiScope*child_context_scope =
				(owner_it != automatic_context_owner.end())
				      ? owner_it->second : resolve_context_scope(thr->parent_scope);
                          /* Detached nested blocks keep sharing the same
                             activation frame as the parent task. Retain the
                             frame for the child and let the parent drop its
                             reference at the matching %free. */
                          ctx_stats_bump("detach.retain-shared");
                          vvp_context_t parent_context = thr->rd_context;
                          if (!parent_context || parent_context == child_context)
                                parent_context = vvp_get_stacked_context(child_context);
                          if (parent_context
                              && parent_context != child_context
                              && context_live_in_owner(parent_context)) {
                                vvp_set_stacked_context(child_context, parent_context);
                          }
                          thr->skip_free_context = child_context;
                          thr->skip_free_scope = child_context_scope;
                          if (child->owns_automatic_context
                              && child->owned_context == child_context) {
                                /* do_fork_ already gave an automatic branch a
                                   retained self-pin on child_context. Convert
                                   that ownership to a chain by retaining only
                                   the ancestors it did not own yet. Retaining
                                   the head again would leak it, while retaining
                                   only the immediate parent would undercount
                                   deeper callers that release_owned_context_
                                   subsequently walks and releases. */
                                if (!child->owned_context_is_chain) {
                                      retain_context_chain_(parent_context);
                                      child->owned_context_is_chain = 1;
                                }
                          } else {
                                /* A branch without a self-pin is acquiring the
                                   complete chain here, so retain head and every
                                   linked ancestor exactly once. */
                                retain_context_chain_(child_context);
                                child->owns_automatic_context = 1;
                                child->owned_context = child_context;
                                child->owned_context_is_chain = 1;
                          }
                          trace_context_event_("join-detach-share", thr,
                                               child ? child->parent_scope : 0,
                                               child_context);
                          /* If the shared head is an UNCONSUMED staged frame
                             -- an %alloc this thread made for the detached
                             child's hoisted call arguments (see
                             fork_child_hoist_split_ in tgt-vvp), recognizable
                             because pending_alloc still points at it and its
                             owner scope is the CALLEE's, not this thread's --
                             then the frame belongs to the child alone.
                             Leaving it at this thread's write head made the
                             next scoped store here (e.g. a later loop
                             iteration's task output copy-back) resolve
                             against a wrong-scope frame the child frees at
                             an arbitrary time: `forever begin get(ph);
                             fork process(ph); join_none end' silently
                             re-spawned with the PREVIOUS iteration's
                             argument. Restore this thread's write head to
                             its own frame. */
                          if (thr->pending_alloc_context == child_context
                              && parent_context
                              && parent_context != child_context) {
                                __vpiScope*own_scope =
                                      resolve_context_scope(thr->parent_scope);
                                if (child_context_scope && own_scope
                                    && child_context_scope != own_scope) {
                                      thr->wt_context = parent_context;
                                      thr->pending_alloc_context = 0;
                                      thr->pending_alloc_scope = 0;
                                      ctx_stats_bump("detach.unstage-wt");
                                      trace_context_event_("join-detach-unstage",
                                                           thr,
                                                           child_context_scope,
                                                           child_context);
                                }
                          }
		    }
		    if (child->i_have_ended) {
			    // If the child has already ended, then reap it.
			  vthread_reap(child);

	    } else {
		  size_t res = child->parent->children.erase(child);
		  assert(res == 1);
		  child->i_am_detached = 1;
		  thr->detached_children.insert(child);
	    }
      }

      return true;
}

/*
 * %load/ar <array-label>, <index>;
*/
bool of_LOAD_AR(vthread_t thr, vvp_code_t cp)
{
      unsigned idx = cp->bit_idx[0];
      double word;

	/* The result is 0.0 if the address is undefined. */
      if (thr->flags[4] == BIT4_1) {
	    word = 0.0;
      } else {
	    unsigned adr = thr->words[idx].w_int;
	    vvp_array_t array = resolve_runtime_array_(cp, "%load/ar");
	    word = array ? array->get_word_r(adr) : 0.0;
      }

      thr->push_real(word);
      return true;
}

static int64_t darray_canonical_index_(const vvp_darray*array,
				       int64_t declared_index)
{
      if (!array || !array->sv_uses_declared_indexing()
	  || !array->dpi_has_decl_range())
	    return declared_index;

      int left = array->dpi_decl_left();
      int right = array->dpi_decl_right();
      int low = left < right ? left : right;
      return declared_index - low;
}

template <typename ELEM>
static bool load_dar(vthread_t thr, vvp_code_t cp)
{
      int64_t adr = thr->words[3].w_int;
      vvp_net_t*net = cp->net;
      assert(net);

      vvp_fun_signal_object*obj = dynamic_cast<vvp_fun_signal_object*> (net->fun);
      assert(obj);

      vvp_darray*darray = obj->get_object().peek<vvp_darray>();
      adr = darray_canonical_index_(darray, adr);

      ELEM word;
      if (darray &&
          (adr >= 0) && (thr->flags[4] == BIT4_0) &&
          (static_cast<size_t>(adr) < darray->get_size()))
	    darray->get_word(adr, word);
      else
	    dq_default(word, obj->size());

      vthread_push(thr, word);
      return true;
}

/*
 * %load/dar/r <array-label>;
 */
bool of_LOAD_DAR_R(vthread_t thr, vvp_code_t cp)
{
      return load_dar<double>(thr, cp);
}

/*
 * %load/dar/str <array-label>;
 */
bool of_LOAD_DAR_STR(vthread_t thr, vvp_code_t cp)
{
      return load_dar<string>(thr, cp);
}

/*
 * %load/dar/vec4 <array-label>;
 */
bool of_LOAD_DAR_VEC4(vthread_t thr, vvp_code_t cp)
{
      return load_dar<vvp_vector4_t>(thr, cp);
}

/*
 * %load/dar/obj <array-label>
 *    Load an object from a dynamic array element, using integer register 3
 *    as the index. Pushes the object onto the object stack.
 */
bool of_LOAD_DAR_OBJ(vthread_t thr, vvp_code_t cp)
{
      int64_t adr = thr->words[3].w_int;
      vvp_net_t*net = cp->net;
      assert(net);

      vvp_fun_signal_object*obj = dynamic_cast<vvp_fun_signal_object*> (net->fun);
      assert(obj);

      vvp_darray*darray = obj->get_object().peek<vvp_darray>();
      adr = darray_canonical_index_(darray, adr);

      vvp_object_t word;
      if (darray &&
	  (adr >= 0) && (thr->flags[4] == BIT4_0) &&
	  (static_cast<uint64_t>(adr) <= static_cast<uint64_t>(UINT_MAX)) &&
	  (static_cast<size_t>(adr) < darray->get_size())) {
	    darray->get_word(static_cast<unsigned>(adr), word);
	      // A dynamic array of an object-backed unpacked struct records its
	      // element class type (declared_type()). A `new[]`-allocated
	      // element starts nil; materialize it as a default-constructed
	      // object on first access so a member write `da[i].field = ...`
	      // (and a member/%p read) addresses a live instance instead of
	      // storing through a null handle. Class-handle darrays carry no
	      // element type, so their nil elements correctly stay null.
	      //
	      // Bounds guard: materialize ONLY within the container's current
	      // size. Queues share this opcode (and, since they also record
	      // declared_type, an out-of-bounds READ like q[5] on a 2-element
	      // queue would otherwise set_word(5) and silently GROW the queue
	      // to 6 elements — IEEE 1800-2017 7.10.2: an out-of-range queue
	      // read returns the default value and must not modify the queue).
	    if (word.test_nil() && obj->declared_type()) {
		  word = vvp_object_t(new vvp_cobject(obj->declared_type()));
		  darray->set_word(static_cast<unsigned>(adr), word);
	    }
      }
      // else word remains nil (default-constructed vvp_object_t)

      thr->push_object(word);
      return true;
}

/*
 * %load/dar/obj/vec4 <index>
 *    Read a vec4 from the darray object on top of the object stack at
 *    index words[cp->number].  Does not pop the object stack.
 */
bool of_LOAD_DAR_OBJ_VEC4(vthread_t thr, vvp_code_t cp)
{
      int64_t adr = thr->words[cp->number].w_int;

      vvp_object_t&top = thr->peek_object();
      vvp_darray*darray = top.peek<vvp_darray>();
      adr = darray_canonical_index_(darray, adr);

      vvp_vector4_t word;
      if (darray && (adr >= 0) && (thr->flags[4] == BIT4_0))
            darray->get_word((unsigned)adr, word);


      thr->push_vec4(word);
      return true;
}

