/*
 * L-value variant of the object-backed associative-array element load. On the
 * WRITE path a member assignment `a[key].field = ...` must address the element
 * stored in the map. For a missing (or nil) object-backed element the read
 * variant above pushes a discarded default, so the store is lost; here we
 * instead materialize a live default instance of the element's declared type
 * and insert it into the map before pushing it — mirroring the darray l-value
 * path (of_LOAD_DAR_OBJ). Read paths keep get-or-default (no insert), so
 * reading a non-existent element does not create it.
 */
template <class KEY, class ASSOC>
static bool aa_load_signal_obj_lval(vthread_t thr, vvp_net_t*net)
{
      KEY key = pop_assoc_key_<KEY>(thr);

      vvp_object_t value;
      ASSOC*assoc = peek_signal_assoc_<ASSOC>(net);
      bool have = assoc && assoc->get(key, value);
      bool changed = false;

      if (assoc && (!have || value.test_nil())) {
	    vvp_fun_signal_object*obj =
		  dynamic_cast<vvp_fun_signal_object*>(net->fun);
	    if (obj && obj->declared_type()) {
		  value = vvp_object_t(new vvp_cobject(obj->declared_type()));
		  assoc->set(key, value);
		  changed = true;
	    }
      }

      if (changed)
	    notify_mutated_object_signal_(thr, net, "aa-loadlv-sig-object");
      assoc_trace_signal_load_(thr, net, assoc, key, value);
      vvp_fun_signal_object*fun = signal_object_fun_(net);
      vvp_object_t root = fun ? fun->peek_object() : vvp_object_t();
      thr->push_object(value, net, root);
      return true;
}

static vvp_object_t make_queue_for_enc_(const char*text);

/*
 * %aa/loadlv/o/q/<keytype> "<elem-enc>"
 *
 * Get-or-create load of a QUEUE-valued associative element through an
 * assoc receiver on the OBJECT stack (mutation contexts like
 * c.aq[key].push_back(v) — a plain %aa/load/obj/* returns nil for a
 * missing key and the mutation is silently dropped). Pops the key,
 * PEEKS the assoc receiver, and pushes the element; a missing or nil
 * element is first created as an empty queue of the encoded element
 * kind and stored under the key.
 */
template <typename KEY>
static bool aa_loadlv_o_queue(vthread_t thr, const char*enc)
{
      KEY key = pop_assoc_key_<KEY>(thr);

      vvp_net_t*root_net = thr->peek_object_source_net(0);
      vvp_object_t root_obj = thr->peek_object_root(0);
      vvp_object_t recv = thr->peek_object();
      vvp_object_t value;
      vvp_assoc_object*assoc = peek_assoc_receiver_<vvp_assoc_object>(thr);
      bool have = assoc && assoc->get(key, value);
      bool changed = false;

      if (assoc && (!have || value.test_nil())) {
	    value = make_queue_for_enc_(enc);
	    if (!value.test_nil()) {
		  assoc->set(key, value);
		  changed = true;
	    }
      }

      if (changed)
	    notify_mutated_object_root_(thr, recv, root_net, root_obj,
					"aa-loadlv-object-queue");
      if (root_obj.test_nil())
	    root_obj = recv;
      thr->push_object(value, root_net, root_obj);
      return true;
}

/*
 * %qdar/loadlv/o "<elem-enc>"
 *
 * Get-or-create load of a QUEUE-valued POSITIONAL container element
 * (queue-of-queue or darray-of-queue) for mutation contexts like
 * dq[i].push_back(v). A plain element load returns nil for a fresh
 * element and the mutation is dropped downstream with only a runtime
 * warning (recovery D14) — but per IEEE 1800-2017 7.5/7.9 container
 * elements are VALUES: a fresh element is an empty queue, not null.
 * Pops the outer container (index in words[3], canonical); a nil
 * element within range is created as an empty queue of the encoded
 * element kind and stored back. Out-of-range or undefined-index
 * (flag 4) loads push nil, keeping the plain-load OOB semantics.
 * The outer's provenance is carried onto the pushed element so the
 * following mutation still notifies the source variable.
 */
bool of_QDAR_LOADLV_O(vthread_t thr, vvp_code_t cp)
{
      int64_t adr = thr->words[3].w_int;

      vvp_net_t*src_net = thr->peek_object_source_net(0);
      vvp_object_t src_root = thr->peek_object_root(0);

      vvp_object_t recv;
      thr->pop_object(recv);
      vvp_darray*arr = recv.peek<vvp_darray>();

      vvp_object_t value;
      bool changed = false;
      adr = darray_canonical_index_(arr, adr);
      if (arr && (adr >= 0) && (thr->flags[4] == BIT4_0)
	  && (static_cast<size_t>(adr) < arr->get_size())) {
	    arr->get_word((unsigned)adr, value);
	    if (value.test_nil()) {
		  value = make_queue_for_enc_(cp->text);
		  if (!value.test_nil()) {
			arr->set_word((unsigned)adr, value);
			changed = true;
		  }
	    }
      }

      if (src_root.test_nil())
	    src_root = recv;
      if (changed)
	    notify_mutated_object_root_(thr, recv, src_net, src_root,
					"qdar-loadlv");
      thr->push_object(value, src_net, src_root);
      return true;
}

bool of_AA_LOADLV_O_Q_OBJ(vthread_t thr, vvp_code_t cp)
{
      return aa_loadlv_o_queue<vvp_object_t>(thr, cp->text);
}

