/*
 * %load/obj <var-label>
 */
bool of_LOAD_OBJ(vthread_t thr, vvp_code_t cp)
{
      vvp_net_t*net = cp->net;
      vvp_fun_signal_object*fun = signal_object_fun_(net);
      if (!fun) {
	    static bool warned_missing_fun = false;
	    if (!warned_missing_fun) {
		  cerr << thr->get_fileline()
		       << "Warning: %load/obj without object functor; pushing nil"
		       << " (further similar warnings suppressed)." << endl;
		  warned_missing_fun = true;
	    }
	    vvp_object_t nil;
	    thr->push_object(nil);
	    return true;
      }

      vvp_object_t val = fun->get_object();
      vvp_net_t*root_net = fun->get_root_net();
      vvp_object_t root_obj = fun->get_root_object();
      if (!root_net || root_obj.test_nil()) {
            root_net = net;
            root_obj = val;
      }

      static int trace_store_obj_enabled = -1;
      if (trace_store_obj_enabled < 0) {
            const char*env = getenv("IVL_STORE_OBJ_TRACE");
            trace_store_obj_enabled = (env && *env && strcmp(env, "0") != 0) ? 1 : 0;
      }
      if (trace_store_obj_enabled) {
            const char*scope_name = (thr && thr->parent_scope)
                                  ? vpi_get_str(vpiFullName, thr->parent_scope) : 0;
            const char*env = getenv("IVL_STORE_OBJ_TRACE");
            bool trace_this = true;
            if (env && *env
                && strcmp(env, "1") != 0 && strcmp(env, "ALL") != 0 && strcmp(env, "*") != 0) {
                  trace_this = (scope_name && strstr(scope_name, env));
            }
            if (trace_this) {
                  const char*fun_kind = "other";
                  if (net->fun) {
                        if (dynamic_cast<vvp_fun_signal_object_sa*>(net->fun))
                              fun_kind = "object_sa";
                        else if (dynamic_cast<vvp_fun_signal_object_aa*>(net->fun))
                              fun_kind = "object_aa";
                  }
                  fprintf(stderr,
                          "trace load_obj  scope=%s net=%p fun=%s val_nil=%d val=%p class=%s wt=%p rd=%p\n",
                          scope_name ? scope_name : "<unknown>",
                          (void*)net, fun_kind, val.test_nil() ? 1 : 0,
                          val.peek<vvp_object>(),
                          object_trace_class_(val),
                          thr ? thr->wt_context : 0, thr ? thr->rd_context : 0);
            }
      }

      thr->push_object(val, root_net, root_obj);

      return true;
}

/*
 * %load/obja <index>
 *    Loads the object from array, using index <index> as the index
 *    value. If flags[4] == 1, the calculation of <index> may have
 *    failed, so push nil.
 */
/*
 * %load/arr/dar <array>, <kind>
 *
 * M10-1: marshal a WHOLE fixed-size unpacked array into a dynamic array
 * and push it as an object.
 *
 * A fixed array is not an object, so using one where an object is wanted --
 * `d = a' for a dynamic array d (IEEE 1800-2017 7.6), or passing it to a
 * DPI open-array formal (35.5.6.1) -- needs a dynamic-array copy of its
 * words. tgt-vvp used to push element 0 instead, so both produced an EMPTY
 * array; then it was a sorry. This makes the copy.
 *
 * The element kind is a packed NUMBER, not a string, because vvp_code_s
 * keeps `array' and `text' in the same union -- an OA_STRING operand would
 * silently clobber the array pointer resolved by OA_ARR_PTR. Layout:
 *
 *    0                       -> real elements
 *    bits  7..0  = width bits 7..0
 *    bit   8     = signed
 *    bit   9     = 4-state (logic) rather than 2-state (bit)
 *    bit  10     = the declared range DESCENDS (left > right)
 *    bit  11     = object (class handle) elements
 *    bit  12     = string elements
 *    bit  13     = materialize a queue rather than a dynamic array
 *    bits 29..14 = width bits 23..8
 *
 * The flags retain their original positions. Older VVP images, which left
 * bits 14..29 zero and therefore supported widths through 255, decode without
 * translation; newer images extend the width in previously unused bits.
 *
 * For a dynamic-array result, bit_idx[1] carries the declared LEFT bound, so
 * the marshaled array can report its source array's range through the
 * open-array accessors rather than always looking like [0:N-1]. For a queue
 * result it instead carries the destination maximum element count (zero is
 * unbounded); queues always use 0..N-1 indexes.
 *
 * 2-state elements become vvp_darray_atom<T>, whose storage is contiguous
 * so the DPI open-array accessors can hand out raw pointers. 4-state
 * elements become vvp_darray_vec4, preserving x/z at the cost of
 * contiguity; the DPI path rejects non-atom elements upstream with its own
 * sorry, so that only affects plain SV assignment.
 */
# define ARRDAR_WIDTH(k)  (((k) & 0xFFu) \
			 | (((((k) >> 14) & 0xFFFFu)) << 8))
# define ARRDAR_SIGNED(k) (((k) >> 8) & 1u)
# define ARRDAR_FOUR(k)   (((k) >> 9) & 1u)
# define ARRDAR_DESC(k)   (((k) >> 10) & 1u)
# define ARRDAR_OBJ(k)    (((k) >> 11) & 1u)
# define ARRDAR_STRING(k) (((k) >> 12) & 1u)
# define ARRDAR_QUEUE(k)  (((k) >> 13) & 1u)
/* Real has a zero type payload; direction/container-kind bits may be set. */
# define ARRDAR_REAL(k)   (((k) & ~((1u << 10) | (1u << 13))) == 0u)

/* Build one LEAF container of `count' elements for a packed element
   descriptor. Shared by the flat and the multi-dimensional marshalers
   so the two cannot drift on element representation. */
static vvp_darray* arrdar_leaf_(uint32_t kind, size_t count)
{
      unsigned wid = ARRDAR_WIDTH(kind);
      bool is_signed = ARRDAR_SIGNED(kind) != 0;

      if (ARRDAR_QUEUE(kind)) {
	    if (ARRDAR_OBJ(kind))
		  return new vvp_queue_object;
	    if (ARRDAR_STRING(kind))
		  return new vvp_queue_string;
	    if (ARRDAR_REAL(kind))
		  return new vvp_queue_real;
	      /* Queue integral elements use the vec4 representation for both
	       * 2-state and 4-state values; each appended word retains its exact
	       * descriptor width. */
	    return new vvp_queue_vec4;
      }

      if (ARRDAR_OBJ(kind))
	      /* Class-handle elements: the words are handles, copied by
		 reference exactly as an element-wise assignment would. */
	    return new vvp_darray_object(count);
      if (ARRDAR_STRING(kind))
	    return new vvp_darray_string(count);
      if (ARRDAR_REAL(kind))
	    return new vvp_darray_real(count);
      if (ARRDAR_FOUR(kind))
	    return new vvp_darray_vec4(count, wid ? wid : 1);
      if (wid <= 8)
	    return is_signed ? (vvp_darray*)new vvp_darray_atom<int8_t>(count)
			     : (vvp_darray*)new vvp_darray_atom<uint8_t>(count);
      if (wid <= 16)
	    return is_signed ? (vvp_darray*)new vvp_darray_atom<int16_t>(count)
			     : (vvp_darray*)new vvp_darray_atom<uint16_t>(count);
      if (wid <= 32)
	    return is_signed ? (vvp_darray*)new vvp_darray_atom<int32_t>(count)
			     : (vvp_darray*)new vvp_darray_atom<uint32_t>(count);
      if (wid <= 64)
	    return is_signed ? (vvp_darray*)new vvp_darray_atom<int64_t>(count)
			     : (vvp_darray*)new vvp_darray_atom<uint64_t>(count);
	/* Wider than an atom: keep the value rather than truncate. */
      return new vvp_darray_vec4(count, wid);
}

/* Fixed unpacked storage is canonical numeric-low first, while ordinary
 * SystemVerilog array assignment maps source and destination left-to-right
 * (IEEE 1800-2017/2023 7.6). Materialized container values therefore use
 * left-to-right order at every dimension. The declared ranges remain passive
 * metadata; %store/obj/open applies this involution a second time before
 * activating the numeric-canonical view required by the DPI C ABI. */
static void reverse_descending_fixed_dimensions_(vvp_darray*array)
{
      if (!array || !array->dpi_has_decl_range())
	    return;

      if (array->dpi_decl_left() > array->dpi_decl_right()) {
	    size_t count = array->get_size();
	    qreverse_dispatch_(array);
	      /* qreverse_dispatch_ carries queue-member identity itself. These
	       * fixed-derived dynamic arrays also carry per-element random state
	       * and captured references, so move that metadata with the values. */
	    if (!dynamic_cast<vvp_queue*>(array)) {
		  vector<size_t> permutation(count);
		  for (size_t idx = 0 ; idx < count ; idx += 1)
			permutation[idx] = count - 1 - idx;
		  array->reorder_element_refs(permutation);
		  array->reorder_rand_modes(permutation);
	    }
      }

      vvp_darray_object*objects = dynamic_cast<vvp_darray_object*>(array);
      if (!objects)
	    return;

      for (size_t idx = 0 ; idx < objects->get_size() ; idx += 1) {
	    vvp_object_t word;
	    objects->get_word((unsigned)idx, word);
	    reverse_descending_fixed_dimensions_(word.peek<vvp_darray>());
      }
}

static size_t fixed_copy_source_index_(
      const vvp_darray*source, bool destination_descending, size_t index,
      size_t count)
{
      /* A DPI open-array formal is activated over numeric-canonical fixed
	 * storage. Ordinary dynamic arrays and queues are left-to-right values.
	 * A descending fixed destination therefore reverses only the ordinary
	 * source at each unpacked dimension. */
      bool canonical_dpi_view = source && source->sv_uses_declared_indexing()
	    && source->dpi_has_decl_range();
      if (!canonical_dpi_view && destination_descending)
	    return count - 1 - index;
      return index;
}

static bool load_arr_dar_window_(vthread_t thr, vvp_code_t cp,
				 vvp_array_t array, size_t base, size_t count,
				 int left, unsigned queue_max_size,
				 const char*opcode)
{
      uint32_t kind = cp->bit_idx[0];

      if (!array) {
	    thr->push_object(vvp_object_t());   // nil
	    return true;
      }

      size_t array_count = array->get_size();
      if (count == 0 || base > array_count || count > array_count - base) {
	    cerr << thr->get_fileline() << "RUN-TIME ERROR: " << opcode
		 << " window base=" << base << " count=" << count
		 << " is outside an unpacked array of size " << array_count
		 << "." << endl;
	    thr->push_object(vvp_object_t());
	    return true;
      }

      bool is_real = ARRDAR_REAL(kind);
      bool is_string = ARRDAR_STRING(kind) != 0;
      vvp_object_t obj = vvp_object_t(arrdar_leaf_(kind, count));

      vvp_darray*dar = obj.peek<vvp_darray>();
      vvp_queue*queue = ARRDAR_QUEUE(kind) ? obj.peek<vvp_queue>() : 0;
	/* A bounded queue assignment retains the source prefix that fits. Do
	 * not attempt extra push_back operations: those are user mutations and
	 * warn at the bound, whereas whole-queue assignment truncates here. */
      if (!queue)
	    queue_max_size = 0;
      size_t copy_count = count;
      if (queue_max_size && copy_count > queue_max_size)
	    copy_count = queue_max_size;
      for (size_t idx = 0 ; dar && idx < copy_count ; idx += 1) {
	      /* Fixed-array storage is canonical-index ordered. Every value
	       * container is ordered from its logical left edge, so a descending
	       * source is read from the opposite storage end. */
	    size_t source_idx = base
		+ (ARRDAR_DESC(kind) ? count - 1 - idx : idx);
	    if (ARRDAR_OBJ(kind)) {
		  vvp_object_t w;
		  array->get_word_obj((unsigned)source_idx, w);
		  if (queue)
			queue->push_back(w, queue_max_size);
		  else
			dar->set_word((unsigned)idx, w);
	    } else if (is_string) {
		  string w = array->get_word_str((unsigned)source_idx);
		  if (queue)
			queue->push_back(w, queue_max_size);
		  else
			dar->set_word((unsigned)idx, w);
	    } else if (is_real) {
		  double w = array->get_word_r((unsigned)source_idx);
		  if (queue)
			queue->push_back(w, queue_max_size);
		  else
			dar->set_word((unsigned)idx, w);
	    } else {
		  vvp_vector4_t w = array->get_word((unsigned)source_idx);
		  if (queue)
			queue->push_back(w, queue_max_size);
		  else
			dar->set_word((unsigned)idx, w);
	    }
      }

	/* Record the source array's declared range so the DPI open-array
	   accessors report it instead of 0..N-1. */
      if (dar && count > 0 && !queue) {
	    int span = (int)count - 1;
	    int right = ARRDAR_DESC(kind) ? (left - span) : (left + span);
	    dar->dpi_set_decl_range(left, right);
      }

      thr->push_object(obj);
      return true;
}

bool of_LOAD_ARR_DAR(vthread_t thr, vvp_code_t cp)
{
      vvp_array_t array = resolve_runtime_array_(cp, "%load/arr/dar");
      size_t count = array ? array->get_size() : 0;
      uint32_t kind = cp->bit_idx[0];
      unsigned second = cp->bit_idx[1];
      int left = ARRDAR_QUEUE(kind) ? 0 : (int)(int32_t)second;
      unsigned queue_max_size = ARRDAR_QUEUE(kind) ? second : 0;
      return load_arr_dar_window_(thr, cp, array, 0, count, left,
				  queue_max_size, "%load/arr/dar");
}

bool of_LOAD_ARR_DAR_SLICE(vthread_t thr, vvp_code_t cp)
{
      if (thr->array_slice_stack.empty()) {
	    cerr << thr->get_fileline()
		 << "RUN-TIME ERROR: %load/arr/dar/slice has no preceding "
		    "%slice/push descriptor." << endl;
	    thr->push_object(vvp_object_t());
	    return true;
      }

      pair<size_t,size_t> window = thr->array_slice_stack.back();
      thr->array_slice_stack.pop_back();
      vvp_array_t array = resolve_runtime_array_(cp, "%load/arr/dar/slice");
      int left = (int)(int32_t)cp->bit_idx[1];
      return load_arr_dar_window_(thr, cp, array, window.first,
				  window.second, left, 0,
				  "%load/arr/dar/slice");
}

/*
 * %store/arr/dar <array>, <kind>
 *
 * The inverse of %load/arr/dar: unmarshal a dynamic array or queue back
 * into a WHOLE fixed-size unpacked array, popping the container off the
 * object stack. <kind> is the same packed element descriptor.
 *
 * Every legal whole-aggregate copy in the container -> fixed direction
 * reaches this one instruction: the 7.6 assignment `fa = da', a struct
 * member `s.arr = da', and the 13.5.2 copy-back of an `inout'/`ref'/
 * `output' open-array formal into a fixed-array actual. The opposite
 * direction has had %load/arr/dar since M10-1; this side was missing, so
 * elaboration rejected the assignment forms outright and the subroutine
 * forms reached the code generator as an untyped store -- an ivl abort
 * for a task and a silently skipped copy-out for a function.
 *
 * IEEE 1800-2017 7.6 requires the element counts to agree. A dynamic
 * source's size is not known until run time, so the check is here: a
 * mismatch is reported and the destination is left alone rather than
 * partially overwritten.
 */
static bool store_arr_dar_window_(vthread_t thr, vvp_code_t cp,
				  const vvp_object_t&val, vvp_array_t array,
				  size_t base, size_t count,
				  const char*opcode)
{
      if (!array)
	    return true;

      uint32_t kind = cp->bit_idx[0];
      size_t array_count = array->get_size();
      vvp_darray*dar = val.peek<vvp_darray>();
      size_t source_count = dar ? dar->get_size() : 0;
      if (count == 0 || base > array_count || count > array_count - base) {
	    cerr << thr->get_fileline() << "RUN-TIME ERROR: " << opcode
		 << " window base=" << base << " count=" << count
		 << " is outside an unpacked array of size " << array_count
		 << "; the array is unchanged." << endl;
	    return true;
      }
      if (!dar || source_count != count) {
	    cerr << "RUN-TIME ERROR: cannot copy a container of size "
		 << source_count << " into an unpacked array of size "
		 << count << " (IEEE 1800-2017/2023 7.6 requires equal element "
		    "counts); the array is unchanged." << endl;
	    return true;
      }

      for (size_t idx = 0 ; idx < count ; idx += 1) {
	    size_t source_idx = fixed_copy_source_index_(
		  dar, ARRDAR_DESC(kind) != 0, idx, count);
	    if (ARRDAR_OBJ(kind)) {
		  vvp_object_t w;
		  dar->get_word((unsigned)source_idx, w);
		  array->set_word((unsigned)(base + idx), w);
	    } else if (ARRDAR_STRING(kind)) {
		  string w;
		  dar->get_word((unsigned)source_idx, w);
		  array->set_word((unsigned)(base + idx), w);
	    } else if (ARRDAR_REAL(kind)) {
		  double w = 0.0;
		  dar->get_word((unsigned)source_idx, w);
		  array->set_word((unsigned)(base + idx), w);
	    } else {
		  vvp_vector4_t w;
		  dar->get_word((unsigned)source_idx, w);
		  unsigned wid = ARRDAR_WIDTH(kind);
		  if (wid && w.size() != wid)
			w = coerce_to_width(w, wid);
		  array->set_word((unsigned)(base + idx), 0, w);
	    }
      }

      return true;
}

bool of_STORE_ARR_DAR(vthread_t thr, vvp_code_t cp)
{
      vvp_object_t val;
      thr->pop_object(val);
      vvp_array_t array = resolve_runtime_array_(cp, "%store/arr/dar");
      size_t count = array ? array->get_size() : 0;
      return store_arr_dar_window_(thr, cp, val, array, 0, count,
				   "%store/arr/dar");
}

bool of_STORE_ARR_DAR_SLICE(vthread_t thr, vvp_code_t cp)
{
      vvp_object_t val;
      thr->pop_object(val);

      if (thr->array_slice_stack.empty()) {
	    cerr << thr->get_fileline()
		 << "RUN-TIME ERROR: %store/arr/dar/slice has no preceding "
		    "%slice/push descriptor; the array is unchanged." << endl;
	    return true;
      }

      pair<size_t,size_t> window = thr->array_slice_stack.back();
      thr->array_slice_stack.pop_back();
      vvp_array_t array = resolve_runtime_array_(cp, "%store/arr/dar/slice");
      return store_arr_dar_window_(thr, cp, val, array, window.first,
				   window.second, "%store/arr/dar/slice");
}

/*
 * %dim/push <msb>, <lsb>
 *
 * Push one declared unpacked bound, leftmost dimension first. The
 * bounds are signed and ride in the unsigned operand fields the same
 * way %load/arr/dar's declared left does.
 */
bool of_DIM_PUSH(vthread_t thr, vvp_code_t cp)
{
      thr->dim_stack.push_back(std::make_pair((int)(int32_t)cp->bit_idx[0],
					      (int)(int32_t)cp->bit_idx[1]));
      return true;
}

/*
 * %slice/push <canonical-base>, <count>
 *
 * Describe a constant one-dimensional fixed-array storage window for the
 * next %load/arr/dar/slice or %store/arr/dar/slice. Both values are unsigned;
 * the selected range's signed declared LEFT bound rides on the load opcode.
 */
bool of_SLICE_PUSH(vthread_t thr, vvp_code_t cp)
{
      thr->array_slice_stack.push_back(
	    make_pair((size_t)cp->bit_idx[0], (size_t)cp->bit_idx[1]));
      return true;
}

static size_t md_range_size_(const pair<int,int>&r)
{
      return r.first > r.second
	   ? (size_t)((int64_t)r.first - r.second) + 1
	   : (size_t)((int64_t)r.second - r.first) + 1;
}

struct fixed_array_shape_mismatch_t {
      size_t dimension;
      size_t source_count;
      size_t target_count;
};

/* Validate every source dimension before copyback starts. A size check at
 * only the outer dimension is insufficient: one later dynamic subarray may
 * be short after earlier siblings have already been stored. IEEE 1800
 * 7.6 requires the failed assignment to perform no operation. */
static bool fixed_array_source_shape_matches_(
      vvp_darray*source, const vector<pair<int,int> >&dimensions, size_t dim,
      fixed_array_shape_mismatch_t&mismatch)
{
      if (dim >= dimensions.size())
	    return true;

      size_t target_count = md_range_size_(dimensions[dim]);
      size_t source_count = source ? source->get_size() : 0;
      if (!source || source_count != target_count) {
	    mismatch.dimension = dim;
	    mismatch.source_count = source_count;
	    mismatch.target_count = target_count;
	    return false;
      }

      if (dim + 1 == dimensions.size())
	    return true;

      for (size_t idx = 0 ; idx < source_count ; idx += 1) {
	    vvp_object_t child;
	    source->get_word((unsigned)idx, child);
	    if (!fixed_array_source_shape_matches_(
		      child.peek<vvp_darray>(), dimensions, dim + 1,
		      mismatch))
		  return false;
      }
      return true;
}

static void report_fixed_array_shape_mismatch_(
      const fixed_array_shape_mismatch_t&mismatch)
{
      cerr << "RUN-TIME ERROR: cannot copy a container dimension of size "
	   << mismatch.source_count << " into fixed unpacked array dimension "
	   << (mismatch.dimension + 1) << " of size " << mismatch.target_count
	   << " (IEEE 1800-2017/2023 7.6 requires equal element counts); "
	      "the array is unchanged." << endl;
}

/*
 * Build the NESTED container an open-array formal iterates, out of the
 * ONE flat word array a multi-dimensional signal is stored as. This is
 * the signal-side twin of fixed_prop_materialize_, which does the same
 * for a class property using its property_dimensions().
 *
 * Each level is a vvp_darray_object holding the level below, and every
 * level records its own declared range, so svLow/svHigh answer per
 * dimension (H.10.2) rather than reporting the flattened extent.
 */
static vvp_object_t md_materialize_(vvp_array_t array, uint32_t kind,
				    const vector<pair<int,int> >&dims,
				    size_t dim, size_t&flat)
{
      if (dim >= dims.size())
	    return vvp_object_t();

      size_t count = md_range_size_(dims[dim]);
      vvp_object_t out;
      vvp_darray*level = 0;

      if (dim + 1 < dims.size()) {
	    level = new vvp_darray_object(count);
	    out = vvp_object_t(level);
	    level->dpi_set_decl_range(dims[dim].first, dims[dim].second);
	    for (size_t idx = 0 ; idx < count ; idx += 1) {
		  vvp_object_t inner =
			md_materialize_(array, kind, dims, dim + 1, flat);
		  level->set_word((unsigned)idx, inner);
	    }
	    return out;
      }

      level = arrdar_leaf_(kind, count);
      out = vvp_object_t(level);
      level->dpi_set_decl_range(dims[dim].first, dims[dim].second);
      for (size_t idx = 0 ; idx < count ; idx += 1, flat += 1) {
	    if (flat >= array->get_size())
		  break;
	    if (ARRDAR_OBJ(kind)) {
		  vvp_object_t w;
		  array->get_word_obj((unsigned)flat, w);
		  level->set_word((unsigned)idx, w);
	    } else if (ARRDAR_STRING(kind)) {
		  level->set_word((unsigned)idx,
				  array->get_word_str((unsigned)flat));
	    } else if (ARRDAR_REAL(kind)) {
		  level->set_word((unsigned)idx,
				  array->get_word_r((unsigned)flat));
	    } else {
		  level->set_word((unsigned)idx,
				  array->get_word((unsigned)flat));
	    }
      }
      return out;
}

/* The inverse: walk the nested container back into the flat words. */
static void md_copy_back_(vvp_array_t array, uint32_t kind,
			  const vvp_object_t&val,
			  const vector<pair<int,int> >&dims,
			  size_t dim, size_t&flat)
{
      vvp_darray*level = val.peek<vvp_darray>();
      if (!level || dim >= dims.size())
	    return;

      size_t count = md_range_size_(dims[dim]);
      if (level->get_size() < count)
	    count = level->get_size();

      if (dim + 1 < dims.size()) {
	    for (size_t idx = 0 ; idx < count ; idx += 1) {
		  size_t source_idx = fixed_copy_source_index_(
			level, dims[dim].first > dims[dim].second,
			idx, count);
		  vvp_object_t inner;
		  level->get_word((unsigned)source_idx, inner);
		  md_copy_back_(array, kind, inner, dims, dim + 1, flat);
	    }
	    return;
      }

      for (size_t idx = 0 ; idx < count ; idx += 1, flat += 1) {
	    if (flat >= array->get_size())
		  break;
	    size_t source_idx = fixed_copy_source_index_(
		  level, dims[dim].first > dims[dim].second, idx, count);
	    if (ARRDAR_OBJ(kind)) {
		  vvp_object_t w;
		  level->get_word((unsigned)source_idx, w);
		  array->set_word((unsigned)flat, w);
	    } else if (ARRDAR_STRING(kind)) {
		  string w;
		  level->get_word((unsigned)source_idx, w);
		  array->set_word((unsigned)flat, w);
	    } else if (ARRDAR_REAL(kind)) {
		  double w = 0.0;
		  level->get_word((unsigned)source_idx, w);
		  array->set_word((unsigned)flat, w);
	    } else {
		  vvp_vector4_t w;
		  level->get_word((unsigned)source_idx, w);
		  unsigned wid = ARRDAR_WIDTH(kind);
		  if (wid && w.size() != wid)
			w = coerce_to_width(w, wid);
		  array->set_word((unsigned)flat, 0, w);
	    }
      }
}

/*
 * %load/arr/dar/md <array>, <kind>
 *
 * The multi-dimensional form of %load/arr/dar: marshal a flat signal
 * array into the nested container shape the %dim/push instructions just
 * described, and push it.
 */
bool of_LOAD_ARR_DAR_MD(vthread_t thr, vvp_code_t cp)
{
      vector<pair<int,int> > dims;
      dims.swap(thr->dim_stack);

      vvp_array_t array = resolve_runtime_array_(cp, "%load/arr/dar/md");
      if (!array || dims.empty()) {
	    thr->push_object(vvp_object_t());
	    return true;
      }

      size_t flat = 0;
      vvp_object_t value = md_materialize_(
	    array, cp->bit_idx[0], dims, 0, flat);
      reverse_descending_fixed_dimensions_(value.peek<vvp_darray>());
      thr->push_object(value);
      return true;
}

/*
 * %store/arr/dar/md <array>, <kind>
 *
 * The inverse, for the copy-back of an inout/ref/output open-array
 * formal into a multi-dimensional fixed-array actual.
 */
bool of_STORE_ARR_DAR_MD(vthread_t thr, vvp_code_t cp)
{
      vector<pair<int,int> > dims;
      dims.swap(thr->dim_stack);

      vvp_object_t val;
      thr->pop_object(val);

      vvp_array_t array = resolve_runtime_array_(cp, "%store/arr/dar/md");
      if (!array || dims.empty())
	    return true;

      fixed_array_shape_mismatch_t mismatch;
      if (!fixed_array_source_shape_matches_(
		val.peek<vvp_darray>(), dims, 0, mismatch)) {
	    report_fixed_array_shape_mismatch_(mismatch);
	    return true;
      }

      size_t total = 1;
      for (size_t idx = 0 ; idx < dims.size() ; idx += 1)
	    total *= md_range_size_(dims[idx]);
      if (total != array->get_size()) {
	    cerr << "RUN-TIME ERROR: cannot copy a container of " << total
		 << " declared elements into an unpacked array of size "
		 << array->get_size() << "; the array is unchanged." << endl;
	    return true;
      }

      size_t flat = 0;
      md_copy_back_(array, cp->bit_idx[0], val, dims, 0, flat);
      return true;
}

bool of_LOAD_OBJA(vthread_t thr, vvp_code_t cp)
{
      unsigned idx = cp->bit_idx[0];
      vvp_object_t word;
      vvp_array_t array = resolve_runtime_array_(cp, "%load/obja");

	/* Guard against unresolved null array stub. */
      if (!array) {
	    thr->push_object(word); // push nil
	    return true;
      }

	/* The result is 0.0 if the address is undefined. */
      if (thr->flags[4] == BIT4_1) {
	    ; // Return nil
      } else {
	    unsigned adr = thr->words[idx].w_int;
	    array->get_word_obj(adr, word);
      }

      thr->push_object(word);
      return true;
}

/*
 * %load/real <var-label>
 */
bool of_LOAD_REAL(vthread_t thr, vvp_code_t cp)
{
      __vpiHandle*tmp = cp->handle;
      t_vpi_value val;

      val.format = vpiRealVal;
      vpi_get_value(tmp, &val);

      thr->push_real(val.value.real);

      return true;
}

/*
 * %load/str <var-label>
 */
bool of_LOAD_STR(vthread_t thr, vvp_code_t cp)
{
      vvp_net_t*net = cp->net;

      vvp_fun_signal_string*fun = dynamic_cast<vvp_fun_signal_string*> (net->fun);
      vvp_ref_signal_aa*ref = dynamic_cast<vvp_ref_signal_aa*> (net->fun);
      assert(fun || ref);

      const string&val = fun ? fun->get_string() : ref->get_string();
      if (load_str_trace_scope_match_(thr ? thr->parent_scope : 0)) {
            __vpiScope*item_scope = 0;
            vpiHandle item = lookup_scope_item_by_net_chain_(thr ? thr->parent_scope : 0,
                                                             net, &item_scope);
            const char*item_name = item ? vpi_get_str(vpiName, item) : 0;
            fprintf(stderr,
                    "trace load_str-op scope=%s item_scope=%s item=%s net=%p len=%zu text=\"%.*s\"\n",
                    thr ? scope_name_or_unknown_(thr->parent_scope) : "<null>",
                    scope_name_or_unknown_(item_scope),
                    item_name ? item_name : "<unknown>",
                    (void*)net, val.size(),
                    (int)(val.size() < 80 ? val.size() : 80), val.c_str());
      }
      thr->push_str(val);

      return true;
}

bool of_LOAD_STRA(vthread_t thr, vvp_code_t cp)
{
      unsigned idx = cp->bit_idx[0];
      string word;
      vvp_array_t array = resolve_runtime_array_(cp, "%load/stra");

      if (thr->flags[4] == BIT4_1) {
	    word = "";
      } else {
	    unsigned adr = thr->words[idx].w_int;
	    word = array ? array->get_word_str(adr) : "";
      }

      thr->push_str(word);
      return true;
}


/*
 * %load/vec4 <net>
 */
bool of_LOAD_VEC4(vthread_t thr, vvp_code_t cp)
{
	// Push a placeholder onto the stack in order to reserve the
	// stack space. Use a reference for the stack top as a target
	// for the load.
      thr->push_vec4(vvp_vector4_t());
      vvp_vector4_t&sig_value = thr->peek_vec4();

      vvp_net_t*net = cp->net;

	// For the %load to work, the functor must actually be a
	// signal functor. Only signals save their vector value.
      vvp_signal_value*sig = net->fil ? net->fil->as_signal_value() : 0;
      if (sig == 0) {
	    cerr << thr->get_fileline()
	         << "%load/v error: Net arg not a signal? "
		 << (net->fil ? typeid(*net->fil).name() :
	                        typeid(*net->fun).name())
	         << endl;
	    assert(sig);
	    return true;
      }

	// Extract the value from the signal and directly into the
	// target stack position.
      sig->vec4_value(sig_value);

      return true;
}

/*
 * %hist/on <var-label>
 *
 * Enable the 1-deep driven-value history on a vec4 signal, so that
 * later %load/preponed reads can recover the value the signal held
 * when the current time step started (IEEE 1800-2017 14.13 clocking
 * input sampling, default #1step skew). Idempotent; emitted in the
 * prologue of synthesized clocking sample processes, which start
 * executing at time 0 before any clocking event can trigger. Signals
 * Strength-resolved vec8 wires retain their full driven strengths and reduce
 * only when loaded. Other filters quietly keep current-value behavior.
 */
bool of_HIST_ON(vthread_t, vvp_code_t cp)
{
      vvp_net_t*net = cp->net;
      if (vvp_wire_vec4*sig = dynamic_cast<vvp_wire_vec4*>(net->fil))
	    sig->enable_sample_hist();
      else if (vvp_wire_vec8*ssig = dynamic_cast<vvp_wire_vec8*>(net->fil))
	    ssig->enable_sample_hist();
      else if (vvp_wire_real*rsig = dynamic_cast<vvp_wire_real*>(net->fil))
	    rsig->enable_sample_hist();
      return true;
}

/*
 * %load/preponed <var-label>
 *
 * Push the signal's Preponed-region value: the value it held when the
 * current time step started if it changed during this step, otherwise
 * the current value. Requires a %hist/on for exact semantics; without
 * one (or on unsupported filters) this degrades to the current value.
 */
bool of_LOAD_PREPONED(vthread_t thr, vvp_code_t cp)
{
      thr->push_vec4(vvp_vector4_t());
      vvp_vector4_t&sig_value = thr->peek_vec4();

      vvp_net_t*net = cp->net;

      if (vvp_wire_vec4*sig = dynamic_cast<vvp_wire_vec4*>(net->fil)) {
	    sig->vec4_preponed_value(sig_value);
	    return true;
      }
      if (vvp_wire_vec8*ssig = dynamic_cast<vvp_wire_vec8*>(net->fil)) {
	    ssig->vec4_preponed_value(sig_value);
	    return true;
      }

      vvp_signal_value*sig = dynamic_cast<vvp_signal_value*> (net->fil);
      if (sig == 0) {
	    cerr << thr->get_fileline()
	         << "%load/preponed error: Net arg not a signal? "
		 << (net->fil ? typeid(*net->fil).name() :
	                        typeid(*net->fun).name())
	         << endl;
	    assert(sig);
	    return true;
      }

      sig->vec4_value(sig_value);
      return true;
}

/*
 * %hist/on/av <arr-label>
 *
 * Turn on the 1-deep per-word driven-value history of an unpacked array,
 * so %load/preponed/av can read a word's Preponed value.
 */
bool of_HIST_ON_AV(vthread_t, vvp_code_t cp)
{
      vvp_array_t array = resolve_runtime_array_(cp, "%hist/on/av");
      if (array) array->enable_sample_hist();
      return true;
}

/*
 * %load/preponed/av <arr>, <adrx>
 *
 * The array-word twin of %load/preponed: push the Preponed-region value of
 * one word. %load/preponed itself takes a signal and ignores any word
 * index, which is why an array element could not be sampled through it.
 */
bool of_LOAD_PREPONED_AV(vthread_t thr, vvp_code_t cp)
{
      int adr_index = cp->bit_idx[0];
      vvp_array_t array = resolve_runtime_array_(cp, "%load/preponed/av");

      long adr = thr->words[adr_index].w_int;

	/* Same out-of-range convention as %load/vec4a. */
      if (thr->flags[4] == BIT4_1) {
	    vvp_vector4_t tmp (array ? array->get_word_size() : 1, BIT4_X);
	    thr->push_vec4(tmp);
	    return true;
      }

      if (!array) {
	    thr->push_vec4(vvp_vector4_t(1, BIT4_X));
	    return true;
      }

      thr->push_vec4(array->get_word_preponed(adr));
      return true;
}

/*
 * %load/preponed/real <var-label>
 *
 * The real-valued twin of %load/preponed: push the signal's
 * Preponed-region value. Requires a %hist/on for exact semantics; without
 * one (or on a non-real filter) this degrades to the current value, which
 * is what a signal that never changed in this step holds anyway.
 */
bool of_LOAD_PREPONED_REAL(vthread_t thr, vvp_code_t cp)
{
      vvp_net_t*net = cp->net;

      if (vvp_wire_real*sig = dynamic_cast<vvp_wire_real*>(net->fil)) {
	    thr->push_real(sig->real_preponed_value());
	    return true;
      }

      vvp_signal_value*sig = dynamic_cast<vvp_signal_value*> (net->fil);
      if (sig == 0) {
	    cerr << thr->get_fileline()
	         << "%load/preponed/real error: Net arg not a signal? "
		 << (net->fil ? typeid(*net->fil).name() :
	                        typeid(*net->fun).name())
	         << endl;
	    assert(sig);
	    return true;
      }

      thr->push_real(sig->real_value());
      return true;
}

/*
 * %load/vec4a <arr>, <adrx>
 */
bool of_LOAD_VEC4A(vthread_t thr, vvp_code_t cp)
{
      int adr_index = cp->bit_idx[0];
      vvp_array_t array = resolve_runtime_array_(cp, "%load/vec4a");

      long adr = thr->words[adr_index].w_int;

	// If flag[3] is set, then the calculation of the address
	// failed, and this load should return X instead of the actual
	// value.
      if (thr->flags[4] == BIT4_1) {
	    vvp_vector4_t tmp (array ? array->get_word_size() : 1, BIT4_X);
	    thr->push_vec4(tmp);
	    return true;
      }

      if (!array) {
	    thr->push_vec4(vvp_vector4_t(1, BIT4_X));
	    return true;
      }

      vvp_vector4_t tmp (array->get_word(adr));
      thr->push_vec4(tmp);
      return true;
}

static void do_verylong_mod(vvp_vector4_t&vala, const vvp_vector4_t&valb,
			    bool left_is_neg, bool right_is_neg)
{
      bool out_is_neg = left_is_neg;
      const int len=vala.size();
      unsigned char *a, *z, *t;
      a = new unsigned char[len+1];
      z = new unsigned char[len+1];
      t = new unsigned char[len+1];

      unsigned char carry;
      unsigned char temp;

      int mxa = -1, mxz = -1;
      int i;
      int current, copylen;

      unsigned lb_carry = left_is_neg? 1 : 0;
      unsigned rb_carry = right_is_neg? 1 : 0;
      for (int idx = 0 ;  idx < len ;  idx += 1) {
	    unsigned lb = vala.value(idx);
	    unsigned rb = valb.value(idx);

	    if ((lb | rb) & 2) {
		  delete []t;
		  delete []z;
		  delete []a;
		  vvp_vector4_t tmp(len, BIT4_X);
		  vala = tmp;
		  return;
	    }

	    if (left_is_neg) {
		  lb = (1-lb) + lb_carry;
		  lb_carry = (lb & ~1)? 1 : 0;
		  lb &= 1;
	    }
	    if (right_is_neg) {
		  rb = (1-rb) + rb_carry;
		  rb_carry = (rb & ~1)? 1 : 0;
		  rb &= 1;
	    }

	    z[idx]=lb;
	    a[idx]=1-rb;	// for 2s complement add..
      }

      z[len]=0;
      a[len]=1;

      for(i=len-1;i>=0;i--) {
	    if(! a[i]) {
		  mxa=i;
		  break;
	    }
      }

      for(i=len-1;i>=0;i--) {
	    if(z[i]) {
		  mxz=i;
		  break;
	    }
      }

      if((mxa>mxz)||(mxa==-1)) {
	    if(mxa==-1) {
		  delete []t;
		  delete []z;
		  delete []a;
		  vvp_vector4_t tmpx (len, BIT4_X);
		  vala = tmpx;
		  return;
	    }

	    goto tally;
      }

      copylen = mxa + 2;
      current = mxz - mxa;

      while(current > -1) {
	    carry = 1;
	    for(i=0;i<copylen;i++) {
		  temp = z[i+current] + a[i] + carry;
		  t[i] = (temp&1);
		  carry = (temp>>1);
	    }

	    if(carry) {
		  for(i=0;i<copylen;i++) {
			z[i+current] = t[i];
		  }
	    }

	    current--;
      }

 tally:

      vvp_vector4_t tmp (len, BIT4_X);
      carry = out_is_neg? 1 : 0;
      for (int idx = 0 ;  idx < len ;  idx += 1) {
	    unsigned ob = z[idx];
	    if (out_is_neg) {
		  ob = (1-ob) + carry;
		  carry = (ob & ~1)? 1 : 0;
		  ob = ob & 1;
	    }
	    tmp.set_bit(idx, ob?BIT4_1:BIT4_0);
      }
      vala = tmp;
      delete []t;
      delete []z;
      delete []a;
}

bool of_MAX_WR(vthread_t thr, vvp_code_t)
{
      double r = thr->pop_real();
      double l = thr->pop_real();
      if (r != r)
	    thr->push_real(l);
      else if (l != l)
	    thr->push_real(r);
      else if (r < l)
	    thr->push_real(l);
      else
	    thr->push_real(r);
      return true;
}

bool of_MIN_WR(vthread_t thr, vvp_code_t)
{
      double r = thr->pop_real();
      double l = thr->pop_real();
      if (r != r)
	    thr->push_real(l);
      else if (l != l)
	    thr->push_real(r);
      else if (r < l)
	    thr->push_real(r);
      else
	    thr->push_real(l);
      return true;
}

bool of_MOD(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t valb = thr->pop_vec4();
      vvp_vector4_t&vala = thr->peek_vec4();

      assert(vala.size()==valb.size());
      unsigned wid = vala.size();

      if(wid <= 8*sizeof(unsigned long long)) {
	    unsigned long long lv = 0, rv = 0;

	    for (unsigned idx = 0 ;  idx < wid ;  idx += 1) {
		  unsigned long long lb = vala.value(idx);
		  unsigned long long rb = valb.value(idx);

		  if ((lb | rb) & 2)
			goto x_out;

		  lv |= (unsigned long long) lb << idx;
		  rv |= (unsigned long long) rb << idx;
	    }

	    if (rv == 0)
		  goto x_out;

	    lv %= rv;

	    for (unsigned idx = 0 ;  idx < wid ;  idx += 1) {
		  vala.set_bit(idx, (lv&1)?BIT4_1 : BIT4_0);
		  lv >>= 1;
	    }

	    return true;

      } else {
	    do_verylong_mod(vala, valb, false, false);
	    return true;
      }

 x_out:
      vala = vvp_vector4_t(wid, BIT4_X);
      return true;
}

/*
 * %mod/s
 */
bool of_MOD_S(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t valb = thr->pop_vec4();
      vvp_vector4_t&vala = thr->peek_vec4();

      assert(vala.size()==valb.size());
      unsigned wid = vala.size();

	/* Handle the case that we can fit the bits into a long-long
	   variable. We cause use native % to do the work. */
      if(wid <= 8*sizeof(long long)) {
	    long long lv = 0, rv = 0;

	    for (unsigned idx = 0 ;  idx < wid ;  idx += 1) {
		  long long lb = vala.value(idx);
		  long long rb = valb.value(idx);

		  if ((lb | rb) & 2)
			goto x_out;

		  lv |= (long long) lb << idx;
		  rv |= (long long) rb << idx;
	    }

	    if (rv == 0)
		  goto x_out;

	    if ((lv == LLONG_MIN) && (rv == -1))
		  goto zero_out;

	      /* Sign extend the signed operands when needed. */
	    if (wid < 8*sizeof(long long)) {
		  if (lv & (1LL << (wid-1)))
			lv |= -1ULL << wid;
		  if (rv & (1LL << (wid-1)))
			rv |= -1ULL << wid;
	    }

	    lv %= rv;

	    for (unsigned idx = 0 ;  idx < wid ;  idx += 1) {
		  vala.set_bit(idx, (lv&1)? BIT4_1 : BIT4_0);
		  lv >>= 1;
	    }

	      // vala is the top of the stack, edited in place, so we
	      // do not need to push the result.

	    return true;

      } else {

	    bool left_is_neg  = vala.value(vala.size()-1) == BIT4_1;
	    bool right_is_neg = valb.value(valb.size()-1) == BIT4_1;
	    do_verylong_mod(vala, valb, left_is_neg, right_is_neg);
	    return true;
      }

 x_out:
      vala = vvp_vector4_t(wid, BIT4_X);
      return true;
 zero_out:
      vala = vvp_vector4_t(wid, BIT4_0);
      return true;
}

/*
 * %mod/wr
 */
bool of_MOD_WR(vthread_t thr, vvp_code_t)
{
      double r = thr->pop_real();
      double l = thr->pop_real();
      thr->push_real(fmod(l,r));

      return true;
}

/*
 * %pad/s <wid>
 */
bool of_PAD_S(vthread_t thr, vvp_code_t cp)
{
      unsigned wid = cp->number;

      vvp_vector4_t&val = thr->peek_vec4();
      unsigned old_size = val.size();

	// Sign-extend.
      if (old_size < wid)
	    val.resize(wid, val.value(old_size-1));
      else
	    val.resize(wid);

      return true;
}

/*
 * %pad/u <wid>
 */
bool of_PAD_U(vthread_t thr, vvp_code_t cp)
{
      unsigned wid = cp->number;

      vvp_vector4_t&val = thr->peek_vec4();
      val.resize(wid, BIT4_0);

      return true;
}

/*
 * %part/s <wid>
 * %part/u <wid>
 * Two values are popped from the stack. First, pop the canonical
 * index of the part select, and second is the value to be
 * selected. The result is pushed back to the stack.
 */
static bool of_PART_base(vthread_t thr, vvp_code_t cp, bool signed_flag)
{
      unsigned wid = cp->number;

      vvp_vector4_t base4 = thr->pop_vec4();
      vvp_vector4_t&value = thr->peek_vec4();

      vvp_vector4_t res (wid, BIT4_X);

	// NOTE: This is treating the vector as signed. Is that correct?
      int32_t base;
      bool value_ok = vector4_to_value(base4, base, signed_flag);
      if (! value_ok) {
	    value = res;
	    return true;
      }

      if (base >= (int32_t)value.size()) {
	    value = res;
	    return true;
      }

      if ((base+(int)wid) <= 0) {
	    value = res;
	    return true;
      }

      long vbase = 0;
      if (base < 0) {
	    vbase = -base;
	    wid -= vbase;
	    base = 0;
      }

      if ((base+wid) > value.size()) {
	    wid = value.size() - base;
      }

      res .set_vec(vbase, value.subvalue(base, wid));
      value = res;

      return true;
}

bool of_PART_S(vthread_t thr, vvp_code_t cp)
{
      return of_PART_base(thr, cp, true);
}

bool of_PART_U(vthread_t thr, vvp_code_t cp)
{
      return of_PART_base(thr, cp, false);
}

/*
 * %parti/s <wid>, <basei>, <base_wid>
 * %parti/u <wid>, <basei>, <base_wid>
 *
 * Pop the value to be selected. The result is pushed back to the stack.
 */
static bool of_PARTI_base(vthread_t thr, vvp_code_t cp, bool signed_flag)
{
      unsigned wid = cp->number;
      uint32_t base = cp->bit_idx[0];
      uint32_t bwid = cp->bit_idx[1];

      vvp_vector4_t&value = thr->peek_vec4();

      vvp_vector4_t res (wid, BIT4_X);

	// NOTE: This is treating the vector as signed. Is that correct?
      int32_t use_base = base;
      if (signed_flag && bwid < 32 && (base&(1<<(bwid-1)))) {
	    use_base |= -1UL << bwid;
      }

      if (use_base >= (int32_t)value.size()) {
	    value = res;
	    return true;
      }

      if ((use_base+(int32_t)wid) <= 0) {
	    value = res;
	    return true;
      }

      long vbase = 0;
      if (use_base < 0) {
	    vbase = -use_base;
	    wid -= vbase;
	    use_base = 0;
      }

      if ((use_base+wid) > value.size()) {
	    wid = value.size() - use_base;
      }

      res .set_vec(vbase, value.subvalue(use_base, wid));
      value = res;

      return true;
}

bool of_PARTI_S(vthread_t thr, vvp_code_t cp)
{
      return of_PARTI_base(thr, cp, true);
}

bool of_PARTI_U(vthread_t thr, vvp_code_t cp)
{
      return of_PARTI_base(thr, cp, false);
}

/*
 * %mul
 */
bool of_MUL(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t r = thr->pop_vec4();
	// Rather then pop l, use it directly from the stack. When we
	// assign to 'l', that will edit the top of the stack, which
	// replaces a pop and a pull.
      vvp_vector4_t&l = thr->peek_vec4();

      l.mul(r);
      return true;
}

/*
 * %muli <vala>, <valb>, <wid>
 *
 * Pop1 operand, get the other operand from the arguments, and push
 * the result.
 */
bool of_MULI(vthread_t thr, vvp_code_t cp)
{
      unsigned wid = cp->number;

      vvp_vector4_t&l = thr->peek_vec4();

	// I expect that most of the bits of an immediate value are
	// going to be zero, so start the result vector with all zero
	// bits. Then we only need to replace the bits that are different.
      vvp_vector4_t r (wid, BIT4_0);
      get_immediate_rval (cp, r);

      l.mul(r);
      return true;
}

bool of_MUL_WR(vthread_t thr, vvp_code_t)
{
      double r = thr->pop_real();
      double l = thr->pop_real();
      thr->push_real(l * r);

      return true;
}

bool of_NAND(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t valr = thr->pop_vec4();
      vvp_vector4_t&vall = thr->peek_vec4();
      assert(vall.size() == valr.size());
      unsigned wid = vall.size();

      for (unsigned idx = 0 ; idx < wid ; idx += 1) {
	    vvp_bit4_t lb = vall.value(idx);
	    vvp_bit4_t rb = valr.value(idx);
	    vall.set_bit(idx, ~(lb&rb));
      }

      return true;
}

/*
 * %new/cobj <vpi_object>
 * This creates a new cobject (SystemVerilog class object) and pushes
 * it to the stack. The <vpi-object> is a __vpiHandle that is a
 * vpiClassDefn object that defines the item to be created.
 *
 * R3 (IEEE 1800-2017 18.13.1): the object's own RNG is seeded here, at
 * construction, from the next value of the constructing thread's LOGICAL
 * PROCESS generator (see the R3 block above thread_rng_srandom_ /
 * logical_process_thread_). Two objects `new'd back to back by the same
 * thread draw two different, independently-evolving seeds; an unrelated
 * object or thread constructed by some OTHER thread never touches this
 * one's sequence.
 */
bool of_NEW_COBJ(vthread_t thr, vvp_code_t cp)
{
      const class_type*defn = dynamic_cast<const class_type*> (cp->handle);
      assert(defn);

      vvp_cobject*cobj = new vvp_cobject(defn);
      if (vthread_t owner = logical_process_thread_(thr))
	    cobj->rng_srandom((int32_t)thread_rng_next_(owner));
      vvp_object_t tmp (cobj);
      thr->push_object(tmp);
      return true;
}

/*
 * Streaming-operator runtime (IEEE 1800-2017 11.4.14) for
 * dynamically sized operands.  Code generation lowers a streaming
 * concatenation with queue/dynamic-array/string operands into:
 *
 *     <push operand>  [%stream/flatten/obj | %stream/flatten/str]
 *     ... %concat/vec4 ...          ; join pieces left-to-right
 *     %stream/end/{l|r} <slice>, <tw>
 *     [%stream/to/queue "<t>" | %stream/to/dar "<t>" | %pushv/str]
 *
 * %stream/flatten/obj: pop a container object, push its bit stream
 * (element 0 leftmost, per the 11.4.14.1 foreach traversal).
 */
bool of_STREAM_FLATTEN_OBJ(vthread_t thr, vvp_code_t)
{
      static bool warned_bad_obj = false;

      vvp_object_t obj;
      thr->pop_object(obj);

      vvp_darray*dar = obj.peek<vvp_darray>();
      if (dar == 0) {
	    // Null handles are skipped (not streamed) per 11.4.14.1;
	    // any other object kind is unsupported here.
	    if (!obj.test_nil() && !warned_bad_obj) {
		  cerr << thr->get_fileline()
		       << "VVP error: unsupported object kind in streaming "
		          "concatenation; treating as empty stream "
		          "(further similar messages suppressed)." << endl;
		  warned_bad_obj = true;
	    }
	    thr->push_vec4(vvp_vector4_t(0, BIT4_0));
	    return true;
      }

      thr->push_vec4(dar->get_bitstream(true));
      return true;
}

namespace {

/* Keep every range-derived allocation below a process-independent cap.  The
 * source can request an arbitrarily large indexed width; rejecting it here
 * prevents integer wrap and memory exhaustion while preserving deterministic
 * empty/no-store recovery. */
const uint64_t STREAM_WITH_MAX_BITS = UINT64_C(64) * 1024 * 1024;
/* A bit count alone is not a safe work bound: one-bit source selections can
 * still run huge loops, and one-bit object-backed targets carry vector/deque
 * bookkeeping. Keep every plan consumer and target-container allocation
 * under an independent element bound. */
const uint64_t STREAM_WITH_MAX_ELEMENTS = UINT64_C(1024) * 1024;

enum stream_with_kind_t {
      STREAM_WITH_BAD, STREAM_WITH_INDEX, STREAM_WITH_RANGE,
      STREAM_WITH_UP, STREAM_WITH_DOWN
};

struct stream_with_desc_t {
      stream_with_kind_t kind;
      unsigned elem_width;
      bool four_state;
      int64_t aux1;
      int64_t aux2;
};

struct stream_with_plan_t {
      int64_t first;
      uint64_t count;
      int step;
};

enum stream_with_plan_phase_t {
      STREAM_PLAN_SINGLE, STREAM_PLAN_TARGET_FIRST, STREAM_PLAN_TARGET_SECOND
};

static bool parse_stream_with_desc_(vthread_t thr, const char*text,
				     stream_with_desc_t&desc)
{
      static bool warned_malformed = false;
      const auto malformed = [&]() {
	    if (!warned_malformed) {
		  cerr << thr->get_fileline()
		       << "VVP error: malformed streaming `with' descriptor '"
		       << (text ? text : "<null>")
		       << "'; treating the field as empty (further similar "
		          "messages suppressed)." << endl;
		  warned_malformed = true;
	    }
	    return false;
      };
      const auto parse_uint = [](const string&value, uint64_t&result) {
	    if (value.empty()) return false;
	    for (char ch : value)
		  if (!isdigit((unsigned char)ch)) return false;
	    errno = 0;
	    char*endp = 0;
	    unsigned long long parsed = strtoull(value.c_str(), &endp, 10);
	    if (errno == ERANGE || endp == value.c_str() || *endp)
		  return false;
	    result = parsed;
	    return true;
      };
      const auto parse_int = [](const string&value, int64_t&result) {
	    if (value.empty()) return false;
	    size_t pos = value[0] == '-' ? 1 : 0;
	    if (pos == value.size()) return false;
	    for ( ; pos < value.size() ; pos += 1)
		  if (!isdigit((unsigned char)value[pos])) return false;
	    errno = 0;
	    char*endp = 0;
	    long long parsed = strtoll(value.c_str(), &endp, 10);
	    if (errno == ERANGE || endp == value.c_str() || *endp)
		  return false;
	    result = parsed;
	    return true;
      };

      desc.kind = STREAM_WITH_BAD;
      desc.elem_width = 0;
      desc.four_state = true;
      desc.aux1 = 0;
      desc.aux2 = 0;
      if (!text) return malformed();

      string spec(text);
      size_t colon = spec.find(':');
      if (colon == string::npos) return malformed();
      string kind = spec.substr(0, colon);
      if (kind == "index") desc.kind = STREAM_WITH_INDEX;
      else if (kind == "range") desc.kind = STREAM_WITH_RANGE;
      else if (kind == "up") desc.kind = STREAM_WITH_UP;
      else if (kind == "down") desc.kind = STREAM_WITH_DOWN;
      else return malformed();

      size_t type_begin = colon + 1;
      size_t max_colon = spec.find(':', type_begin);
      string etype = spec.substr(type_begin,
				 max_colon == string::npos ? string::npos
				                            : max_colon-type_begin);
      const char*tp = etype.c_str();
      if (*tp == 's') tp += 1;
	  if (*tp != 'b' && *tp != 'v') return malformed();
      desc.four_state = (*tp == 'v');
	  uint64_t width = 0;
	  if (!parse_uint(tp+1, width) || width == 0 || width > UINT_MAX)
	    return malformed();
	  desc.elem_width = (unsigned)width;

      if (max_colon != string::npos) {
	    size_t aux2_colon = spec.find(':', max_colon + 1);
	    string aux1 = spec.substr(max_colon + 1,
		  aux2_colon == string::npos ? string::npos
		                              : aux2_colon-max_colon-1);
	    if (!parse_int(aux1, desc.aux1)) return malformed();
	    if (aux2_colon != string::npos) {
		  string aux2 = spec.substr(aux2_colon + 1);
		  if (!parse_int(aux2, desc.aux2)) return malformed();
	    }
      }
      return true;
}

static bool make_stream_with_plan_(vthread_t thr, vvp_code_t cp,
				    const stream_with_desc_t&desc,
				    stream_with_plan_t&plan,
				    bool allow_negative = false,
				    stream_with_plan_phase_t phase = STREAM_PLAN_SINGLE)
{
      plan.first = 0;
      plan.count = 0;
      plan.step = 1;
      if (phase == STREAM_PLAN_TARGET_FIRST) {
	    /* A previous null-receiver branch may have skipped its second
	       consumer. A new target field always begins a fresh plan. */
	    thr->stream_plan_invalid_pending = false;
      } else if (phase == STREAM_PLAN_TARGET_SECOND) {
	    bool repeated_invalid = thr->stream_plan_invalid_pending
		  && thr->stream_plan_first_reg == cp->bit_idx[0]
		  && thr->stream_plan_second_reg == cp->bit_idx[1];
	    thr->stream_plan_invalid_pending = false;
	    if (repeated_invalid) return false;
      }

      int64_t first = thr->words[cp->bit_idx[0]].w_int;
      int64_t second = thr->words[cp->bit_idx[1]].w_int;
	  bool unknown = thr->stream_range_unknown[cp->bit_idx[0]]
	    || (desc.kind != STREAM_WITH_INDEX
		&& thr->stream_range_unknown[cp->bit_idx[1]]);
      bool valid = !unknown && (allow_negative || first >= 0);
      plan.first = valid ? first : 0;

      switch (desc.kind) {
	  case STREAM_WITH_INDEX:
	    plan.count = valid ? 1 : 0;
	    break;
	  case STREAM_WITH_RANGE:
	    if (!allow_negative && second < 0) valid = false;
	    if (valid) {
		  __int128 delta = (__int128)second - (__int128)plan.first;
		  plan.step = delta >= 0 ? 1 : -1;
		  if (delta < 0) delta = -delta;
		  if (delta >= (__int128)UINT64_MAX) valid = false;
		  else plan.count = (uint64_t)delta + 1;
	    }
	    break;
	  case STREAM_WITH_UP:
	    if (second <= 0) valid = false;
	    if (valid) {
		  plan.count = (uint64_t)second;
		  __int128 last = (__int128)plan.first + plan.count - 1;
		  if (last > INT64_MAX) valid = false;
	    }
	    break;
	  case STREAM_WITH_DOWN:
	    if (second <= 0) valid = false;
	    if (valid) {
		  plan.count = (uint64_t)second;
		  plan.step = -1;
		  __int128 last = (__int128)plan.first - (plan.count - 1);
		  if (last < INT64_MIN || (!allow_negative && last < 0))
			valid = false;
	    }
	    break;
	  default:
	    valid = false;
	    break;
      }

      if (valid && plan.count > STREAM_WITH_MAX_ELEMENTS) {
	    cerr << thr->get_fileline()
		 << "VVP error: streaming `with' range selects " << plan.count
		 << " elements, exceeding the bounded per-operation limit of "
		 << STREAM_WITH_MAX_ELEMENTS
		 << " elements; treating the range as empty." << endl;
	    if (phase == STREAM_PLAN_TARGET_FIRST) {
		  thr->stream_plan_invalid_pending = true;
		  thr->stream_plan_first_reg = cp->bit_idx[0];
		  thr->stream_plan_second_reg = cp->bit_idx[1];
	    }
	    return false;
      }
      if (valid && (plan.count > STREAM_WITH_MAX_BITS/desc.elem_width)) {
	    cerr << thr->get_fileline()
		 << "VVP error: streaming `with' range requests " << plan.count
		 << " elements (" << desc.elem_width
		 << " bits each), exceeding the bounded runtime limit of "
		 << STREAM_WITH_MAX_BITS << " bits; treating the range as empty."
		 << endl;
	    if (phase == STREAM_PLAN_TARGET_FIRST) {
		  thr->stream_plan_invalid_pending = true;
		  thr->stream_plan_first_reg = cp->bit_idx[0];
		  thr->stream_plan_second_reg = cp->bit_idx[1];
	    }
	    return false;
      }
      if (!valid) {
	    cerr << thr->get_fileline()
		 << (unknown
		       ? "VVP error: streaming `with' range expression contains X/Z; "
		       : "VVP error: streaming `with' range has invalid indexes or "
			 "a nonpositive indexed width; ")
		 << "treating the range as empty." << endl;
	    /* The target-width calculation and subsequent store consume the
	       same captured bounds. Remember that relationship out of band so
	       no ordinary signed range value is reserved as a sentinel. */
	    if (phase == STREAM_PLAN_TARGET_FIRST) {
		  thr->stream_plan_invalid_pending = true;
		  thr->stream_plan_first_reg = cp->bit_idx[0];
		  thr->stream_plan_second_reg = cp->bit_idx[1];
	    }
	    return false;
      }
      return true;
}

static int64_t stream_with_index_(const stream_with_plan_t&plan,
				   uint64_t offset)
{
      return plan.step > 0 ? plan.first + (int64_t)offset
	                         : plan.first - (int64_t)offset;
}

static vvp_vector4_t normalize_stream_elem_(vvp_darray*dar,
					     int64_t index,
					     const stream_with_desc_t&desc,
					     bool nonexistent_default)
{
      vvp_bit4_t fill = nonexistent_default && desc.four_state
	    ? BIT4_X : BIT4_0;
      vvp_vector4_t elem(desc.elem_width, fill);
      if (!dar || index < 0 || (uint64_t)index >= dar->get_size()
	  || (uint64_t)index > UINT_MAX)
	    return elem;
      vvp_vector4_t got;
      dar->get_word((unsigned)index, got);
      unsigned copy = min(desc.elem_width, got.size());
      if (copy)
	    elem.set_vec(0, got.subvalue(0, copy));
      if (!desc.four_state)
	    elem = vector2_to_vector4(vvp_vector2_t(elem), elem.size());
      return elem;
}

static vvp_vector4_t coerce_stream_elem_(const vvp_vector4_t&value,
					  bool four_state)
{
      return four_state ? value
	                    : vector2_to_vector4(vvp_vector2_t(value),
	                                         value.size());
}

static bool take_stream_left_(vthread_t thr, uint64_t wanted)
{
      if (wanted > STREAM_WITH_MAX_BITS || wanted > UINT_MAX) {
	    cerr << thr->get_fileline()
		 << "VVP error: streaming target field exceeds the bounded "
		    "runtime width; producing an empty field." << endl;
	    wanted = 0;
      }
      vvp_vector4_t source = thr->pop_vec4();
      unsigned sw = source.size();
      unsigned take = (unsigned)wanted;
      vvp_vector4_t remainder(0, BIT4_0);
      vvp_vector4_t piece(take, BIT4_0);
      if (sw >= take) {
	    unsigned rw = sw - take;
	    remainder = source.subvalue(0, rw);
	    if (take) piece = source.subvalue(rw, take);
      } else {
	    if (sw) piece.set_vec(take-sw, source);
	    cerr << thr->get_fileline()
		 << "VVP error: streaming concatenation target field requires "
		 << take << " bits, but only " << sw
		 << " source bits remain; zero-filling." << endl;
      }
      thr->push_vec4(remainder);
      thr->push_vec4(piece);
      return true;
}

} // namespace

bool of_STREAM_FLATTEN_OBJ_WITH(vthread_t thr, vvp_code_t cp)
{
      stream_with_desc_t desc;
      stream_with_plan_t plan;
      vvp_object_t obj;
      thr->pop_object(obj);
      if (!parse_stream_with_desc_(thr, cp->text, desc)
	  || !make_stream_with_plan_(thr, cp, desc, plan, true)) {
	    thr->push_vec4(vvp_vector4_t(0, BIT4_0));
	    return true;
      }

      vvp_darray*dar = obj.peek<vvp_darray>();
      unsigned total = (unsigned)(plan.count * desc.elem_width);
      vvp_vector4_t result(total, BIT4_0);
      for (uint64_t pos = 0 ; pos < plan.count ; pos += 1) {
	    vvp_vector4_t elem = normalize_stream_elem_(
		  dar, stream_with_index_(plan, pos), desc, true);
	    unsigned base = total - (unsigned)((pos+1)*desc.elem_width);
	    result.set_vec(base, elem);
      }
      thr->push_vec4(result);
      return true;
}

bool of_STREAM_RANGE_MARK(vthread_t thr, vvp_code_t cp)
{
      unsigned word = cp->bit_idx[0];
      unsigned flag = cp->bit_idx[1];
	  thr->stream_range_unknown[word] = thr->flags[flag] != BIT4_0;
      return true;
}

bool of_STREAM_FLATTEN_VEC_WITH(vthread_t thr, vvp_code_t cp)
{
      stream_with_desc_t desc;
      stream_with_plan_t plan;
      vvp_vector4_t source = thr->pop_vec4();
      if (!parse_stream_with_desc_(thr, cp->text, desc)
	  || !make_stream_with_plan_(thr, cp, desc, plan, true)) {
	    thr->push_vec4(vvp_vector4_t(0, BIT4_0));
	    return true;
      }

      int64_t left = desc.aux1;
      int64_t right = desc.aux2;
      __int128 span = (__int128)right - left;
      if (span < 0) span = -span;
	  __int128 array_count_wide = span + 1;
	  if (array_count_wide > UINT_MAX
	      || array_count_wide
		   > (__int128)(STREAM_WITH_MAX_BITS/desc.elem_width)) {
	    cerr << thr->get_fileline()
		 << "VVP error: fixed-array streaming operand exceeds the bounded "
		    "runtime width; treating it as empty." << endl;
	    thr->push_vec4(vvp_vector4_t(0, BIT4_0));
	    return true;
      }
	  uint64_t array_count = (uint64_t)array_count_wide;

      unsigned total = (unsigned)(plan.count * desc.elem_width);
      unsigned source_total = (unsigned)(array_count * desc.elem_width);
      vvp_vector4_t result(total, BIT4_0);
      for (uint64_t pos = 0 ; pos < plan.count ; pos += 1) {
	    int64_t index = stream_with_index_(plan, pos);
	    vvp_vector4_t elem(desc.elem_width,
		  desc.four_state ? BIT4_X : BIT4_0);
	    int decl_step = left <= right ? 1 : -1;
	    __int128 rel = decl_step > 0 ? (__int128)index-left
					  : (__int128)left-index;
	    if (rel >= 0 && rel < (__int128)array_count) {
		  unsigned src_pos = (unsigned)rel;
		  unsigned src_base = source_total - (src_pos+1)*desc.elem_width;
		  if (src_base + desc.elem_width <= source.size())
			elem = source.subvalue(src_base, desc.elem_width);
	    }
	    unsigned dst_base = total - (unsigned)((pos+1)*desc.elem_width);
	    result.set_vec(dst_base, elem);
      }
      thr->push_vec4(result);
      return true;
}

bool of_STREAM_TAKE_LEFT(vthread_t thr, vvp_code_t cp)
{
      return take_stream_left_(thr, cp->number);
}

bool of_STREAM_TAKE_LEFT_WITH(vthread_t thr, vvp_code_t cp)
{
      stream_with_desc_t desc;
      stream_with_plan_t plan;
	  if (!parse_stream_with_desc_(thr, cp->text, desc)) {
	    thr->stream_plan_invalid_pending = true;
	    thr->stream_plan_first_reg = cp->bit_idx[0];
	    thr->stream_plan_second_reg = cp->bit_idx[1];
	    return take_stream_left_(thr, 0);
	  }
	  if (!make_stream_with_plan_(thr, cp, desc, plan, false,
				       STREAM_PLAN_TARGET_FIRST))
	    return take_stream_left_(thr, 0);

      uint64_t wanted = plan.count * desc.elem_width;
      uint64_t reserve = desc.aux1 > 0 ? (uint64_t)desc.aux1 : 0;
      if (reserve) {
	    vvp_vector4_t source = thr->pop_vec4();
	    unsigned sw = source.size();
	    uint64_t available = sw > reserve ? sw-reserve : 0;
	    unsigned take = (unsigned)min(wanted, available);
	    vvp_vector4_t remainder = source.subvalue(0, sw-take);
	    vvp_vector4_t piece((unsigned)wanted, BIT4_0);
	    if (take)
		  piece.set_vec((unsigned)wanted-take,
			       source.subvalue(sw-take, take));
	    if (take < wanted)
		  cerr << thr->get_fileline()
		       << "VVP error: ranged streaming target has only " << take
		       << " bits available before later fixed fields; zero-filling "
			  "the remaining " << wanted-take << " bits." << endl;
	    thr->push_vec4(remainder);
	    thr->push_vec4(piece);
	    return true;
      }
      return take_stream_left_(thr, wanted);
}

bool of_STREAM_TAKE_LEFT_REM(vthread_t thr, vvp_code_t cp)
{
      uint64_t reserve = cp->number;
      vvp_vector4_t source = thr->pop_vec4();
      unsigned sw = source.size();
      if (reserve > STREAM_WITH_MAX_BITS || reserve > UINT_MAX) {
	    cerr << thr->get_fileline()
		 << "VVP error: fixed suffix of a streaming target exceeds the "
		    "bounded runtime width." << endl;
	    reserve = 0;
      }
      unsigned keep = (unsigned)reserve;
      vvp_vector4_t remainder(keep, BIT4_0);
      vvp_vector4_t greedy(0, BIT4_0);
      if (sw >= keep) {
	    unsigned greedy_width = sw-keep;
	    remainder = source.subvalue(0, keep);
	    greedy = source.subvalue(keep, greedy_width);
      } else if (sw) {
	    remainder.set_vec(keep-sw, source);
      }
      thr->push_vec4(remainder);
      thr->push_vec4(greedy);
      return true;
}

static bool stream_store_fixed_with_(vthread_t thr, vvp_code_t cp,
				      stream_with_kind_t kind)
{
      vvp_vector4_t selected = thr->pop_vec4();
      vvp_array_t array = resolve_runtime_array_(cp, "%stream/store/fixed");
      if (!array) return true;

      stream_with_desc_t desc;
      desc.kind = kind;
      desc.elem_width = (unsigned)array->get_word_size();
      desc.four_state = true;
      desc.aux1 = desc.aux2 = 0;
      stream_with_plan_t plan;
	  if (desc.elem_width == 0
	      || !make_stream_with_plan_(thr, cp, desc, plan, true,
					 STREAM_PLAN_TARGET_SECOND))
	    return true;

      bool reported_oob = false;
      uint64_t array_size = array->get_size();
      int64_t declared_zero = array_size
	    ? (int64_t)array->get_word_declared_index(0) : 0;
      for (uint64_t pos = 0 ; pos < plan.count ; pos += 1) {
	    int64_t declared = stream_with_index_(plan, pos);
	    /* Fixed-array canonical addresses are affine from the lowest
	       declared index.  Invert that mapping directly instead of scanning
	       the complete array once for every selected element. */
	    __int128 canonical = (__int128)declared - declared_zero;
	    if (canonical < 0 || canonical >= (__int128)array_size) {
		  if (!reported_oob) {
			cerr << thr->get_fileline()
			     << "VVP error: streaming `with' unpack range includes "
			     << "index " << declared
			     << " outside the fixed array bounds; in-range elements "
				"are still modified." << endl;
			reported_oob = true;
		  }
		  continue;
	    }

	    unsigned top = selected.size() > pos*desc.elem_width
		  ? selected.size() - (unsigned)(pos*desc.elem_width) : 0;
	    vvp_vector4_t elem(desc.elem_width, BIT4_0);
	    unsigned avail = min(desc.elem_width, top);
	    if (avail)
		  elem.set_vec(desc.elem_width-avail,
			       selected.subvalue(top-avail, avail));
	    array->set_word((unsigned)canonical, 0, elem);
      }
      return true;
}

bool of_STREAM_STORE_FIXED_INDEX(vthread_t thr, vvp_code_t cp)
{ return stream_store_fixed_with_(thr, cp, STREAM_WITH_INDEX); }
bool of_STREAM_STORE_FIXED_RANGE(vthread_t thr, vvp_code_t cp)
{ return stream_store_fixed_with_(thr, cp, STREAM_WITH_RANGE); }
bool of_STREAM_STORE_FIXED_UP(vthread_t thr, vvp_code_t cp)
{ return stream_store_fixed_with_(thr, cp, STREAM_WITH_UP); }
bool of_STREAM_STORE_FIXED_DOWN(vthread_t thr, vvp_code_t cp)
{ return stream_store_fixed_with_(thr, cp, STREAM_WITH_DOWN); }

static bool stream_store_prop_fixed_with_(vthread_t thr, vvp_code_t cp,
					   stream_with_kind_t kind)
{
      vvp_vector4_t selected = thr->pop_vec4();
      size_t pid = cp->number;
      vvp_object_t&obj = thr->peek_object();
      vvp_cobject*cobj = obj.peek<vvp_cobject>();
      vvp_vinterface*vif = obj.peek<vvp_vinterface>();
      const class_type*defn = cobj ? cobj->get_defn()
	                            : (vif ? vif->get_defn() : 0);
      if (!defn || pid >= defn->property_count())
	    return true;
      const vector<pair<int,int> >&dimensions =
	    defn->property_dimensions(pid);
      if (dimensions.size() != 1)
	    return true;

      stream_with_desc_t desc;
      desc.kind = kind;
      desc.elem_width = defn->property_vec4_width(pid);
      desc.four_state = defn->property_base_type(pid).find('L')
	    != string::npos;
      desc.aux1 = desc.aux2 = 0;
      stream_with_plan_t plan;
	  if (desc.elem_width == 0
	      || !make_stream_with_plan_(thr, cp, desc, plan, true,
					 STREAM_PLAN_TARGET_SECOND))
	    return true;

      int64_t left = dimensions[0].first;
      int64_t right = dimensions[0].second;
      __int128 span = (__int128)right-left;
      if (span < 0) span = -span;
      uint64_t count = (uint64_t)span + 1;
      bool reported_oob = false;
      for (uint64_t pos = 0 ; pos < plan.count ; pos += 1) {
	    int64_t declared = stream_with_index_(plan, pos);
	      /* Inline fixed-array properties use the same canonical storage
		 numbering as signal arrays: slot zero is the declared RIGHT bound,
		 irrespective of declaration direction. */
	    __int128 canonical = left <= right
		  ? (__int128)right-declared : (__int128)declared-right;
	    if (canonical < 0 || canonical >= (__int128)count) {
		  if (!reported_oob) {
			cerr << thr->get_fileline()
			     << "VVP error: streaming `with' unpack range includes "
			     << "index " << declared
			     << " outside the fixed array property bounds; in-range "
				"elements are still modified." << endl;
			reported_oob = true;
		  }
		  continue;
	    }

	    unsigned top = selected.size() > pos*desc.elem_width
		  ? selected.size() - (unsigned)(pos*desc.elem_width) : 0;
	    vvp_vector4_t elem(desc.elem_width, BIT4_0);
	    unsigned avail = min(desc.elem_width, top);
	    if (avail)
		  elem.set_vec(desc.elem_width-avail,
			       selected.subvalue(top-avail, avail));
	    elem = coerce_stream_elem_(elem, desc.four_state);
	    if (cobj) cobj->set_vec4(pid, elem, (size_t)canonical);
	    else vif->set_vec4(pid, elem, (size_t)canonical);
      }
      notify_mutated_object_root_(thr, obj, thr->peek_object_source_net(0),
				  thr->peek_object_root(0),
				  "stream-store-prop-fixed");
      return true;
}

bool of_STREAM_STORE_PROP_FIXED_INDEX(vthread_t thr, vvp_code_t cp)
{ return stream_store_prop_fixed_with_(thr, cp, STREAM_WITH_INDEX); }
bool of_STREAM_STORE_PROP_FIXED_RANGE(vthread_t thr, vvp_code_t cp)
{ return stream_store_prop_fixed_with_(thr, cp, STREAM_WITH_RANGE); }
bool of_STREAM_STORE_PROP_FIXED_UP(vthread_t thr, vvp_code_t cp)
{ return stream_store_prop_fixed_with_(thr, cp, STREAM_WITH_UP); }
bool of_STREAM_STORE_PROP_FIXED_DOWN(vthread_t thr, vvp_code_t cp)
{ return stream_store_prop_fixed_with_(thr, cp, STREAM_WITH_DOWN); }

static bool stream_to_container_with_(vthread_t thr, vvp_code_t cp,
				       bool as_queue)
{
      stream_with_desc_t desc;
      stream_with_plan_t plan;
      vvp_vector4_t selected = thr->pop_vec4();
      vvp_object_t old_obj;
      thr->pop_object(old_obj);
	  if (!parse_stream_with_desc_(thr, cp->text, desc)
	      || !make_stream_with_plan_(thr, cp, desc, plan, false,
					 STREAM_PLAN_TARGET_SECOND)) {
	    thr->push_object(old_obj);
	    return true;
      }

      vvp_darray*old = old_obj.peek<vvp_darray>();
      uint64_t old_size = old ? old->get_size() : 0;
      int64_t max_index_signed = plan.count
	    ? stream_with_index_(plan, plan.step > 0 ? plan.count-1 : 0)
	    : 0;
	if (plan.step < 0) max_index_signed = plan.first;
      uint64_t max_index = max_index_signed < 0 ? 0
	                                       : (uint64_t)max_index_signed;
      uint64_t wanted_size = plan.count ? max(old_size, max_index+1)
	                               : old_size;
      uint64_t limit_elems = STREAM_WITH_MAX_BITS / desc.elem_width;
      uint64_t queue_max = desc.aux1 > 0 ? (uint64_t)desc.aux1 : 0;
      if (as_queue && queue_max && wanted_size > queue_max) {
	    cerr << thr->get_fileline()
		 << "VVP error: streaming `with' selection exceeds bounded queue "
		 << "size " << queue_max
		 << "; out-of-bound elements are ignored." << endl;
	    wanted_size = queue_max;
      }
      if (plan.count > STREAM_WITH_MAX_ELEMENTS
	  || wanted_size > STREAM_WITH_MAX_ELEMENTS
	  || wanted_size > limit_elems || wanted_size > UINT_MAX) {
	    cerr << thr->get_fileline()
		 << "VVP error: streaming `with' target requests " << plan.count
		 << " selected elements and a " << wanted_size
		 << "-element container, exceeding the bounded runtime limit of "
		 << STREAM_WITH_MAX_ELEMENTS
		 << " container elements; preserving the previous container value."
		 << endl;
	    thr->push_object(old_obj);
	    return true;
      }

      vvp_object_t result_obj;
      vvp_darray*result = 0;
      bool can_duplicate = old && old_size == wanted_size
	    && (desc.four_state || dynamic_cast<vvp_darray_vec2*>(old));
      if (can_duplicate) {
	    result_obj = vvp_object_t(old->duplicate());
	    result = result_obj.peek<vvp_darray>();
      } else if (as_queue) {
	    vvp_queue_vec4*q = new vvp_queue_vec4;
	    for (uint64_t pos = 0 ; pos < wanted_size ; pos += 1) {
		  vvp_vector4_t elem = normalize_stream_elem_(old, pos, desc, false);
		  q->push_back(elem, (unsigned)queue_max);
	    }
	    result_obj = vvp_object_t(q);
	    result = q;
      } else {
	    vvp_darray*d = desc.four_state
		  ? static_cast<vvp_darray*>(new vvp_darray_vec4(
			(size_t)wanted_size, desc.elem_width))
		  : static_cast<vvp_darray*>(new vvp_darray_vec2(
			(size_t)wanted_size, desc.elem_width));
	    for (uint64_t pos = 0 ; pos < wanted_size ; pos += 1)
		  d->set_word((unsigned)pos,
		      normalize_stream_elem_(old, pos, desc, false));
	    result_obj = vvp_object_t(d);
	    result = d;
      }

      for (uint64_t pos = 0 ; pos < plan.count ; pos += 1) {
	    int64_t index = stream_with_index_(plan, pos);
	    if (index < 0 || (uint64_t)index >= wanted_size
		|| (uint64_t)index > UINT_MAX)
		  continue;
	    unsigned top = selected.size() > pos*desc.elem_width
		  ? selected.size() - (unsigned)(pos*desc.elem_width) : 0;
	    vvp_vector4_t elem(desc.elem_width, BIT4_0);
	    unsigned avail = min(desc.elem_width, top);
	    if (avail)
		  elem.set_vec(desc.elem_width-avail,
			       selected.subvalue(top-avail, avail));
	    elem = coerce_stream_elem_(elem, desc.four_state);
	    result->set_word((unsigned)index, elem);
      }
      thr->push_object(result_obj);
      return true;
}

bool of_STREAM_TO_DAR_WITH(vthread_t thr, vvp_code_t cp)
{
      return stream_to_container_with_(thr, cp, false);
}

bool of_STREAM_TO_QUEUE_WITH(vthread_t thr, vvp_code_t cp)
{
      return stream_to_container_with_(thr, cp, true);
}

/*
 * %stream/flatten/str: pop a string, push its bit stream (8 bits per
 * character, first character leftmost).
 */
bool of_STREAM_FLATTEN_STR(vthread_t thr, vvp_code_t)
{
      string str = thr->pop_str();

      vvp_vector4_t vec(8 * str.size(), BIT4_0);
      unsigned vdx = vec.size();
      for (size_t sdx = 0 ; sdx < str.size() ; sdx += 1) {
	    unsigned char ch = (unsigned char)str[sdx];
	    vdx -= 8;
	    for (unsigned bdx = 0 ; bdx < 8 ; bdx += 1) {
		  if ((ch >> bdx) & 1)
			vec.set_bit(vdx + bdx, BIT4_1);
	    }
      }
      thr->push_vec4(vec);
      return true;
}

/*
 * %stream/end/l <slice>, <tw>   (stream operator <<)
 * %stream/end/r <slice>, <tw>   (stream operator >>)
 *
 * Finish a runtime stream: pop the joined stream, apply the <<
 * block re-ordering (11.4.14.2) for the /l form, then if <tw> is
 * nonzero align the stream into a <tw>-bit fixed-size target
 * (11.4.14: left-align, zero-fill on the right; a stream wider than
 * the target is an error).  Push the result.
 */
static bool do_stream_end(vthread_t thr, vvp_code_t cp, bool reverse)
{
      static bool warned_stream_too_wide = false;

      unsigned slice = cp->bit_idx[0];
      unsigned tw    = cp->bit_idx[1];

      vvp_vector4_t val = thr->pop_vec4();
      unsigned w = val.size();

      if (reverse && slice > 0 && w > slice) {
	    // Slice into blocks starting at the right-most bit; the
	    // left-most partial block keeps the remaining bits; block
	    // order is reversed (11.4.14.2).
	    vvp_vector4_t res(w, BIT4_0);
	    unsigned full = w / slice;
	    unsigned rem  = w % slice;
	    unsigned pos = w;
	    for (unsigned i = 0 ; i < full ; i += 1) {
		  pos -= slice;
		  res.set_vec(pos, val.subvalue(i*slice, slice));
	    }
	    if (rem)
		  res.set_vec(0, val.subvalue(full*slice, rem));
	    val = res;
	    w = val.size();
      }

      if (tw > 0 && w != tw) {
	    if (w > tw) {
		  if (!warned_stream_too_wide) {
			cerr << thr->get_fileline()
			     << "VVP error: streaming concatenation produces "
			     << w << " bits, which does not fit in the "
			     << tw << "-bit assignment target (IEEE "
			        "1800-2017 11.4.14); keeping the left-most "
			        "bits (further similar messages "
			        "suppressed)." << endl;
			warned_stream_too_wide = true;
		  }
		  val = val.subvalue(w - tw, tw);
	    } else {
		  // Left-align in the wider target, zero-fill right.
		  vvp_vector4_t res(tw, BIT4_0);
		  if (w > 0)
			res.set_vec(tw - w, val);
		  val = res;
	    }
      }

      thr->push_vec4(val);
      return true;
}

bool of_STREAM_END_L(vthread_t thr, vvp_code_t cp)
{
      return do_stream_end(thr, cp, true);
}

bool of_STREAM_END_R(vthread_t thr, vvp_code_t cp)
{
      return do_stream_end(thr, cp, false);
}

/*
 * %stream/unpack/l <slice>, <tw>   (stream operator <<)
 * %stream/unpack/r <slice>, <tw>   (stream operator >>)
 *
 * Unpack side (11.4.14.3): pop the source stream; when <tw> is
 * nonzero the target consumes the left-most <tw> bits (a source with
 * fewer bits is an error); then the /l form applies the INVERSE of
 * the pack block re-ordering ("the streaming operators perform the
 * reverse operation").  Push the result.
 */
static bool do_stream_unpack(vthread_t thr, vvp_code_t cp, bool reverse)
{
      static bool warned_stream_too_small = false;

      unsigned slice = cp->bit_idx[0];
      unsigned tw    = cp->bit_idx[1];

      vvp_vector4_t val = thr->pop_vec4();
      unsigned w = val.size();

      if (tw > 0 && w != tw) {
	    if (w < tw) {
		  if (!warned_stream_too_small) {
			cerr << thr->get_fileline()
			     << "VVP error: streaming concatenation target "
			        "requires " << tw << " bits, but the source "
			        "stream provides only " << w << " (IEEE "
			        "1800-2017 11.4.14.3); zero-filling "
			        "(further similar messages suppressed)."
			     << endl;
			warned_stream_too_small = true;
		  }
		  vvp_vector4_t res(tw, BIT4_0);
		  if (w > 0)
			res.set_vec(tw - w, val);
		  val = res;
	    } else {
		  // Consume from the left (most significant) end.
		  val = val.subvalue(w - tw, tw);
	    }
	    w = val.size();
      }

      if (reverse && slice > 0 && w > slice) {
	    // Inverse of the 11.4.14.2 block re-ordering: the input's
	    // top slice-size block returns to the LSB end; the LSB-end
	    // partial block (w % slice bits) returns to the top.
	    vvp_vector4_t res(w, BIT4_0);
	    unsigned full = w / slice;
	    unsigned rem  = w % slice;
	    if (rem)
		  res.set_vec(w - rem, val.subvalue(0, rem));
	    for (unsigned i = 0 ; i < full ; i += 1) {
		    // Input block just above the rem bits maps to the
		    // output block below the rem bits, and so on down.
		  res.set_vec((full - 1 - i)*slice,
			      val.subvalue(rem + i*slice, slice));
	    }
	    val = res;
      }

      thr->push_vec4(val);
      return true;
}

bool of_STREAM_UNPACK_L(vthread_t thr, vvp_code_t cp)
{
      return do_stream_unpack(thr, cp, true);
}

bool of_STREAM_UNPACK_R(vthread_t thr, vvp_code_t cp)
{
      return do_stream_unpack(thr, cp, false);
}

/*
 * %stream/pad/min <wid>
 *
 * A dynamically sized streaming target still has a fixed minimum width: the
 * sum of all statically sized members. Leave a wider stream unchanged. If it
 * is shorter, report the 11.4.14.3 error and left-align it in a zero-filled
 * minimum-width vector so target distribution remains deterministic.
 */
bool of_STREAM_PAD_MIN(vthread_t thr, vvp_code_t cp)
{
      static bool warned_stream_too_small = false;
      const vvp_vector4_t*cur = thr->safe_peek_vec4(0);
      if (!cur) {
	    cerr << thr->get_fileline()
		 << "VVP error: %stream/pad/min requires one vec4 stack value."
		 << endl;
	    return false;
      }

      unsigned min_width = cp->number;
      if (cur->size() >= min_width)
	    return true;

      if (!warned_stream_too_small) {
	    cerr << thr->get_fileline()
		 << "VVP error: streaming concatenation target has "
		 << min_width << " fixed bits, but the source stream provides "
		 << cur->size() << " (IEEE 1800-2017 11.4.14.3); "
		    "zero-filling (further similar messages suppressed)."
		 << endl;
	    warned_stream_too_small = true;
      }

      vvp_vector4_t val = thr->pop_vec4();
      vvp_vector4_t padded(min_width, BIT4_0);
      if (val.size() > 0)
	    padded.set_vec(min_width - val.size(), val);
      thr->push_vec4(padded);
      return true;
}

/*
 * %stream/split/rem <fixed-msb-width>
 *
 * Split a stream at a run-time-sized greedy target. Keep the reserved fixed
 * MSB portion below and push the remaining LSB portion for the dynamic member.
 */
bool of_STREAM_SPLIT_REM(vthread_t thr, vvp_code_t cp)
{
      const vvp_vector4_t*cur = thr->safe_peek_vec4(0);
      if (!cur) {
	    cerr << thr->get_fileline()
		 << "VVP error: %stream/split/rem requires one vec4 stack value."
		 << endl;
	    return false;
      }

      unsigned fixed_msb = cp->number;
      if (fixed_msb > cur->size()) {
	    cerr << thr->get_fileline()
		 << "VVP error: %stream/split/rem reserves " << fixed_msb
		 << " bits from a " << cur->size() << "-bit stream." << endl;
	    return false;
      }

      vvp_vector4_t val = thr->pop_vec4();
      unsigned dynamic_width = val.size() - fixed_msb;
      vvp_vector4_t fixed = val.subvalue(dynamic_width, fixed_msb);
      vvp_vector4_t dynamic = val.subvalue(0, dynamic_width);
      thr->push_vec4(fixed);
      thr->push_vec4(dynamic);
      return true;
}

struct stream_container_encoding_t {
      unsigned element_width;
      bool four_state;
      bool strict_cast;
      uint64_t queue_max;
};

static bool decode_stream_container_encoding_(
      const char*text, bool as_queue, stream_container_encoding_t&enc)
{
      enc.element_width = 0;
      enc.four_state = false;
      enc.strict_cast = false;
      enc.queue_max = 0;
      if (!text)
	    return false;

      const char*cursor = text;
      if (*cursor == 's')
	    cursor += 1;
      if (*cursor != 'b' && *cursor != 'v')
	    return false;
      enc.four_state = *cursor == 'v';
      cursor += 1;

      if (!isdigit(static_cast<unsigned char>(*cursor)))
	    return false;
      errno = 0;
      char*end = 0;
      unsigned long long width = strtoull(cursor, &end, 10);
      if (errno == ERANGE || end == cursor || width == 0 || width > UINT_MAX)
	    return false;
      enc.element_width = static_cast<unsigned>(width);
      cursor = end;

      if (*cursor == '!') {
	    enc.strict_cast = true;
	    cursor += 1;
      }

      if (*cursor == ':') {
	    if (!as_queue)
		  return false;
	    cursor += 1;
	    if (!isdigit(static_cast<unsigned char>(*cursor)))
		  return false;
	    errno = 0;
	    unsigned long long maximum = strtoull(cursor, &end, 10);
	    if (errno == ERANGE || end == cursor)
		  return false;
	    enc.queue_max = static_cast<uint64_t>(maximum);
	    cursor = end;
      }

      return *cursor == 0;
}

bool vvp_stream_container_encoding_is_valid(const char*text, bool as_queue)
{
      stream_container_encoding_t enc;
      return decode_stream_container_encoding_(text, as_queue, enc);
}

static bool container_opcode_runtime_fatal_();

/*
 * %stream/to/queue "<t>" and %stream/to/dar "<t>"
 *
 * Pop a bit stream and materialize it as a dynamically sized
 * container with elements of the type described by <t> ("b8",
 * "sb32", "v1", ...).  Per 11.4.14, the container gets the smallest
 * number of elements that hold the whole stream; a final partial
 * element is zero-filled on the right.  Element 0 receives the
 * left-most bits (matching the flatten order above).
 */
static bool do_stream_to_container(vthread_t thr, vvp_code_t cp, bool as_queue)
{
      const char*text = cp->text;
      vvp_vector4_t val = thr->pop_vec4();

      stream_container_encoding_t enc;
      if (!decode_stream_container_encoding_(text, as_queue, enc)) {
	    cerr << thr->get_fileline()
		 << "VVP error: malformed stream container encoding '"
		 << (text ? text : "<null>") << "'." << endl;
	    vvp_object_t nil;
	    thr->push_object(nil);
	    return container_opcode_runtime_fatal_();
      }

      unsigned ewid = enc.element_width;
      bool four_state = enc.four_state;
      bool strict_cast = enc.strict_cast;
      uint64_t queue_max = enc.queue_max;

      unsigned w = val.size();
      size_t count = w / ewid + ((w % ewid) != 0);
      bool cast_size_error = strict_cast && (w % ewid) != 0;
      bool cast_bound_error = strict_cast && as_queue && queue_max
	    && count > queue_max;
      if (cast_size_error || cast_bound_error) {
	    cerr << thr->get_fileline()
		 << "VVP error: bit-stream cast source size " << w
		 << " does not fit the destination";
	    if (cast_bound_error)
		  cerr << " bounded queue capacity " << queue_max;
	    else
		  cerr << " element width " << ewid;
	    cerr << "." << endl;
	    count = 0;
      }
      bool runtime_limit_error = count > STREAM_WITH_MAX_BITS/ewid;
      if (runtime_limit_error) {
	    cerr << thr->get_fileline()
		 << "VVP error: streaming target container exceeds the bounded "
		    "runtime width; producing an empty container." << endl;
	    count = 0;
      }
      if (as_queue && queue_max && count > queue_max) {
	    cerr << thr->get_fileline()
		 << "VVP error: streaming target exceeds bounded queue size "
		 << queue_max << "; trailing elements are ignored." << endl;
	    count = (size_t)queue_max;
      }

      if (as_queue) {
	    vvp_queue_vec4*res = new vvp_queue_vec4;
	    for (size_t i = 0 ; i < count ; i += 1) {
		  vvp_vector4_t elem(ewid, BIT4_0);
		  unsigned top = w - (unsigned)i*ewid;   // stream bits above this element
		  unsigned avail = (top >= ewid) ? ewid : top;
		  elem.set_vec(ewid - avail, val.subvalue(top - avail, avail));
		  elem = coerce_stream_elem_(elem, four_state);
		  /* COUNT was already clipped or validated against the full
		   * uint64_t bound. Reapplying it through the legacy unsigned API
		   * would wrap bounds above UINT_MAX. */
		  res->push_back(elem, 0);
	    }
	    vvp_object_t obj(res);
	    thr->push_object(obj);
      } else {
	    vvp_darray*res = four_state
		  ? static_cast<vvp_darray*>(new vvp_darray_vec4(count, ewid))
		  : static_cast<vvp_darray*>(new vvp_darray_vec2(count, ewid));
	    for (size_t i = 0 ; i < count ; i += 1) {
		  vvp_vector4_t elem(ewid, BIT4_0);
		  unsigned top = w - (unsigned)i*ewid;
		  unsigned avail = (top >= ewid) ? ewid : top;
		  elem.set_vec(ewid - avail, val.subvalue(top - avail, avail));
		  res->set_word((unsigned)i, elem);
	    }
	    vvp_object_t obj(res);
	    thr->push_object(obj);
      }

      if (cast_size_error || cast_bound_error
	  || (strict_cast && runtime_limit_error)) {
	    vpip_set_return_value(1);
	    if (!schedule_finished())
		  schedule_finish(0);
	    return false;
      }

      return true;
}

bool of_STREAM_TO_QUEUE(vthread_t thr, vvp_code_t cp)
{
      return do_stream_to_container(thr, cp, true);
}

bool of_STREAM_TO_DAR(vthread_t thr, vvp_code_t cp)
{
      return do_stream_to_container(thr, cp, false);
}

bool of_NEW_VIF(vthread_t thr, vvp_code_t cp)
{
      __vpiScope*scope = dynamic_cast<__vpiScope*> (cp->handle);
      const class_type*defn = reinterpret_cast<const class_type*> (cp->cptr2);

      if (!scope || !defn) {
	    thr->push_object(vvp_object_t());
	    return true;
      }

      vvp_object_t tmp (new vvp_vinterface(scope, defn));
      thr->push_object(tmp);
      return true;
}

/* logical_process_thread_() moved up next to the thread-RNG helpers
   (R3, IEEE 1800-2017 18.13.1) -- it is the resolver both process::self()
   and the RNG hierarchy use to find "the" thread a nested callf/fork_v
   child belongs to. See its definition above, just before
   vpip_object_urandom(). */

static void process_status_to_vec4_(unsigned status, vvp_vector4_t&val)
{
      val = vvp_vector4_t(32, BIT4_0);
      for (unsigned idx = 0 ; idx < 32 ; idx += 1) {
	    if ((status >> idx) & 1U)
		  val.set_bit(idx, BIT4_1);
      }
}

bool of_PROCESS_SELF(vthread_t thr, vvp_code_t)
{
      vthread_t owner = logical_process_thread_(thr);
      if (getenv("IVL_PROC_TRACE"))
	    fprintf(stderr, "[proc] self: thr=%p callf=%d forkv=%d -> owner=%p obj=%p\n",
		    (void*)thr, thr->is_callf_child ? 1 : 0,
		    thr->is_fork_v_child ? 1 : 0, (void*)owner,
		    owner ? (void*)owner->process_obj_.peek<vvp_process>() : 0);
      if (!owner) {
	    thr->push_object(vvp_object_t());
	    return true;
      }

      thr->push_object(owner->process_obj_);
      return true;
}

/*
 * %process/status
 *   Pop a process object and push its live state as a 32-bit vec4
 *   per IEEE 1800-2017 9.7 (FINISHED=0, RUNNING=1, WAITING=2,
 *   SUSPENDED=3, KILLED=4).  A nil handle pushes x.
 */
bool of_PROCESS_STATUS(vthread_t thr, vvp_code_t)
{
      vvp_object_t obj;
      thr->pop_object(obj);

      vvp_process*proc = obj.peek<vvp_process>();
      if (getenv("IVL_PROC_TRACE"))
	    fprintf(stderr, "[proc] status: proc=%p owner=%p st=%u\n",
		    (void*)proc, proc ? (void*)proc->owner() : 0,
		    proc ? proc->status() : 99);
      if (!proc) {
	    thr->push_vec4(vvp_vector4_t(32, BIT4_X));
	    return true;
      }

      vvp_vector4_t val;
      process_status_to_vec4_(proc->status(), val);
      thr->push_vec4(val);
      return true;
}

bool of_PROCESS_AWAIT(vthread_t thr, vvp_code_t)
{
      vvp_object_t obj;
      thr->pop_object(obj);

      vvp_process*proc = obj.peek<vvp_process>();
      if (!proc)
	    return true;

      unsigned status = proc->status();
      if (status == PROCESS_STATE_FINISHED || status == PROCESS_STATE_KILLED)
	    return true;

      if (!proc->add_waiter(thr))
	    return true;   /* not registrable: do not park on it */

	/* Park on the process object the same way a mailbox or semaphore
	   wait parks, so that killing this thread unlinks it from proc's
	   waiter set, and so the scheduler sees it as blocked. `obj' retains
	   proc for as long as the wait is outstanding. */
      vthread_mark_resource_wait(thr, proc, obj,
				 &vvp_process::cancel_await_waiter);
      return false;
}

/*
 * IEEE 1800-2017 9.7.2: kill() terminates the process AND every
 * sub-process it spawned -- "processes spawned using fork statements by
 * the process being killed".
 *
 * do_disable() unwinds thr->children, which is the set a %join is
 * waiting on. A `fork ... join_none' child is DETACHED: it is never
 * joined, so it lives in detached_children instead and that walk never
 * reached it. Killing a parent therefore left its join_none children
 * running, still counting time and still reporting WAITING -- silently,
 * since kill() returned normally and the parent really was dead.
 *
 * Only kill() takes this path. `disable' keeps its own semantics, which
 * are a different clause (9.6.2) and a much larger blast radius.
 */
static void kill_detached_subprocesses_(vthread_t thr)
{
      if (!thr) return;

      while (!thr->detached_children.empty()) {
	    size_t before = thr->detached_children.size();
	    vthread_t kid = *(thr->detached_children.begin());
	    if (!kid) break;

	      /* Depth first, so a grandchild spawned by the detached
		 child goes with it. */
	    kill_detached_subprocesses_(kid);
	    (void) do_disable(kid, kid);

	      /* do_disable reaps a detached thread, which is what
		 removes it from this set. If some path ever leaves it in
		 place, stop rather than spin. */
	    if (thr->detached_children.size() >= before)
		  break;
      }
}

bool of_PROCESS_KILL(vthread_t thr, vvp_code_t)
{
      vvp_object_t obj;
      thr->pop_object(obj);

      vvp_process*proc = obj.peek<vvp_process>();
      if (!proc)
	    return true;

      vthread_t target = proc->owner();
      if (!target)
	    return true;

      unsigned status = proc->status();
      if (status == PROCESS_STATE_FINISHED || status == PROCESS_STATE_KILLED)
	    return true;

      vthread_t self_process = logical_process_thread_(thr);
      bool self_kill = (target == thr) || (target == self_process);

	/* Sub-processes first: once do_disable has run on the target it
	   may already have been reaped, taking the set with it. */
      kill_detached_subprocesses_(target);

      (void)do_disable(target, target);
      return !self_kill;
}

/*
 * The threads that together ARE one logical process.
 *
 * A named begin/end body and a synchronous task frame each execute in
 * their own vthread, but they are not sub-processes: they are the same
 * process, which is why logical_process_thread_() walks straight past
 * them and process::self() inside one returns the enclosing fork thread.
 * While such a child runs, the parent is parked in %join -- so marking
 * the parent alone suspended nothing, and status() then reported
 * SUSPENDED for a process that was still counting time.
 *
 * fork...join_none children are deliberately excluded: those really are
 * sub-processes, and 9.7.2 gives the cascade to kill() only.
 */
static void logical_process_threads_(vthread_t thr, vector<vthread_t>&out)
{
      if (!thr) return;

      out.push_back(thr);

      for (set<vthread_t>::iterator cur = thr->children.begin()
		 ; cur != thr->children.end() ; ++cur) {
	    vthread_t kid = *cur;
	    if (!kid) continue;
	    if (!kid->is_callf_child && !kid->is_fork_v_child) continue;
	    logical_process_threads_(kid, out);
      }
}

/*
 * %process/suspend
 *   Pop a process object and suspend its owning thread (IEEE 1800-2017
 *   9.7.2). A suspended thread is skipped by vthread_run until resumed. If
 *   a process suspends itself the suspension takes effect immediately: the
 *   opcode parks the thread (returns false) after marking it so resume()
 *   will reschedule it to continue. Suspending an already ready/running
 *   thread likewise marks it for reschedule; suspending a thread that is
 *   blocked (waiting on an event/join) leaves the block in place and lets
 *   the eventual wake re-arm the reschedule.
 */
bool of_PROCESS_SUSPEND(vthread_t thr, vvp_code_t)
{
      vvp_object_t obj;
      thr->pop_object(obj);

      vvp_process*proc = obj.peek<vvp_process>();
      if (!proc)
	    return true;

      vthread_t target = proc->owner();
      if (!target)
	    return true;

      unsigned status = proc->status();
      if (status == PROCESS_STATE_FINISHED || status == PROCESS_STATE_KILLED)
	    return true;

	// Idempotent: suspending an already-suspended process is a no-op.
      if (target->suspended)
	    return true;

      vthread_t self_process = logical_process_thread_(thr);
      bool self_suspend = (target == thr) || (target == self_process);

	// Every thread the process is made of, not just the one the handle
	// names: while a named block or a task frame is executing, IT is the
	// thread that has to stop and `target' is parked in %join behind it.
      vector<vthread_t> parts;
      logical_process_threads_(target, parts);

      for (size_t idx = 0 ; idx < parts.size() ; idx += 1) {
	    vthread_t part = parts[idx];
	    part->suspended = 1;

	      // A running/ready thread must be rescheduled by resume() to
	      // make progress. A blocked one (waiting on an event or a join)
	      // will have its reschedule armed by vthread_run when the wake
	      // is delivered.
	    if (part == thr || part->is_scheduled)
		  part->suspend_resched = 1;
      }

	// Self-suspension takes effect immediately: park this thread. It is
	// not placed on any run queue, so only resume() will revive it.
      if (self_suspend) {
	    thr->suspend_resched = 1;
	    return false;
      }

      return true;
}

/*
 * %process/resume
 *   Pop a process object and resume its owning thread (IEEE 1800-2017
 *   9.7.2). Clearing the suspended flag lets vthread_run run it again; if a
 *   run was pending (self-suspended, or an event tried to wake it while it
 *   was suspended) it is rescheduled so it continues where it left off. A
 *   process still blocked on an event with no pending wake simply resumes
 *   waiting.
 */
bool of_PROCESS_RESUME(vthread_t thr, vvp_code_t)
{
      vvp_object_t obj;
      thr->pop_object(obj);

      vvp_process*proc = obj.peek<vvp_process>();
      if (!proc)
	    return true;

      vthread_t target = proc->owner();
      if (!target || !target->suspended)
	    return true;

	// Resume every thread the process is made of -- the same set
	// suspend() stopped. The one that was actually executing is the one
	// that has to be put back on a run queue.
      vector<vthread_t> parts;
      logical_process_threads_(target, parts);

      for (size_t idx = 0 ; idx < parts.size() ; idx += 1) {
	    vthread_t part = parts[idx];
	    if (!part->suspended) continue;

	    part->suspended = 0;

	    if (part->suspend_resched) {
		  part->suspend_resched = 0;
		  if (!part->is_scheduled)
			schedule_vthread(part, 0, true);
	    }
      }

      return true;
}

static vvp_object_t make_darray_for_enc_(const char*text, size_t size)
{
      unsigned word_wid;
      size_t n;

      vvp_object_t obj;
      if (!text) {
	    return obj;
      } else if (strcmp(text,"b8") == 0) {
	    obj = new vvp_darray_atom<uint8_t>(size);
      } else if (strcmp(text,"b16") == 0) {
	    obj = new vvp_darray_atom<uint16_t>(size);
      } else if (strcmp(text,"b32") == 0) {
	    obj = new vvp_darray_atom<uint32_t>(size);
      } else if (strcmp(text,"b64") == 0) {
	    obj = new vvp_darray_atom<uint64_t>(size);
      } else if (strcmp(text,"sb8") == 0) {
	    obj = new vvp_darray_atom<int8_t>(size);
      } else if (strcmp(text,"sb16") == 0) {
	    obj = new vvp_darray_atom<int16_t>(size);
      } else if (strcmp(text,"sb32") == 0) {
	    obj = new vvp_darray_atom<int32_t>(size);
      } else if (strcmp(text,"sb64") == 0) {
	    obj = new vvp_darray_atom<int64_t>(size);
      } else if ((1 == sscanf(text, "b%u%zn", &word_wid, &n)) &&
                 (n == strlen(text))) {
	    obj = new vvp_darray_vec2(size, word_wid);
      } else if ((1 == sscanf(text, "sb%u%zn", &word_wid, &n)) &&
                 (n == strlen(text))) {
	    obj = new vvp_darray_vec2(size, word_wid);
      } else if ((1 == sscanf(text, "v%u%zn", &word_wid, &n)) &&
                 (n == strlen(text))) {
	    obj = new vvp_darray_vec4(size, word_wid);
      } else if ((1 == sscanf(text, "sv%u%zn", &word_wid, &n)) &&
                 (n == strlen(text))) {
	    obj = new vvp_darray_vec4(size, word_wid);
      } else if (strcmp(text,"r") == 0) {
	    obj = new vvp_darray_real(size);
      } else if (strcmp(text,"S") == 0) {
	    obj = new vvp_darray_string(size);
      } else if (strcmp(text,"o") == 0) {
	    obj = new vvp_darray_object(size);
      } else {
            return vvp_object_t();
      }

      return obj;
}

enum container_element_kind_t {
      CONTAINER_ELEMENT_INVALID,
      CONTAINER_ELEMENT_REAL,
      CONTAINER_ELEMENT_STRING,
      CONTAINER_ELEMENT_OBJECT,
      CONTAINER_ELEMENT_VECTOR
};

struct container_element_encoding_t {
      container_element_kind_t kind;
      unsigned word_wid;
      bool four_state;
      bool is_signed;
};

/* Decode the element spelling shared by %new/darray, %new/queue, and the
 * destination-typed container conversion opcodes. Signedness affects vector
 * extension; b/sb selects IEEE 1800-2017/2023 6.11.2 2-state coercion while
 * v/sv preserves X/Z. */
static bool decode_container_element_encoding_(
      const char*text, container_element_encoding_t&enc)
{
      size_t n = 0;

      enc.kind = CONTAINER_ELEMENT_INVALID;
      enc.word_wid = 0;
      enc.four_state = false;
      enc.is_signed = false;
      if (!text)
	    return false;

      if (strcmp(text, "r") == 0) {
	    enc.kind = CONTAINER_ELEMENT_REAL;
	    return true;
      }
      if (strcmp(text, "S") == 0) {
	    enc.kind = CONTAINER_ELEMENT_STRING;
	    return true;
      }
      if (strcmp(text, "o") == 0) {
	    enc.kind = CONTAINER_ELEMENT_OBJECT;
	    return true;
      }

      if ((1 == sscanf(text, "b%u%zn", &enc.word_wid, &n))
	  && n == strlen(text)) {
	    enc.kind = CONTAINER_ELEMENT_VECTOR;
      } else if ((1 == sscanf(text, "sb%u%zn", &enc.word_wid, &n))
		 && n == strlen(text)) {
	    enc.kind = CONTAINER_ELEMENT_VECTOR;
	    enc.is_signed = true;
      } else if ((1 == sscanf(text, "v%u%zn", &enc.word_wid, &n))
		 && n == strlen(text)) {
	    enc.kind = CONTAINER_ELEMENT_VECTOR;
	    enc.four_state = true;
      } else if ((1 == sscanf(text, "sv%u%zn", &enc.word_wid, &n))
		 && n == strlen(text)) {
	    enc.kind = CONTAINER_ELEMENT_VECTOR;
	    enc.four_state = true;
	    enc.is_signed = true;
      }

      if (enc.kind == CONTAINER_ELEMENT_VECTOR && enc.word_wid == 0) {
	    enc.kind = CONTAINER_ELEMENT_INVALID;
	    return false;
      }
      return enc.kind != CONTAINER_ELEMENT_INVALID;
}

bool vvp_container_element_encoding_is_valid(const char*text)
{
      container_element_encoding_t enc;
      return decode_container_element_encoding_(text, enc);
}

/* Runtime validation is a defensive backstop for internally constructed or
 * corrupted code records. Parsed VVP images are rejected by compile.cc before
 * scheduling. Keep the opcode fallback non-asserting and return a process
 * failure so malformed bytecode cannot turn into SIGABRT. */
static bool container_opcode_runtime_fatal_()
{
      vpip_set_return_value(1);
      if (!schedule_finished())
	    schedule_finish(0);
      return false;
}

static vvp_vector4_t coerce_container_vector_(
      const vvp_vector4_t&value, const container_element_encoding_t&enc)
{
      vvp_bit4_t fill = BIT4_0;
      if (enc.is_signed && value.size() != 0)
	    fill = value.value(value.size()-1);

      vvp_vector4_t result(enc.word_wid, fill);
      unsigned copy_wid = min(enc.word_wid, value.size());
      if (copy_wid)
	    result.set_vec(0, value.subvalue(0, copy_wid));
      if (!enc.four_state)
	    result = vector2_to_vector4(vvp_vector2_t(result), result.size());
      return result;
}

bool of_NEW_DARRAY(vthread_t thr, vvp_code_t cp)
{
      const char*text = cp->text;
      size_t size = thr->words[cp->bit_idx[0]].w_int;
      vvp_object_t obj = make_darray_for_enc_(text, size);
      if (obj.test_nil()) {
            cerr << get_fileline()
                 << "Internal error: Unsupported dynamic array type: "
                 << text << "." << endl;
            assert(0);
      }

      thr->push_object(obj);

      return true;
}

/* Build a fresh destination-typed dynamic-array value from any positional
 * runtime collection. This is shared by whole-container conversion and by
 * object-collection splices whose declared inner element is a darray. A null
 * or non-container source intentionally produces an empty declared target;
 * the splice caller diagnoses a non-container element at its own boundary. */
static vvp_object_t materialize_darray_for_enc_(
      const vvp_object_t&src_obj, const char*text,
      const class_type*elem_class_override, bool&valid)
{
      vvp_darray*src = src_obj.peek<vvp_darray>();
      size_t size = src ? src->get_size() : 0;
      container_element_encoding_t enc;
      vvp_object_t dst_obj = make_darray_for_enc_(text, size);
      vvp_darray*dst = dst_obj.peek<vvp_darray>();

      valid = decode_container_element_encoding_(text, enc) && dst;
      if (!valid)
	    return vvp_object_t();

      if (src) {
            for (size_t idx = 0; idx < size; idx += 1) {
		  if (enc.kind == CONTAINER_ELEMENT_REAL) {
                        double value = 0.0;
                        src->get_word(idx, value);
                        dst->set_word(idx, value);
		  } else if (enc.kind == CONTAINER_ELEMENT_STRING) {
                        string value;
                        src->get_word(idx, value);
                        dst->set_word(idx, value);
		  } else if (enc.kind == CONTAINER_ELEMENT_OBJECT) {
                        vvp_object_t value;
                        src->get_word(idx, value);
                        dst->set_word(idx, value.value_copy_element());
		  } else {
			vvp_vector4_t value;
                        src->get_word(idx, value);
			dst->set_word(idx,
			      coerce_container_vector_(value, enc));
                  }
            }
	    src->copy_passive_value_metadata_to(dst);
      }

      if (elem_class_override)
	    dst->set_elem_class(elem_class_override);

      return dst_obj;
}

/*
 * %queue/to/darray "<element-encoding>"
 *
 * Pop any queue/dynamic-array value and push a fresh destination-typed dynamic
 * array with the same elements. The legacy opcode spelling is retained for
 * generated-image compatibility. Besides unpacked-array concatenations, this
 * supports whole-container assignment without leaking the source's runtime
 * kind into later indexing or DPI operations (IEEE 1800-2017/2023 7.6).
 * The original concatenation use remains governed by 7.5 and 10.10.
 */
bool of_QUEUE_TO_DARRAY(vthread_t thr, vvp_code_t cp)
{
      vvp_object_t src_obj;
      thr->pop_object(src_obj);
      bool valid = false;
      vvp_object_t dst_obj = materialize_darray_for_enc_(
	    src_obj, cp->text, 0, valid);

      if (!valid) {
	    cerr << thr->get_fileline()
		 << "VVP error: malformed %queue/to/darray element encoding '"
		 << (cp->text ? cp->text : "<null>") << "'." << endl;
	    /* The opcode consumes one object and produces one object even on
	     * failure, so a diagnostic path cannot unbalance its caller. */
	    thr->push_object(dst_obj);
	    return container_opcode_runtime_fatal_();
      }

      thr->push_object(dst_obj);
      return true;
}

/* Make a fresh empty dynamic container. Legacy element-kind encodings make
 * queues for %new/queue and older load-or-vivify VVP. "@N" is the nested
 * dynamic-container spec shared with %aa/viv, and can also make an
 * associative child. Returns nil for an unknown encoding. */
static vvp_object_t make_queue_for_enc_(const char*text)
{
      unsigned word_wid;
      unsigned container_spec;
      size_t n;

      vvp_object_t obj;
      if (!text) {
	    return obj;
      } else if ((1 == sscanf(text, "@%u%zn", &container_spec, &n))
	  && (n == strlen(text))) {
	    obj = make_dynamic_container_from_code_(container_spec);
      } else if (strcmp(text, "r") == 0) {
	    obj = new vvp_queue_real;
      } else if (strcmp(text, "S") == 0) {
	    obj = new vvp_queue_string;
      } else if (strcmp(text, "o") == 0) {
	    obj = new vvp_queue_object;
      } else if ((1 == sscanf(text, "b%u%zn", &word_wid, &n))
		 && (n == strlen(text))) {
	    obj = new vvp_queue_vec4;
      } else if ((1 == sscanf(text, "sb%u%zn", &word_wid, &n))
		 && (n == strlen(text))) {
	    obj = new vvp_queue_vec4;
      } else if ((1 == sscanf(text, "v%u%zn", &word_wid, &n))
		 && (n == strlen(text))) {
	    obj = new vvp_queue_vec4;
      } else if ((1 == sscanf(text, "sv%u%zn", &word_wid, &n))
		 && (n == strlen(text))) {
	    obj = new vvp_queue_vec4;
      }
      return obj;
}

/* Build a fresh destination-typed queue value from any positional runtime
 * collection. A zero maximum is unbounded. Passive value metadata follows the
 * copy, after which a declared unpacked-struct prototype (when supplied) wins
 * over metadata carried by the source object's runtime type. */
static vvp_object_t materialize_queue_for_enc_(
      const vvp_object_t&src_obj, const char*text, unsigned max_size,
      const class_type*elem_class_override, bool&valid)
{
      vvp_darray*src = src_obj.peek<vvp_darray>();
      container_element_encoding_t enc;
      vvp_object_t dst_obj = make_queue_for_enc_(text);
      vvp_queue*dst = dst_obj.peek<vvp_queue>();

      valid = decode_container_element_encoding_(text, enc) && dst;
      if (!valid)
	    return vvp_object_t();

      if (src) {
	    dst->copy_elems(src_obj, max_size);
	    if (enc.kind == CONTAINER_ELEMENT_VECTOR) {
		  for (size_t idx = 0; idx < dst->get_size(); idx += 1) {
			vvp_vector4_t value;
			dst->get_word(idx, value);
			dst->set_word(idx,
			      coerce_container_vector_(value, enc));
		  }
	    }
	    src->copy_passive_value_metadata_to(dst);
      }

      if (elem_class_override)
	    dst->set_elem_class(elem_class_override);

      return dst_obj;
}

/*
 * %container/to/queue "<element-encoding>", <max>
 *
 * Pop any queue/dynamic-array value and push a fresh destination-typed queue.
 * A zero maximum is unbounded. Element copying goes through the destination
 * encoding, including IEEE 1800-2017/2023 6.11.2 X/Z-to-zero coercion for
 * b/sb elements.
 */
bool of_CONTAINER_TO_QUEUE(vthread_t thr, vvp_code_t cp)
{
      vvp_object_t src_obj;
      thr->pop_object(src_obj);
      bool valid = false;
      vvp_object_t dst_obj = materialize_queue_for_enc_(
	    src_obj, cp->text, cp->bit_idx[0], 0, valid);

      if (!valid) {
	    cerr << get_fileline()
		 << "VVP error: malformed %container/to/queue element encoding '"
		 << (cp->text ? cp->text : "<null>") << "'." << endl;
	    thr->push_object(dst_obj);
	    return container_opcode_runtime_fatal_();
      }

      thr->push_object(dst_obj);
      return true;
}

bool of_NEW_QUEUE(vthread_t thr, vvp_code_t cp)
{
      const char*text = cp->text;

      vvp_object_t obj = make_queue_for_enc_(text);
      if (obj.test_nil()) {
	    cerr << get_fileline()
		 << "Internal error: Unsupported queue type: "
		 << text << "." << endl;
	    assert(0);
      }

      thr->push_object(obj);
      return true;
}

bool of_NOOP(vthread_t, vvp_code_t)
{
      return true;
}

/*
 * %nor/r
 */
bool of_NORR(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t val = thr->pop_vec4();

      vvp_bit4_t lb = BIT4_1;

      for (unsigned idx = 0 ;  idx < val.size() ;  idx += 1) {

	    vvp_bit4_t rb = val.value(idx);
	    if (rb == BIT4_1) {
		  lb = BIT4_0;
		  break;
	    }

	    if (rb != BIT4_0)
		  lb = BIT4_X;
      }

      vvp_vector4_t res (1, lb);
      thr->push_vec4(res);

      return true;
}

/*
 * Push a null to the object stack.
 */
bool of_NULL(vthread_t thr, vvp_code_t)
{
      vvp_object_t tmp;
      thr->push_object(tmp);
      return true;
}

/*
 * %and/r
 */
bool of_ANDR(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t val = thr->pop_vec4();

      vvp_bit4_t lb = BIT4_1;

      for (unsigned idx = 0 ; idx < val.size() ; idx += 1) {
	    vvp_bit4_t rb = val.value(idx);
	    if (rb == BIT4_0) {
		  lb = BIT4_0;
		  break;
	    }

	    if (rb != 1)
		  lb = BIT4_X;
      }

      vvp_vector4_t res (1, lb);
      thr->push_vec4(res);

      return true;
}

/*
 * %nand/r
 */
bool of_NANDR(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t val = thr->pop_vec4();

      vvp_bit4_t lb = BIT4_0;
      for (unsigned idx = 0 ; idx < val.size() ; idx += 1) {

	    vvp_bit4_t rb = val.value(idx);
	    if (rb == BIT4_0) {
		  lb = BIT4_1;
		  break;
	    }

	    if (rb != BIT4_1)
		  lb = BIT4_X;
      }

      vvp_vector4_t res (1, lb);
      thr->push_vec4(res);

      return true;
}

/*
 * %or/r
 */
bool of_ORR(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t val = thr->pop_vec4();

      vvp_bit4_t lb = BIT4_0;
      for (unsigned idx = 0 ; idx < val.size() ; idx += 1) {
	    vvp_bit4_t rb = val.value(idx);
	    if (rb == BIT4_1) {
		  lb = BIT4_1;
		  break;
	    }

	    if (rb != BIT4_0)
		  lb = BIT4_X;
      }

      vvp_vector4_t res (1, lb);
      thr->push_vec4(res);
      return true;
}

/*
 * %xor/r
 */
bool of_XORR(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t val = thr->pop_vec4();

      vvp_bit4_t lb = BIT4_0;
      for (unsigned idx = 0 ; idx < val.size() ; idx += 1) {

	    vvp_bit4_t rb = val.value(idx);
	    if (rb == BIT4_1)
		  lb = ~lb;
	    else if (rb != BIT4_0) {
		  lb = BIT4_X;
		  break;
	    }
      }

      vvp_vector4_t res (1, lb);
      thr->push_vec4(res);
      return true;
}

/*
 * %xnor/r
 */
bool of_XNORR(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t val = thr->pop_vec4();

      vvp_bit4_t lb = BIT4_1;
      for (unsigned idx = 0 ; idx < val.size() ; idx += 1) {

	    vvp_bit4_t rb = val.value(idx);
	    if (rb == BIT4_1)
		  lb = ~lb;
	    else if (rb != BIT4_0) {
		  lb = BIT4_X;
		  break;
	    }
      }

      vvp_vector4_t res (1, lb);
      thr->push_vec4(res);
      return true;
}

/*
 * %or
 */
bool of_OR(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t valb = thr->pop_vec4();
      vvp_vector4_t&vala = thr->peek_vec4();
      vala |= valb;
      return true;
}

/*
 * %nor
 */
bool of_NOR(vthread_t thr, vvp_code_t)
{
      vvp_vector4_t valr = thr->pop_vec4();
      vvp_vector4_t&vall = thr->peek_vec4();
      assert(vall.size() == valr.size());
      unsigned wid = vall.size();

      for (unsigned idx = 0 ; idx < wid ; idx += 1) {
	    vvp_bit4_t lb = vall.value(idx);
	    vvp_bit4_t rb = valr.value(idx);
	    vall.set_bit(idx, ~(lb|rb));
      }

      return true;
}

/*
 * %pop/obj <num>, <skip>
 */
bool of_POP_OBJ(vthread_t thr, vvp_code_t cp)
{
      unsigned cnt = cp->bit_idx[0];
      unsigned skip = cp->bit_idx[1];

      thr->pop_object(cnt, skip);
      return true;
}

/*
 * %pop/real <number>
 */
bool of_POP_REAL(vthread_t thr, vvp_code_t cp)
{
      unsigned cnt = cp->number;
      thr->pop_real(cnt);
      return true;
}

/*
 *  %pop/str <number>
 */
bool of_POP_STR(vthread_t thr, vvp_code_t cp)
{
      unsigned cnt = cp->number;
      thr->pop_str(cnt);
      return true;
}

/*
 *  %pop/vec4 <number>
 */
bool of_POP_VEC4(vthread_t thr, vvp_code_t cp)
{
      unsigned cnt = cp->number;
      thr->pop_vec4(cnt);
      return true;
}

/*
 * %pow
 * %pow/s
 */
static bool of_POW_base(vthread_t thr, bool signed_flag)
{
      vvp_vector4_t valb = thr->pop_vec4();
      vvp_vector4_t vala = thr->pop_vec4();

      unsigned wid = vala.size();

      vvp_vector2_t xv2 = vvp_vector2_t(vala, true);
      vvp_vector2_t yv2 = vvp_vector2_t(valb, true);


        /* If we have an X or Z in the arguments return X. */
      if (xv2.is_NaN() || yv2.is_NaN()) {
	    vvp_vector4_t tmp (wid, BIT4_X);
	    thr->push_vec4(tmp);
	    return true;
      }

	// Is the exponent negative? If so, table 5-6 in IEEE1364-2005
	// defines what value is returned.
      if (signed_flag && yv2.value(yv2.size()-1)) {
	    int a_val;
	    vvp_bit4_t pad = BIT4_0, lsb = BIT4_0;
	    if (vector2_to_value(xv2, a_val, true)) {
		  if (a_val == 0) {
			pad = BIT4_X; lsb = BIT4_X;
		  }
		  if (a_val == 1) {
			pad = BIT4_0; lsb = BIT4_1;
		  }
		  if (a_val == -1) {
			if (yv2.value(0)) {
			      pad = BIT4_1; lsb = BIT4_1;
			} else {
			      pad = BIT4_0; lsb = BIT4_1;
			}
		  }
	    }
	    vvp_vector4_t tmp (wid, pad);
	    tmp.set_bit(0, lsb);
	    thr->push_vec4(tmp);
	    return true;
      }

      vvp_vector2_t result = pow(xv2, yv2);

        /* Copy only what we need of the result. If the result is too
	   small, zero-pad it. */
      for (unsigned jdx = 0;  jdx < wid;  jdx += 1) {
	    if (jdx >= result.size())
		  vala.set_bit(jdx, BIT4_0);
	    else
		  vala.set_bit(jdx, result.value(jdx) ? BIT4_1 : BIT4_0);
      }
      thr->push_vec4(vala);

      return true;
}

bool of_POW(vthread_t thr, vvp_code_t)
{
      return of_POW_base(thr, false);
}

bool of_POW_S(vthread_t thr, vvp_code_t)
{
      return of_POW_base(thr, true);
}

bool of_POW_WR(vthread_t thr, vvp_code_t)
{
      double r = thr->pop_real();
      double l = thr->pop_real();
      thr->push_real(pow(l,r));

      return true;
}

/*
 * %prop/obj <pid>, <idx>
 *
 * Load an object value from the cobject and push it onto the object stack.
 */
static const char*prop_trace_obj_kind_(const vvp_object_t&obj);
static const char*prop_trace_receiver_class_(const vvp_object_t&obj);
static bool prop_pid_in_range_(const vvp_object_t&obj, size_t pid, size_t*count_out);
static void prop_trace_log_(vthread_t thr, const char*op, size_t pid, unsigned idx, const vvp_object_t&obj, bool has_propobj);

struct fixed_prop_receiver_t {
      vvp_cobject*cobj;
      vvp_vinterface*vif;

      const class_type* defn(void) const
      {
	    return cobj ? cobj->get_defn() : (vif ? vif->get_defn() : 0);
      }

      void get_vec4(size_t pid, vvp_vector4_t&val, size_t idx) const
      {
	    if (cobj) cobj->get_vec4(pid, val, idx);
	    else if (vif) vif->get_vec4(pid, val, idx);
      }
      void set_vec4(size_t pid, const vvp_vector4_t&val, size_t idx) const
      {
	    if (cobj) cobj->set_vec4(pid, val, idx);
	    else if (vif) vif->set_vec4(pid, val, idx);
      }
      double get_real(size_t pid, size_t idx) const
      {
	    return cobj ? cobj->get_real(pid, idx)
			: (vif ? vif->get_real(pid, idx) : 0.0);
      }
      void set_real(size_t pid, double val, size_t idx) const
      {
	    if (cobj) cobj->set_real(pid, val, idx);
	    else if (vif) vif->set_real(pid, val, idx);
      }
      string get_string(size_t pid, size_t idx) const
      {
	    return cobj ? cobj->get_string(pid, idx)
			: (vif ? vif->get_string(pid, idx) : string());
      }
      void set_string(size_t pid, const string&val, size_t idx) const
      {
	    if (cobj) cobj->set_string(pid, val, idx);
	    else if (vif) vif->set_string(pid, val, idx);
      }
      void get_object(size_t pid, vvp_object_t&val, size_t idx) const
      {
	    if (cobj) cobj->get_object(pid, val, idx);
	    else if (vif) vif->get_object(pid, val, idx);
      }
      void set_object(size_t pid, const vvp_object_t&val, size_t idx) const
      {
	    if (cobj) cobj->set_object(pid, val, idx);
	    else if (vif) vif->set_object(pid, val, idx);
      }
};

static size_t fixed_prop_range_size_(const pair<int,int>&range)
{
      return range.first > range.second
	   ? (size_t)((int64_t)range.first - range.second) + 1
	   : (size_t)((int64_t)range.second - range.first) + 1;
}

static vvp_darray* fixed_prop_leaf_(const string&type, size_t size)
{
      if (type == "b8")   return new vvp_darray_atom<uint8_t>(size);
      if (type == "b16")  return new vvp_darray_atom<uint16_t>(size);
      if (type == "b32")  return new vvp_darray_atom<uint32_t>(size);
      if (type == "b64")  return new vvp_darray_atom<uint64_t>(size);
      if (type == "sb8")  return new vvp_darray_atom<int8_t>(size);
      if (type == "sb16") return new vvp_darray_atom<int16_t>(size);
      if (type == "sb32") return new vvp_darray_atom<int32_t>(size);
      if (type == "sb64") return new vvp_darray_atom<int64_t>(size);
      if (type == "r")    return new vvp_darray_real(size);
      if (type == "S")    return new vvp_darray_string(size);
      if (type == "o" || type.compare(0, 3, "oc:") == 0)
	    return new vvp_darray_object(size);

      const char*cp = type.c_str();
      bool is_signed = false;
      if (cp[0] == 's') {
	    is_signed = true;
	    cp += 1;
      }
      char flavor = *cp++;
      unsigned width = (unsigned)strtoul(cp, 0, 10);
      if (width == 0) width = 1;
      if (flavor == 'b')
	    return new vvp_darray_vec2(size, width);
      if (flavor == 'L')
	    return new vvp_darray_vec4(size, width);

      (void)is_signed;
      return new vvp_darray_object(size);
}

static vvp_object_t fixed_prop_materialize_(
      const fixed_prop_receiver_t&recv, size_t pid,
      const vector<pair<int,int> >&dimensions, size_t dim, size_t&flat)
{
      const class_type*defn = recv.defn();
      if (!defn || dim >= dimensions.size())
	    return vvp_object_t();

      size_t count = fixed_prop_range_size_(dimensions[dim]);
      vvp_object_t out;
      vvp_darray*array = 0;
      if (dim + 1 < dimensions.size())
	    out = array = new vvp_darray_object(count);
      else
	    out = array = fixed_prop_leaf_(defn->property_base_type(pid), count);

      array->dpi_set_decl_range(dimensions[dim].first,
				dimensions[dim].second);

      if (dim + 1 < dimensions.size()) {
	    for (size_t idx = 0 ; idx < count ; idx += 1) {
		  vvp_object_t inner =
			fixed_prop_materialize_(recv, pid, dimensions,
						dim + 1, flat);
		  array->set_word((unsigned)idx, inner);
	    }
	    return out;
      }

      const string&type = defn->property_base_type(pid);
      for (size_t idx = 0 ; idx < count ; idx += 1, flat += 1) {
	    if (type == "r") {
		  array->set_word((unsigned)idx, recv.get_real(pid, flat));
	    } else if (type == "S") {
		  array->set_word((unsigned)idx, recv.get_string(pid, flat));
	    } else if (type == "o" || type.compare(0, 3, "oc:") == 0) {
		  vvp_object_t val;
		  recv.get_object(pid, val, flat);
		  array->set_word((unsigned)idx, val);
	    } else {
		  vvp_vector4_t val;
		  recv.get_vec4(pid, val, flat);
		  array->set_word((unsigned)idx, val);
	    }
      }
      return out;
}

static size_t fixed_prop_subtree_size_(
      const vector<pair<int,int> >&dimensions, size_t dim)
{
      size_t size = 1;
      for ( ; dim < dimensions.size() ; dim += 1)
	    size *= fixed_prop_range_size_(dimensions[dim]);
      return size;
}

static size_t fixed_prop_copy_source_index_(
      const vvp_darray*array, const pair<int,int>&destination, size_t index,
      size_t count)
{
      return fixed_copy_source_index_(
	    array, destination.first > destination.second, index, count);
}

static void fixed_prop_copy_back_(
      const fixed_prop_receiver_t&recv, size_t pid, vvp_darray*array,
      const vector<pair<int,int> >&dimensions, size_t dim, size_t&flat)
{
      if (dim >= dimensions.size())
	    return;

      size_t count = fixed_prop_range_size_(dimensions[dim]);
      size_t available = array ? min(count, array->get_size()) : 0;
      if (dim + 1 < dimensions.size()) {
	    for (size_t idx = 0 ; idx < count ; idx += 1) {
		  size_t source_idx = fixed_prop_copy_source_index_(
			array, dimensions[dim], idx, count);
		  if (source_idx < available) {
			vvp_object_t word;
			array->get_word((unsigned)source_idx, word);
			fixed_prop_copy_back_(recv, pid,
					     word.peek<vvp_darray>(),
					     dimensions, dim + 1, flat);
		  } else {
			flat += fixed_prop_subtree_size_(dimensions, dim + 1);
		  }
	    }
	    return;
      }

      const class_type*defn = recv.defn();
      const string&type = defn->property_base_type(pid);
      for (size_t idx = 0 ; idx < count ; idx += 1, flat += 1) {
	    size_t source_idx = fixed_prop_copy_source_index_(
		  array, dimensions[dim], idx, count);
	    if (source_idx >= available)
		  continue;
	    if (type == "r") {
		  double val = 0.0;
		  array->get_word((unsigned)source_idx, val);
		  recv.set_real(pid, val, flat);
	    } else if (type == "S") {
		  string val;
		  array->get_word((unsigned)source_idx, val);
		  recv.set_string(pid, val, flat);
	    } else if (type == "o" || type.compare(0, 3, "oc:") == 0) {
		  vvp_object_t val;
		  array->get_word((unsigned)source_idx, val);
		  recv.set_object(pid, val, flat);
	    } else {
		  vvp_vector4_t val;
		  array->get_word((unsigned)source_idx, val);
		  recv.set_vec4(pid, val, flat);
	    }
      }
}

struct checked_property_index_dim_t {
      bool is_signed;
      int64_t low;
      uint64_t width;
      uint64_t stride;
};

static bool checked_property_index_parse_i64_(const char*&cursor,
                                              int64_t&value)
{
      char*end = 0;
      errno = 0;
      long long parsed = strtoll(cursor, &end, 10);
      if (end == cursor || errno == ERANGE || *end != ':')
            return false;
      value = (int64_t)parsed;
      cursor = end + 1;
      return true;
}

static bool checked_property_index_parse_u64_(const char*&cursor,
                                              uint64_t&value,
                                              char delimiter)
{
      char*end = 0;
      if (*cursor == '-')
            return false;
      errno = 0;
      unsigned long long parsed = strtoull(cursor, &end, 10);
      if (end == cursor || errno == ERANGE || *end != delimiter)
            return false;
      value = (uint64_t)parsed;
      cursor = delimiter ? end + 1 : end;
      return true;
}

/* Convert the complete mathematical value of RAW to the signed-64 domain
 * used by declared unpacked-array bounds. Wide values are accepted only when
 * all discarded bits are a valid sign extension; an unsigned bit 63 or any
 * higher set bit is therefore OOB instead of being reinterpreted as negative. */
static bool checked_property_index_value_(const vvp_vector4_t&raw,
                                          bool is_signed, int64_t&value)
{
      unsigned width = raw.size();
      uint64_t bits = 0;
      unsigned idx;

      if (width == 0 || raw.has_xz())
            return false;

      for (idx = 0 ; idx < width && idx < 64 ; idx += 1)
            if (raw.value(idx) == BIT4_1)
                  bits |= UINT64_C(1) << idx;

      if (!is_signed) {
            if ((width >= 64 && raw.value(63) == BIT4_1))
                  return false;
            for (idx = 64 ; idx < width ; idx += 1)
                  if (raw.value(idx) != BIT4_0)
                        return false;
      } else if (width < 64) {
            if (raw.value(width - 1) == BIT4_1)
                  bits |= UINT64_MAX << width;
      } else if (width > 64) {
            vvp_bit4_t extension = raw.value(63);
            for (idx = 64 ; idx < width ; idx += 1)
                  if (raw.value(idx) != extension)
                        return false;
      }

      value = (int64_t)bits;
      return true;
}

/* %prop/index/check "N|s:low:width:stride;..."
 *
 * The N raw index vectors are already on the vec4 stack in declared
 * left-to-right order. Pop all of them even after an invalid dimension, then
 * return X64 for X/Z, OOB, metadata, or arithmetic overflow; otherwise return
 * the canonical flat index. */
bool of_PROP_INDEX_CHECK(vthread_t thr, vvp_code_t cp)
{
      const char*cursor = cp->text ? cp->text : "";
      char*count_end = 0;
      errno = 0;
      unsigned long parsed_count = strtoul(cursor, &count_end, 10);
      bool valid = count_end != cursor && errno != ERANGE
            && *count_end == '|' && parsed_count <= 65536;
      unsigned count = valid ? (unsigned)parsed_count : 0;
      vector<checked_property_index_dim_t> dims;

      if (valid) {
            cursor = count_end + 1;
            dims.resize(count);
            for (unsigned idx = 0 ; idx < count && valid ; idx += 1) {
                  checked_property_index_dim_t&dim = dims[idx];
                  if ((*cursor != 's' && *cursor != 'u') || cursor[1] != ':') {
                        valid = false;
                        break;
                  }
                  dim.is_signed = *cursor == 's';
                  cursor += 2;
                  valid = checked_property_index_parse_i64_(cursor, dim.low)
                        && checked_property_index_parse_u64_(cursor, dim.width, ':')
                        && checked_property_index_parse_u64_(
                              cursor, dim.stride,
                              idx + 1 < count ? ';' : '\0')
                        && dim.width != 0;
            }
            if (valid && *cursor != '\0')
                  valid = false;
      }

      uint64_t flat = 0;
      for (unsigned rev = count ; rev > 0 ; rev -= 1) {
            vvp_vector4_t raw = thr->pop_vec4();
            if (!valid)
                  continue;

            const checked_property_index_dim_t&dim = dims[rev - 1];
            int64_t raw_value = 0;
            if (!checked_property_index_value_(raw, dim.is_signed, raw_value)
                || raw_value < dim.low) {
                  valid = false;
                  continue;
            }

            uint64_t delta = (uint64_t)raw_value - (uint64_t)dim.low;
            if (delta >= dim.width
                || (dim.stride && delta > UINT64_MAX / dim.stride)) {
                  valid = false;
                  continue;
            }

            uint64_t contribution = delta * dim.stride;
            if (contribution > UINT64_MAX - flat) {
                  valid = false;
                  continue;
            }
            flat += contribution;
      }

      if (!valid) {
            thr->push_vec4(vvp_vector4_t(64, BIT4_X));
            return true;
      }

      vvp_vector4_t result(64, BIT4_0);
      for (unsigned idx = 0 ; idx < 64 ; idx += 1)
            if ((flat >> idx) & UINT64_C(1))
                  result.set_bit(idx, BIT4_1);
      thr->push_vec4(result);
      return true;
}

/*
 * %prop/arr/dar <pid>
 *
 * Materialize an inline fixed-array property as a nested dynamic-array
 * object. The receiver remains below the new value on the object stack.
 */
bool of_PROP_ARR_DAR(vthread_t thr, vvp_code_t cp)
{
      size_t pid = cp->number;
      vvp_object_t&obj = thr->peek_object();
      fixed_prop_receiver_t recv = {
	    obj.peek<vvp_cobject>(), obj.peek<vvp_vinterface>()
      };
      const class_type*defn = recv.defn();
      if (!defn || pid >= defn->property_count()
	  || defn->property_dimensions(pid).empty()) {
	    thr->push_object(vvp_object_t(), thr->peek_object_source_net(0),
			     thr->peek_object_root(0));
	    return true;
      }

      size_t flat = 0;
      vvp_object_t val = fixed_prop_materialize_(
	    recv, pid, defn->property_dimensions(pid), 0, flat);
      reverse_descending_fixed_dimensions_(val.peek<vvp_darray>());
      thr->push_object(val, thr->peek_object_source_net(0),
		       thr->peek_object_root(0));
      return true;
}

bool of_PROP_OBJ(vthread_t thr, vvp_code_t cp)
{
      unsigned pid = cp->number;
      unsigned idx = cp->bit_idx[0];

      if (idx != 0) {
	    assert(idx < vthread_s::WORDS_COUNT);
	    idx = thr->words[idx].w_uint;
      }

      vvp_object_t&obj = thr->peek_object();
      vvp_cobject*cobj = obj.peek<vvp_cobject>();
      vvp_vinterface*vif = obj.peek<vvp_vinterface>();
      bool has_propobj = cobj != 0 || vif != 0;
      prop_trace_log_(thr, "%prop/obj", pid, idx, obj, has_propobj);
      if (!has_propobj) {
	    static bool warned = false;
	    if (!warned) {
		  const char*scope_name = scope_name_or_unknown_(thr ? thr->parent_scope : 0);
		  cerr << thr->get_fileline()
		       << "Warning: %prop/obj on null/unsupported object handle"
		       << " (pid=" << pid << ", idx=" << idx << ")"
		       << " scope=" << scope_name
		       << " receiver=" << prop_trace_obj_kind_(obj)
		       << " class=" << prop_trace_receiver_class_(obj)
		       << "; using null object fallback." << endl;
		  warned = true;
	    }
	    vvp_object_t val;
	    val.reset();
	    thr->push_object(val, thr->peek_object_source_net(0), thr->peek_object_root(0));
	    return true;
      }

      size_t prop_count = 0;
      if (!prop_pid_in_range_(obj, pid, &prop_count)) {
            static bool warned = false;
            if (!warned) {
                  cerr << thr->get_fileline()
                       << "Warning: %prop/obj pid=" << pid
                       << " out of range for receiver class "
                       << prop_trace_receiver_class_(obj)
                       << " (size=" << prop_count << ")"
                       << "; using null object fallback."
                       << " scope=" << scope_name_or_unknown_(thr ? thr->parent_scope : 0)
                       << endl;
                  warned = true;
            }
            vvp_object_t val;
            val.reset();
            thr->push_object(val, thr->peek_object_source_net(0), thr->peek_object_root(0));
            return true;
      }

      vvp_object_t val;
      if (cobj)
	    cobj->get_object(pid, val, idx);
      else
	    vif->get_object(pid, val, idx);

      thr->push_object(val, thr->peek_object_source_net(0), thr->peek_object_root(0));

      return true;
}

