/*
 * These implement the %release/net and %release/reg instructions. The
 * %release/net instruction applies to a net kind of functor by
 * sending the release/net command to the command port. (See vvp_net.h
 * for details.) The %release/reg instruction is the same, but sends
 * the release/reg command instead. These are very similar to the
 * %deassign instruction.
 */
static bool do_release_vec(vvp_code_t cp, bool net_flag)
{
      vvp_net_t*net = cp->net;
      unsigned base  = cp->bit_idx[0];
      unsigned width = cp->bit_idx[1];

      assert(net->fil);

      if (base >= net->fil->filter_size()) return true;
      if (base+width > net->fil->filter_size())
	    width = net->fil->filter_size() - base;

      bool full_sig = base == 0 && width == net->fil->filter_size();

      if (full_sig)
	    net->fil->force_unlink();
      else
	    net->fil->force_unlink_pv(base, width);

	/* Do we release all or part of the net? */
      vvp_net_ptr_t ptr (net, 0);
      if (full_sig) {
	    net->fil->release(ptr, net_flag);
      } else {
	    net->fil->release_pv(ptr, base, width, net_flag);
      }
      net->fun->force_flag(false);
	// M12B-fr: report the release to any cbRelease callbacks.
      net->fil->run_force_callbacks(cbRelease);

      return true;
}

/*
 * %ref/bind <formal>, <actual>
 *
 * Point a `ref' formal at the caller's variable (IEEE 1800-2017
 * 13.5.2). Emitted between the callee's %alloc and its %fork, so the
 * write context is already the callee's frame -- which is where the
 * binding belongs -- while the read context is still the caller's,
 * which is the frame a caller-local automatic actual lives in.
 */
bool of_REF_BIND(vthread_t, vvp_code_t cp)
{
      vvp_ref_signal_aa*formal =
	    dynamic_cast<vvp_ref_signal_aa*> (cp->net->fil);
      if (!formal) {
	    cerr << "%ref/bind error: the formal is not a ref signal." << endl;
	    assert(formal);
	    return true;
      }

      formal->bind(cp->net2, false);
      return true;
}

/*
 * %ref/bind/f <formal>, <companion>
 *
 * The same, for an actual that could not be named: the caller copied it
 * into a companion word in THIS frame, so that is where the target has
 * to be resolved.
 */
bool of_REF_BIND_F(vthread_t, vvp_code_t cp)
{
      vvp_ref_signal_aa*formal =
	    dynamic_cast<vvp_ref_signal_aa*> (cp->net->fil);
      if (!formal) {
	    cerr << "%ref/bind/f error: the formal is not a ref signal." << endl;
	    assert(formal);
	    return true;
      }

      formal->bind(cp->net2, true);
      return true;
}

/*
 * %ref/bind/pr <formal>, <pid>
 *
 * Bind a ref formal to property <pid> of the object popped from the
 * object stack (IEEE 1800-2017 13.5.2: the actual is the property's
 * storage, which lives in the object -- the binding holds the object,
 * so a later reassignment of the caller's handle variable does not
 * retarget the reference).
 */
bool of_REF_BIND_PR(vthread_t thr, vvp_code_t cp)
{
      vvp_object_t recv;
      thr->pop_object(recv);
      vvp_ref_signal_aa*formal =
	    dynamic_cast<vvp_ref_signal_aa*> (cp->net->fil);
      if (!formal) {
	    cerr << "%ref/bind/pr error: the formal is not a ref signal." << endl;
	    assert(formal);
	    return true;
      }
      formal->bind_prop(recv, cp->bit_idx[0]);
      return true;
}

/*
 * %ref/bind/el <formal>, <container-var>
 *
 * Bind a ref formal to element <index> (popped from the vec4 stack) of
 * the dynamic array or queue held by <container-var>. The captured
 * element cell follows a live queue element through index shifts and
 * retains its last value if the element is removed or the whole
 * container is replaced.
 */
bool of_REF_BIND_EL(vthread_t thr, vvp_code_t cp)
{
      vvp_vector4_t idxv = thr->pop_vec4();
      int64_t use_index = -1;
      vector4_to_value(idxv, use_index, true, false);
      vvp_ref_signal_aa*formal =
	    dynamic_cast<vvp_ref_signal_aa*> (cp->net->fil);
      if (!formal) {
	    cerr << "%ref/bind/el error: the formal is not a ref signal." << endl;
	    assert(formal);
	    return true;
      }
      vvp_object_t container;
      if (vvp_fun_signal_object*fun = signal_object_fun_(cp->net2))
            container = fun->peek_object();
      formal->bind_elem(container, use_index);
      return true;
}

/*
 * %ref/bind/w <array>, <formal>
 *
 * Bind a ref formal to word <index> (popped from the vec4 stack,
 * already normalized to the canonical word offset) of a static
 * unpacked array.
 */
bool of_REF_BIND_W(vthread_t thr, vvp_code_t cp)
{
      vvp_vector4_t idxv = thr->pop_vec4();
      int64_t use_index = -1;
      bool defined = vector4_to_value(idxv, use_index, true, false);
      vvp_ref_signal_aa*formal =
	    dynamic_cast<vvp_ref_signal_aa*> (cp->net2->fil);
      if (!formal) {
	    cerr << "%ref/bind/w error: the formal is not a ref signal." << endl;
	    assert(formal);
	    return true;
      }
      if (!defined || use_index < 0)
	    formal->bind_word(0, 0);
      else
	    formal->bind_word(cp->array, (unsigned)use_index);
      return true;
}

bool of_RELEASE_NET(vthread_t thr, vvp_code_t cp)
{
      force_pending_clear_(thr);
      return do_release_vec(cp, true);
}


bool of_RELEASE_REG(vthread_t thr, vvp_code_t cp)
{
      force_pending_clear_(thr);
      return do_release_vec(cp, false);
}

/* %release/reg/a <array>, <off-reg>, <width-reg>
 *
 * The canonical unpacked word address is in ix3. Compact arrays are
 * variables, so released bits retain their last forced visible value. */
bool of_RELEASE_REG_A(vthread_t thr, vvp_code_t cp)
{
      unsigned off_idx = cp->bit_idx[0];
      unsigned wid_idx = cp->bit_idx[1];
      int64_t address = thr->words[3].w_int;
      int64_t off = off_idx ? thr->words[off_idx].w_int : 0;
      int64_t wid = thr->words[wid_idx].w_int;
      force_pending_clear_(thr);

      if (thr->flags[4] != BIT4_0 || wid <= 0)
	    return true;
      vvp_array_t array = resolve_runtime_array_(cp, "%release/reg/a");
      if (!array || address < 0 || (uint64_t)address >= array->get_size()
	  || array->automatic_storage
	  || !array->is_forceable_vec4_array())
	    return true;
      unsigned word_wid = array->get_word_size();
      uint64_t use_wid = (uint64_t)wid;
      if (off < 0) {
	      /* Compute the magnitude without negating INT64_MIN, and subtract
	       * in unsigned space so a malformed bytecode operand cannot cause
	       * signed overflow. */
	    uint64_t below = (uint64_t)(-(off + 1)) + 1;
	    if (below >= use_wid)
		  return true;
	    use_wid -= below;
	    off = 0;
      }
      uint64_t use_off = (uint64_t)off;
      if (use_off >= word_wid)
	    return true;
      uint64_t available = word_wid - use_off;
      if (use_wid > available)
	    use_wid = available;

      array->release_word((unsigned)address, (unsigned)use_off,
			  (unsigned)use_wid);
      return true;
}

/* The type is 1 for registers and 0 for everything else. */
bool of_RELEASE_WR(vthread_t thr, vvp_code_t cp)
{
      vvp_net_t*net = cp->net;
      unsigned type  = cp->bit_idx[0];

      force_pending_clear_(thr);
      assert(net->fil);
      net->fil->force_unlink();

	// Send a command to this signal to unforce itself.
      vvp_net_ptr_t ptr (net, 0);
      net->fil->release(ptr, type==0);
	// M12B-fr: report the release to any cbRelease callbacks.
      net->fil->run_force_callbacks(cbRelease);
      return true;
}

bool of_REPLICATE(vthread_t thr, vvp_code_t cp)
{
      int rept = cp->number;
      vvp_vector4_t val = thr->pop_vec4();
      vvp_vector4_t res (val.size() * rept, BIT4_X);

      for (int idx = 0 ; idx < rept ; idx += 1) {
	    res.set_vec(idx * val.size(), val);
      }

      thr->push_vec4(res);

      return true;
}

static void poke_val(vthread_t fun_thr, unsigned depth, double val)
{
      fun_thr->parent->poke_real(depth, val);
}

static void poke_val(vthread_t fun_thr, unsigned depth, const string&val)
{
      fun_thr->parent->poke_str(depth, val);
}

static void poke_val(vthread_t fun_thr, unsigned depth, const vvp_object_t&val)
{
      fun_thr->parent->poke_object(depth, val);
}

static size_t get_max(vthread_t fun_thr, double&)
{
      return fun_thr->args_real.size();
}

static size_t get_max(vthread_t fun_thr, vvp_object_t&)
{
      return fun_thr->args_obj.size();
}

static size_t get_max(vthread_t fun_thr, string&)
{
      return fun_thr->args_str.size();
}

static size_t get_max(vthread_t fun_thr, vvp_vector4_t&)
{
      return fun_thr->args_vec4.size();
}

static unsigned get_depth(vthread_t fun_thr, size_t index, double&)
{
      return fun_thr->args_real[index];
}

static unsigned get_depth(vthread_t fun_thr, size_t index, string&)
{
      return fun_thr->args_str[index];
}

static unsigned get_depth(vthread_t fun_thr, size_t index, vvp_vector4_t&)
{
      return fun_thr->args_vec4[index];
}

static unsigned get_depth(vthread_t fun_thr, size_t index, vvp_object_t&)
{
      return fun_thr->args_obj[index];
}

static vthread_t get_func(vthread_t thr)
{
      vthread_t fun_thr = thr;

	/* Walk up until we reach the thread that owns the return slot.
	   An autofunction's fork body runs in the same vpiFunction scope as
	   the callf/exec_ufunc child, but was created by %fork so it has no
	   args_vec4/real/str.  Continue past such zero-slot threads to find
	   the actual return-slot owner. */
      while (fun_thr->parent_scope->get_type_code() != vpiFunction
	     || (fun_thr->args_vec4.empty()
	         && fun_thr->args_real.empty()
	         && fun_thr->args_str.empty()
	         && fun_thr->args_obj.empty())) {
	    assert(fun_thr->parent);
	    fun_thr = fun_thr->parent;
      }

      return fun_thr;
}

template <typename ELEM>
static bool ret(vthread_t thr, vvp_code_t cp)
{
      size_t index = cp->number;
      ELEM val;
      pop_value(thr, val, 0);

      vthread_t fun_thr = get_func(thr);
      assert(index < get_max(fun_thr, val));

      unsigned depth = get_depth(fun_thr, index, val);
	// Use the depth to put the value into the stack of
	// the parent thread.
      poke_val(fun_thr, depth, val);
      return true;
}

/*
 * %ret/real <index>
 */
bool of_RET_REAL(vthread_t thr, vvp_code_t cp)
{
      return ret<double>(thr, cp);
}

/*
 * %ret/str <index>
 */
bool of_RET_STR(vthread_t thr, vvp_code_t cp)
{
      return ret<string>(thr, cp);
}

/*
 * %ret/vec4 <index>, <offset>, <wid>
 */
bool of_RET_VEC4(vthread_t thr, vvp_code_t cp)
{
      size_t index = cp->number;
      unsigned off_index = cp->bit_idx[0];
      unsigned int wid = cp->bit_idx[1];
      vvp_vector4_t&val = thr->peek_vec4();

      vthread_t fun_thr = get_func(thr);
      assert(index < get_max(fun_thr, val));
      if (val.size() != wid) {
            // Compile-progress fallback: unresolved vec4 returns can appear
            // as width-0 values. Coerce silently to destination width.
            if (val.size() == 0) {
                  val.resize(wid, BIT4_X);
            } else {
            {
                  const char*fn = thr->parent_scope ? vpi_get_str(vpiFullName, thr->parent_scope) : "<unknown>";
                  cerr << "Warning: %ret/vec4 width mismatch (" << val.size()
                       << " != " << wid << "), coercing in " << fn << endl;
            }
            if (val.size() > wid) {
                  val = coerce_to_width(val, wid);
            } else {
                  val.resize(wid, BIT4_0);
            }
            }
      }
      unsigned depth = get_depth(fun_thr, index, val);

      int64_t off = off_index ? thr->words[off_index].w_int : 0;
      unsigned int sig_value_size = fun_thr->parent->peek_vec4(depth).size();

      if (off_index!=0 && thr->flags[4] != BIT4_0) {
	    thr->pop_vec4(1);
	    return true;
      }

      if (!resize_rval_vec(val, off, sig_value_size)) {
	    thr->pop_vec4(1);
	    return true;
      }

      if (off == 0 && val.size() == sig_value_size) {
	    fun_thr->parent->poke_vec4(depth, val);
      } else {
	    vvp_vector4_t tmp_dst = fun_thr->parent->peek_vec4(depth);
	    tmp_dst.set_vec(off, val);
	    fun_thr->parent->poke_vec4(depth, tmp_dst);
      }

      thr->pop_vec4(1);
      return true;
}

static void push_from_parent(vthread_t thr, vthread_t fun_thr, unsigned depth, double&)
{
      thr->push_real(fun_thr->parent->peek_real(depth));
}

static void push_from_parent(vthread_t thr, vthread_t fun_thr, unsigned depth, string&)
{
      thr->push_str(fun_thr->parent->peek_str(depth));
}

static void push_from_parent(vthread_t thr, vthread_t fun_thr, unsigned depth, vvp_vector4_t&)
{
      thr->push_vec4(fun_thr->parent->peek_vec4(depth));
}

static void push_from_parent(vthread_t thr, vthread_t fun_thr, unsigned depth, vvp_object_t&)
{
      thr->push_object(fun_thr->parent->peek_object(depth));
}

template <typename ELEM>
static bool retload(vthread_t thr, vvp_code_t cp)
{
      size_t index = cp->number;
      ELEM type;

      vthread_t fun_thr = get_func(thr);
      assert(index < get_max(fun_thr, type));

      unsigned depth = get_depth(fun_thr, index, type);
	// Use the depth to extract the values from the stack
	// of the parent thread.
      push_from_parent(thr, fun_thr, depth, type);
      return true;
}

/*
 * %retload/real <index>
 */
bool of_RETLOAD_REAL(vthread_t thr, vvp_code_t cp)
{
      return retload<double>(thr, cp);
}

/*
 * %retload/str <index>
 */
bool of_RETLOAD_STR(vthread_t thr, vvp_code_t cp)
{
      return retload<string>(thr, cp);
}

/*
 * Phase 63b/B6: %ret/obj <index>
 *
 * Pop an object handle from the current thread and write it into
 * the parent thread's object stack at the slot reserved for this
 * function's return value.  Mirrors %ret/real and %ret/str.
 */
bool of_RET_OBJ(vthread_t thr, vvp_code_t cp)
{
      return ret<vvp_object_t>(thr, cp);
}

/*
 * Phase 63b/B6: %retload/obj <index>
 *
 * Push a copy of the parent thread's return-slot object onto the
 * current thread's object stack.  Mirrors %retload/real and
 * %retload/str.
 */
bool of_RETLOAD_OBJ(vthread_t thr, vvp_code_t cp)
{
      return retload<vvp_object_t>(thr, cp);
}

/*
 * %retload/vec4 <index>
 */
bool of_RETLOAD_VEC4(vthread_t thr, vvp_code_t cp)
{
      return retload<vvp_vector4_t>(thr, cp);
}

/*
 * %scopy
 *
 * Pop the top item from the object stack, and shallow_copy() that item into
 * the new top of the object stack. This will copy at many items as needed
 * from the source object to fill the target object. If the target object is
 * larger then the source object, then some items will be left unchanged.
 *
 * The object may be any kind of object that supports shallow_copy(),
 * including dynamic arrays and class objects.
 */
bool of_SCOPY(vthread_t thr, vvp_code_t)
{
      vvp_object_t tmp;
      thr->pop_object(tmp);

      vvp_object_t&dest = thr->peek_object();
        // If it is null there is nothing to copy
      if (!tmp.test_nil())
	    dest.shallow_copy(tmp);

      return true;
}

static void thread_peek(vthread_t thr, double&value)
{
      value = thr->peek_real(0);
}

static void thread_peek(vthread_t thr, string&value)
{
      value = thr->peek_str(0);
}

static void thread_peek(vthread_t thr, vvp_vector4_t&value)
{
      value = thr->peek_vec4(0);
}

/* Fill the dynamic array at the top of the object stack with the scalar at
 * the top of its value stack. new[N]('{default:value}) uses this compact
 * operation so a run-time N does not need generated loop bytecode and a
 * large constant N does not duplicate the initializer expression. */
template <typename ELEM>
static bool fill_dar_obj(vthread_t thr, const char*opcode)
{
      ELEM value;
      thread_peek(thr, value);

      vvp_object_t&top = thr->peek_object();
      vvp_darray*darray = top.peek<vvp_darray>();
      if (!darray) {
	    fprintf(stderr, "vvp: malformed %s receiver is not a dynamic "
		    "array; fill ignored.\n", opcode);
	    return true;
	}

      for (size_t idx = 0 ; idx < darray->get_size() ; idx += 1)
	    darray->set_word((unsigned)idx, value);

      notify_mutated_object_root_(thr, top, thr->peek_object_source_net(0),
				  thr->peek_object_root(0), "fill-dar-obj");
      return true;
}

static bool fill_dar_stack_operands_(vthread_t thr, const char*opcode,
				      size_t vec4_need, size_t real_need,
				      size_t str_need, size_t obj_need)
{
      if (thr->vec4_stack_size() >= vec4_need
	  && thr->real_stack_size() >= real_need
	  && thr->str_stack_size() >= str_need
	  && thr->object_stack_size() >= obj_need)
	    return true;

      fprintf(stderr,
	    "vvp: malformed %s stack underflow (need vec4/real/string/object "
	    "%zu/%zu/%zu/%zu, have %zu/%zu/%zu/%zu); fill ignored.\n",
	    opcode, vec4_need, real_need, str_need, obj_need,
	    thr->vec4_stack_size(), thr->real_stack_size(),
	    thr->str_stack_size(), thr->object_stack_size());
      return false;
}

bool of_FILL_DAR_OBJ_REAL(vthread_t thr, vvp_code_t cp)
{
      (void)cp;
      if (!fill_dar_stack_operands_(thr, "%fill/dar/obj/real",
				    0, 1, 0, 1))
	    return true;
      return fill_dar_obj<double>(thr, "%fill/dar/obj/real");
}

bool of_FILL_DAR_OBJ_STR(vthread_t thr, vvp_code_t cp)
{
      (void)cp;
      if (!fill_dar_stack_operands_(thr, "%fill/dar/obj/str",
				    0, 0, 1, 1))
	    return true;
      return fill_dar_obj<string>(thr, "%fill/dar/obj/str");
}

bool of_FILL_DAR_OBJ_VEC4(vthread_t thr, vvp_code_t cp)
{
      (void)cp;
      if (!fill_dar_stack_operands_(thr, "%fill/dar/obj/vec4",
				    1, 0, 0, 1))
	    return true;

      vvp_darray*darray = thr->peek_object().peek<vvp_darray>();
      if (darray) {
	    unsigned expected = darray->vec4_word_width();
	    unsigned actual = thr->peek_vec4(0).size();
	    if (!expected) {
		  fprintf(stderr, "vvp: malformed %%fill/dar/obj/vec4 receiver "
			  "does not have integral elements; fill ignored.\n");
		  return true;
	    }
	    if (actual != expected) {
		  fprintf(stderr, "vvp: malformed %%fill/dar/obj/vec4 value "
			  "width %u does not match element width %u; fill "
			  "ignored.\n", actual, expected);
		  return true;
	    }
      }
      return fill_dar_obj<vvp_vector4_t>(thr, "%fill/dar/obj/vec4");
}

/* Object-backed array elements include both reference-semantic class handles
 * and value-semantic aggregates/containers. value_copy_element() preserves
 * a class handle while making the independent copy required for a struct,
 * dynamic array, or associative-array value in each destination slot. */
bool of_FILL_DAR_OBJ_OBJ(vthread_t thr, vvp_code_t)
{
      if (!fill_dar_stack_operands_(thr, "%fill/dar/obj/obj",
				    0, 0, 0, 2))
	    return true;

      vvp_darray*darray = thr->peek_object(1).peek<vvp_darray>();
      if (!darray) {
	    fprintf(stderr, "vvp: malformed %%fill/dar/obj/obj receiver is not "
		    "a dynamic array; fill ignored.\n");
	    return true;
      }

      vvp_object_t value;
      thr->pop_object(value);

      vvp_object_t&top = thr->peek_object();

      for (size_t idx = 0 ; idx < darray->get_size() ; idx += 1)
	    darray->set_word((unsigned)idx, value.value_copy_element());

      notify_mutated_object_root_(thr, top, thr->peek_object_source_net(0),
				  thr->peek_object_root(0), "fill-dar-obj-obj");
      return true;
}

/* Phase 63b/runtime-cleanup: silently absorb vec4-into-object-queue
 * code-gen mismatches.  See store_dar() for the rationale. */
template<typename ELEM>
static inline bool set_dar_obj_skip_obj_queue_(ELEM&)
{
      /* Default: no skip. */
      return false;
}
template<>
inline bool set_dar_obj_skip_obj_queue_(vvp_vector4_t&)
{
      return true;
}

template <typename ELEM>
static bool set_dar_obj(vthread_t thr, vvp_code_t cp)
{
      int64_t adr = thr->words[cp->number].w_int;

      ELEM value;
      thread_peek(thr, value);

      vvp_object_t&top = thr->peek_object();
      if (vvp_queue*queue = top.peek<vvp_queue>()) {
	    adr = darray_canonical_index_(queue, adr);
	    if (adr < 0) return true;
	    if (set_dar_obj_skip_obj_queue_(value) &&
	        dynamic_cast<vvp_queue_object*>(queue)) {
		  /* No-op: vec4-into-object-queue silently absorbed. */
	    } else {
		  queue->set_word_max(adr, value, 0);
	    }
      } else {
	    vvp_darray*darray = top.peek<vvp_darray>();
	    if (!darray) return true;
	    adr = darray_canonical_index_(darray, adr);
	    if (adr < 0) return true;
	    if (set_dar_obj_skip_obj_queue_(value) &&
	        dynamic_cast<vvp_darray_object*>(darray)) {
		  /* No-op. */
	    } else {
		  darray->set_word(adr, value);
	    }
      }
      notify_mutated_object_root_(thr, top, thr->peek_object_source_net(0),
                                  thr->peek_object_root(0), "set-dar-obj");
      return true;
}

/*
 * %set/dar/obj/real <index>
 */
bool of_SET_DAR_OBJ_REAL(vthread_t thr, vvp_code_t cp)
{
      return set_dar_obj<double>(thr, cp);
}

/*
 * %set/dar/obj/obj <index>
 */
bool of_SET_DAR_OBJ_OBJ(vthread_t thr, vvp_code_t cp)
{
      int64_t adr = thr->words[cp->number].w_int;

      vvp_object_t value;
      thr->pop_object(value);

      vvp_object_t&top = thr->peek_object();
      if (vvp_queue*queue = top.peek<vvp_queue>()) {
	    adr = darray_canonical_index_(queue, adr);
	    if (adr < 0) return true;
	    queue->set_word_max(adr, value, 0);
      } else {
	    vvp_darray*darray = top.peek<vvp_darray>();
	    assert(darray);
	    adr = darray_canonical_index_(darray, adr);
	    if (adr < 0) return true;
	    darray->set_word(adr, value);
      }
      notify_mutated_object_root_(thr, top, thr->peek_object_source_net(0),
                                  thr->peek_object_root(0), "set-dar-obj-obj");
      return true;
}

/*
 * %set/dar/obj/str <index>
 */
bool of_SET_DAR_OBJ_STR(vthread_t thr, vvp_code_t cp)
{
      return set_dar_obj<string>(thr, cp);
}

/*
 * %set/dar/obj/vec4 <index>
 */
bool of_SET_DAR_OBJ_VEC4(vthread_t thr, vvp_code_t cp)
{
      return set_dar_obj<vvp_vector4_t>(thr, cp);
}

/*
 * %shiftl <idx>
 *
 * Pop the operand, then push the result.
 */
/*
 * %setbits/vec4 <off>, <wid>
 * %setbits/vec4/x <off_reg>, <wid>
 *
 * Read-modify-write on the vec4 stack: pops a <wid>-bit value and merges
 * it into the vector BELOW it at bit offset <off> (immediate, or read
 * from index register <off_reg> for the /x form). The target is a fixed-width
 * container element, so out-of-range writes are clipped rather than extending
 * the stack vector. Generic building block for container-element partial
 * stores (e.g. assoc[key][m:l] = v).
 */
static bool setbits_vec4_(vthread_t thr, int64_t off, unsigned wid)
{
      vvp_vector4_t val = thr->pop_vec4();
      vvp_vector4_t&tgt = thr->peek_vec4();

      if (val.size() > wid)
	    val = val.subvalue(0, wid);
      if (!resize_rval_vec(val, off, tgt.size()))
	    return true;
      tgt.set_vec((unsigned)off, val);
      return true;
}

bool of_SETBITS_VEC4(vthread_t thr, vvp_code_t cp)
{
      return setbits_vec4_(thr, cp->bit_idx[0], cp->bit_idx[1]);
}

bool of_SETBITS_VEC4_X(vthread_t thr, vvp_code_t cp)
{
      unsigned off_reg = cp->bit_idx[0];
      assert(off_reg < vthread_s::WORDS_COUNT);
      if (thr->flags[4] != BIT4_0) {
	    /* Pop the replacement while retaining the target below it. */
	    thr->pop_vec4(1);
	    return true;
      }
      return setbits_vec4_(thr, thr->words[off_reg].w_int, cp->bit_idx[1]);
}

bool of_SHIFTL(vthread_t thr, vvp_code_t cp)
{
      int use_index = cp->number;
      uint64_t shift = thr->words[use_index].w_uint;

      vvp_vector4_t&val = thr->peek_vec4();
      unsigned wid  = val.size();

      if (thr->flags[4] == BIT4_1) {
	      // The result is 'bx if the shift amount is undefined
	    val = vvp_vector4_t(wid, BIT4_X);

      } else if (thr->flags[4] == BIT4_X || shift >= wid) {
	      // Shift is so big that all value is shifted out. Write
	      // a constant 0 result.
	    val = vvp_vector4_t(wid, BIT4_0);

      } else if (shift > 0) {
	    vvp_vector4_t blk = val.subvalue(0, wid-shift);
	    vvp_vector4_t tmp (shift, BIT4_0);
	    val.set_vec(0, tmp);
	    val.set_vec(shift, blk);
      }

      return true;
}

/*
 * %shiftr <idx>
 * This is an unsigned right shift. The <idx> is a number that selects
 * the index register with the amount of the shift. This instruction
 * checks flag bit 4, which will be true if the shift is invalid.
 */
bool of_SHIFTR(vthread_t thr, vvp_code_t cp)
{
      int use_index = cp->number;
      uint64_t shift = thr->words[use_index].w_uint;

      vvp_vector4_t val = thr->pop_vec4();
      unsigned wid  = val.size();

      if (thr->flags[4] == BIT4_1) {
	    val = vvp_vector4_t(wid, BIT4_X);

      } else if (thr->flags[4] == BIT4_X || shift > wid) {
	    val = vvp_vector4_t(wid, BIT4_0);

      } else if (shift > 0) {
	    vvp_vector4_t blk = val.subvalue(shift, wid-shift);
	    vvp_vector4_t tmp (shift, BIT4_0);
	    val.set_vec(0, blk);
	    val.set_vec(wid-shift, tmp);
      }

      thr->push_vec4(val);
      return true;
}

/*
 *  %shiftr/s <wid>
 */
bool of_SHIFTR_S(vthread_t thr, vvp_code_t cp)
{
      int use_index = cp->number;
      uint64_t shift = thr->words[use_index].w_uint;

      vvp_vector4_t val = thr->pop_vec4();
      unsigned wid  = val.size();

      vvp_bit4_t sign_bit = val.value(val.size()-1);

      if (thr->flags[4] == BIT4_1) {
	    val = vvp_vector4_t(wid, BIT4_X);

      } else if (thr->flags[4] == BIT4_X || shift > wid) {
	    val = vvp_vector4_t(wid, sign_bit);

      } else if (shift > 0) {
	    vvp_vector4_t blk = val.subvalue(shift, wid-shift);
	    vvp_vector4_t tmp (shift, sign_bit);
	    val.set_vec(0, blk);
	    val.set_vec(wid-shift, tmp);
      }

      thr->push_vec4(val);
      return true;
}

/*
 * %split/vec4 <wid>
 *   Pop 1 value,
 *   Take <wid> bits from the lsb,
 *   Push the remaining msb,
 *   Push the lsb.
 */
bool of_SPLIT_VEC4(vthread_t thr, vvp_code_t cp)
{
      unsigned lsb_wid = cp->number;

      const vvp_vector4_t*cur = thr->safe_peek_vec4(0);
      if (!cur) {
	    cerr << thr->get_fileline()
		 << "VVP error: %split/vec4 requires one vec4 stack value."
		 << endl;
	    return false;
      }
      if (lsb_wid > cur->size()) {
	    cerr << thr->get_fileline() << "VVP error: %split/vec4 requests "
		 << lsb_wid << " bits from a " << cur->size()
		 << "-bit value." << endl;
	    return false;
      }

      vvp_vector4_t&val = thr->peek_vec4();

      vvp_vector4_t lsb = val.subvalue(0, lsb_wid);
      val = val.subvalue(lsb_wid, val.size()-lsb_wid);

      thr->push_vec4(lsb);
      return true;
}

/*
 * The following are used to allow the darray templates to print correctly.
 */
inline static string get_darray_type(double&)
{
      return "darray<real>";
}

inline static string get_darray_type(string&)
{
      return "darray<string>";
}

inline static string get_darray_type(const vvp_vector4_t&value)
{
      ostringstream buf;
      buf << "darray<vector[" << value.size() << "]>";
      string res = buf.str();
      return res;
}

/*
 * The following are used to allow a common template to be written for
 * darray real/string/vec4 operations
 */
inline static void dar_pop_value(vthread_t thr, double&value)
{
      value = thr->pop_real();
}

inline static void dar_pop_value(vthread_t thr, string&value)
{
      value = thr->pop_str();
}

inline static void dar_pop_value(vthread_t thr, vvp_vector4_t&value)
{
      value = thr->pop_vec4();
}

template <typename ELEM>
static bool store_dar(vthread_t thr, vvp_code_t cp)
{
      int64_t adr = thr->words[3].w_int;
      ELEM value;
	// FIXME: Can we get the size of the underlying array element
	//        and then use the normal pop_value?
      dar_pop_value(thr, value);

      vvp_net_t*net = cp->net;
      assert(net);

      vvp_fun_signal_object*obj = dynamic_cast<vvp_fun_signal_object*> (net->fun);
      assert(obj);

      vvp_darray*darray = obj->get_object().peek<vvp_darray>();
      adr = darray_canonical_index_(darray, adr);

      if (adr < 0)
	    cerr << thr->get_fileline()
	         << "Warning: cannot write to a negative " << get_darray_type(value)
	         << " index (" << adr << ")." << endl;
      else if (thr->flags[4] != BIT4_0)
	    cerr << thr->get_fileline()
	         << "Warning: cannot write to an undefined " << get_darray_type(value)
	         << " index." << endl;
      else if (darray) {
	    /* Phase 63b/runtime-cleanup: object queues silently
	       reject vec4 stores because the codegen sometimes emits
	       %store/dar/vec4 for inner-statement arms that don't
	       actually fire (e.g. dead-code branch in foreach over
	       polymorphic queue).  Skip rather than warn since the
	       value can't meaningfully convert. */
	    if (dynamic_cast<vvp_queue_object*>(darray) ||
	        dynamic_cast<vvp_darray_object*>(darray)) {
		  /* No-op: type mismatch silently absorbed. */
	    } else {
		  darray->set_word(adr, value);
	    }
      } else
	    cerr << thr->get_fileline()
	         << "Warning: cannot write to an undefined " << get_darray_type(value)
	         << "." << endl;

      if (darray)
            notify_mutated_object_signal_(thr, net, "store-dar");

      return true;
}

/*
 * %store/dar/real <var>
 */
bool of_STORE_DAR_R(vthread_t thr, vvp_code_t cp)
{
      return store_dar<double>(thr, cp);
}

/*
 * %store/dar/str <var>
 */
bool of_STORE_DAR_STR(vthread_t thr, vvp_code_t cp)
{
      return store_dar<string>(thr, cp);
}

/*
 * %store/dar/vec4 <var>
 */
bool of_STORE_DAR_VEC4(vthread_t thr, vvp_code_t cp)
{
      return store_dar<vvp_vector4_t>(thr, cp);
}

/*
 * %store/dar/vec4/off <var>, <off_reg>, <wid>
 *
 * Read-modify-write a part/bit-select into a dynamic-array (or queue)
 * element whose base type is a packed vector: load element[reg3], splice
 * the width-<wid> value on the vec4 stack into it at the (already
 * element-normalized) bit offset held in integer register <off_reg>, and
 * store the element back. Implements `d[i][b] = v` and `q[i][m:l] = v`,
 * including a run-time-variable bit index. The element address is in
 * integer register 3 (as for %store/dar/vec4); flag 4 marks an undefined
 * address. <wid> is the value width.
 */
bool of_STORE_DAR_VEC4_OFF(vthread_t thr, vvp_code_t cp)
{
      int64_t adr = thr->words[3].w_int;
      int64_t soff = thr->words[cp->bit_idx[0]].w_int;
      unsigned wid = cp->bit_idx[1];
      vvp_vector4_t value = thr->pop_vec4();

      if (soff < 0) {
	    cerr << thr->get_fileline()
	         << "Warning: negative bit offset into a darray element "
	            "part-select is ignored." << endl;
	    return true;
      }
      unsigned off = (unsigned) soff;

      vvp_net_t*net = cp->net;
      assert(net);

      vvp_fun_signal_object*obj = dynamic_cast<vvp_fun_signal_object*> (net->fun);
      assert(obj);

      vvp_darray*darray = obj->get_object().peek<vvp_darray>();
      adr = darray_canonical_index_(darray, adr);

      if (adr < 0)
	    cerr << thr->get_fileline()
	         << "Warning: cannot write to a negative darray index ("
	         << adr << ")." << endl;
      else if (thr->flags[4] != BIT4_0)
	    cerr << thr->get_fileline()
	         << "Warning: cannot write to an undefined darray index." << endl;
      else if (darray) {
	    vvp_vector4_t elem;
	    darray->get_word(adr, elem);
	      // Safety net: a never-written element may come back narrower
	      // than the splice needs; widen it to all-x so set_vec lands.
	    if (elem.size() < off + wid) {
		  vvp_vector4_t wider (off + wid, BIT4_X);
		  if (elem.size() > 0)
			wider.set_vec(0, elem);
		  elem = wider;
	    }
	    elem.set_vec(off, value.size()==wid ? value
					        : value.subvalue(0, wid));
	    darray->set_word(adr, elem);
      } else
	    cerr << thr->get_fileline()
	         << "Warning: cannot write to an undefined darray." << endl;

      if (darray)
	    notify_mutated_object_signal_(thr, net, "store-dar-off");

      return true;
}

/*
 * %store/dar/obj <var>
 * Store an object into a dynamic array element
 */
bool of_STORE_DAR_OBJ(vthread_t thr, vvp_code_t cp)
{
      int64_t adr = thr->words[3].w_int;
      vvp_object_t value;
      thr->pop_object(value);
      container_value_copy_(value);

      vvp_net_t*net = cp->net;
      assert(net);

      vvp_fun_signal_object*obj = dynamic_cast<vvp_fun_signal_object*> (net->fun);
      assert(obj);

      vvp_darray*darray = obj->get_object().peek<vvp_darray>();
      adr = darray_canonical_index_(darray, adr);

      if (adr < 0)
	    cerr << thr->get_fileline()
	         << "Warning: cannot write to a negative darray<object>"
	         << " index (" << adr << ")." << endl;
      else if (thr->flags[4] != BIT4_0)
	    cerr << thr->get_fileline()
	         << "Warning: cannot write to an undefined darray<object>"
	         << " index." << endl;
      else if (darray)
	    darray->set_word(adr, value);
      else
	    cerr << thr->get_fileline()
	         << "Warning: cannot write to an undefined darray<object>"
	         << "." << endl;

      if (darray)
            notify_mutated_object_signal_(thr, net, "store-dar-obj");

      return true;
}

bool of_STORE_OBJ(vthread_t thr, vvp_code_t cp)
{
	/* set the value into port 0 of the destination. */
      vvp_net_ptr_t ptr (cp->net, 0);
      vvp_net_t*src_root_net = thr->peek_object_source_net(0);
      vvp_object_t src_root_obj = thr->peek_object_root(0);

      vvp_object_t val;
      thr->pop_object(val);

      static int trace_store_obj_enabled = -1;
      if (trace_store_obj_enabled < 0) {
            const char*env = getenv("IVL_STORE_OBJ_TRACE");
            trace_store_obj_enabled = (env && *env && strcmp(env, "0") != 0) ? 1 : 0;
      }
      if (trace_store_obj_enabled) {
            const char*scope_name = (thr && thr->parent_scope)
                                  ? vpi_get_str(vpiFullName, thr->parent_scope) : 0;
            const char*env = getenv("IVL_STORE_OBJ_TRACE");
            bool trace_this = true;
            if (env && *env
                && strcmp(env, "1") != 0 && strcmp(env, "ALL") != 0 && strcmp(env, "*") != 0) {
                  trace_this = (scope_name && strstr(scope_name, env));
            }
            if (trace_this) {
                  const char*fun_kind = "other";
                  if (cp->net && cp->net->fun) {
                        if (dynamic_cast<vvp_fun_signal_object_sa*>(cp->net->fun))
                              fun_kind = "object_sa";
                        else if (dynamic_cast<vvp_fun_signal_object_aa*>(cp->net->fun))
                              fun_kind = "object_aa";
                  }
                  fprintf(stderr,
                          "trace store_obj scope=%s net=%p fun=%s val_nil=%d val=%p class=%s wt=%p rd=%p\n",
                          scope_name ? scope_name : "<unknown>",
                          (void*)cp->net, fun_kind, val.test_nil() ? 1 : 0,
                          val.peek<vvp_object>(),
                          object_trace_class_(val),
                          thr ? thr->wt_context : 0, thr ? thr->rd_context : 0);
            }
      }

      vvp_send_object(ptr, val, ensure_write_context_(thr, "store-obj"));
      if (vvp_fun_signal_object*fun = signal_object_fun_(cp->net)) {
            /* If the incoming provenance refers to a different object than
             * the handle we are storing, this assignment creates a new alias
             * boundary and the destination handle must become the canonical
             * wakeup root for later in-place mutations. */
            if (!src_root_net || src_root_obj.test_nil() || src_root_obj != val) {
                  src_root_net = cp->net;
                  src_root_obj = val;
            }
            fun->set_root_provenance(src_root_net, src_root_obj,
                                     ensure_write_context_(thr, "store-obj-root"));
      }

      return true;
}

/*
 * Activate the declared-index view on a fixed array that has been
 * materialized as nested darray objects. Each multidimensional word owns
 * its own child object, so walk every child rather than only a prototype.
 */
static void activate_open_array_indices_(vvp_darray*array)
{
      if (!array || !array->dpi_has_decl_range())
	    return;

      array->sv_set_declared_indexing(true);
      vvp_darray_object*objects = dynamic_cast<vvp_darray_object*>(array);
      if (!objects)
	    return;

      for (size_t idx = 0 ; idx < objects->get_size() ; idx += 1) {
	    vvp_object_t word;
	    objects->get_word((unsigned)idx, word);
	    activate_open_array_indices_(word.peek<vvp_darray>());
      }
}

/*
 * %store/obj/open <signal>
 *
 * Store through the ordinary object-signal infrastructure, but first mark
 * a materialized fixed-array actual as the declared-index view used by an
 * SV/DPI open-array formal. The range metadata remains passive for ordinary
 * fixed-to-dynamic assignments.
 */
bool of_STORE_OBJ_OPEN(vthread_t thr, vvp_code_t cp)
{
      vvp_darray*array = thr->peek_object().peek<vvp_darray>();
      if (array && !array->sv_uses_declared_indexing())
	    reverse_descending_fixed_dimensions_(array);
      activate_open_array_indices_(array);
      return of_STORE_OBJ(thr, cp);
}

/*
 * %store/obja <array-label> <index>
 */
bool of_STORE_OBJA(vthread_t thr, vvp_code_t cp)
{
      unsigned idx = cp->bit_idx[0];
      vvp_array_t array = resolve_runtime_array_(cp, "%store/obja");

      vvp_object_t val;
      thr->pop_object(val);

	/* The RHS and address expression have already been evaluated, and the RHS
	 * must be consumed even when the outer array index is invalid. An
	 * undefined index leaves a recovery value (commonly zero) in the integer
	 * word and marks flag 4; using the word without the flag check corrupts a
	 * valid slot instead of ignoring the write. Explicitly bound-check as well
	 * so negative or too-large run-time canonical addresses are no-ops. */
      if (!array || thr->flags[4] != BIT4_0)
	    return true;

      unsigned adr = thr->words[idx].w_int;
      if (adr >= array->get_size())
	    return true;

      array->set_word(adr, val);

      return true;
}

