/*
 * %store/prop/obj <pid>, <idx>
 *
 * Pop an object value from the object stack, and store the value into
 * the property of the object references by the top of the stack. Do NOT
 * pop the object stack.
 */
bool of_STORE_PROP_OBJ(vthread_t thr, vvp_code_t cp)
{
      size_t pid = cp->number;
      unsigned idx = cp->bit_idx[0];

      if (idx != 0) {
	    assert(idx < vthread_s::WORDS_COUNT);
	    idx = thr->words[idx].w_uint;
      }

      vvp_object_t val;
      thr->pop_object(val);

      vvp_object_t&obj = thr->peek_object();
      vvp_cobject*cobj = obj.peek<vvp_cobject>();
      vvp_vinterface*vif_base = obj.peek<vvp_vinterface>();
      bool has_propobj = cobj != 0 || vif_base != 0;
      prop_trace_log_(thr, "%store/prop/obj", pid, idx, obj, has_propobj);
      if (!has_propobj) {
	      // Compile-progress fallback: storing into an unresolved/null class
	      // handle is a no-op.
	    return true;
      }

      size_t prop_count = 0;
      if (!prop_pid_in_range_(obj, pid, &prop_count)) {
            static bool warned = false;
            if (!warned) {
                  cerr << thr->get_fileline()
                       << "Warning: %store/prop/obj pid=" << pid
                       << " out of range for receiver class "
                       << prop_trace_receiver_class_(obj)
                       << " (size=" << prop_count << ")"
                       << "; ignoring write."
                       << " scope=" << scope_name_or_unknown_(thr ? thr->parent_scope : 0)
                       << endl;
                  warned = true;
            }
            return true;
      }

      if (cobj)
	    cobj->set_object(pid, val, idx);
      else
	    vif_base->set_object(pid, val, idx);
      notify_mutated_object_root_(thr, obj, thr->peek_object_source_net(0),
                                  thr->peek_object_root(0), "store-prop-obj");

      return true;
}

/*
 * %store/prop/arr/dar <pid>
 *
 * Copy a nested dynamic-array value back into an inline fixed-array
 * property. Pop the value and leave the receiver on the object stack,
 * matching %store/prop/obj.
 */
bool of_STORE_PROP_ARR_DAR(vthread_t thr, vvp_code_t cp)
{
      size_t pid = cp->number;
      vvp_object_t val;
      thr->pop_object(val);

      vvp_object_t&obj = thr->peek_object();
      fixed_prop_receiver_t recv = {
	    obj.peek<vvp_cobject>(), obj.peek<vvp_vinterface>()
      };
      const class_type*defn = recv.defn();
      vvp_darray*array = val.peek<vvp_darray>();
      if (!defn || pid >= defn->property_count()
	  || defn->property_dimensions(pid).empty())
	    return true;

      fixed_array_shape_mismatch_t mismatch;
      if (!fixed_array_source_shape_matches_(
		array, defn->property_dimensions(pid), 0, mismatch)) {
	    report_fixed_array_shape_mismatch_(mismatch);
	    return true;
      }

      size_t flat = 0;
      fixed_prop_copy_back_(recv, pid, array,
			    defn->property_dimensions(pid), 0, flat);
      notify_mutated_object_root_(thr, obj, thr->peek_object_source_net(0),
				  thr->peek_object_root(0),
				  "store-prop-arr-dar");
      return true;
}

static void pop_prop_val(vthread_t thr, double&val, unsigned)
{
      val = thr->pop_real();
}

static void pop_prop_val(vthread_t thr, string&val, unsigned)
{
      val = thr->pop_str();
}

static void pop_prop_val(vthread_t thr, vvp_vector4_t&val, unsigned wid)
{
      val = thr->pop_vec4();
      assert(val.size() >= wid);
      val.resize(wid);
}

