template <typename ELEM, class QTYPE>
static bool store_qobj(vthread_t thr, vvp_code_t cp, unsigned wid=0)
{
// FIXME: Can we actually use wid here?
      (void)wid;
      vvp_net_t*net = cp->net;

      vvp_queue*queue = get_queue_object<QTYPE>(thr, net);
      assert(queue);

      vvp_object_t src;
      thr->pop_object(src);

	// If it is null just clear the queue
      if (src.test_nil()) {
	    queue->erase_tail(0);
	    queue->reset_passive_value_metadata();
      } else {
	    unsigned max_size = thr->words[cp->bit_idx[0]].w_int;
	    queue->copy_elems(src, max_size);
	    if (vvp_darray*src_container = src.peek<vvp_darray>())
		  src_container->copy_passive_value_metadata_to(queue);
      }
      notify_mutated_object_signal_(thr, net, "store-qobj");

      return true;
}

/*
 * %store/qobj/obj <var-label>, <max-idx>
 * Whole-container assignment into a queue of objects. Copies the
 * source elements into the destination queue (value semantics per
 * IEEE 1800-2017 7.9.9); the per-element policy in copy_elems keeps
 * class handles shared while containers and structs copy by value.
 */
bool of_STORE_QOBJ_OBJ(vthread_t thr, vvp_code_t cp)
{
      return store_qobj<vvp_object_t, vvp_queue_object>(thr, cp);
}

